# ==========================================
# INDETERMINATE RESULTS
# ==========================================
# A doctrinal question can fail to produce a value for several different
# reasons. Keep that state in the engine instead of encoding it as a string,
# zero or False: those substitutes can silently enter arithmetic and Boolean
# tests. The page turns this object into ordinary display text at its
# rendering boundary.
INDETERMINATE_STATUSES = frozenset({'unavailable', 'unresolved', 'unassigned', 'not decided'})


@dataclass(frozen=True)
class UnresolvedResult:
    """An immutable result for a question the adopted rules do not settle.

    ``alternatives`` names the readings that remain open; each item is a
    ``(name, value)`` pair so callers can preserve numbers and booleans as
    values rather than flattening them into prose.
    """

    reason: str
    source: str
    alternatives: tuple = ()
    status: str = 'unresolved'
    display_label: str = ''
    display_alternatives: bool = True

    def __post_init__(self):
        if self.status not in INDETERMINATE_STATUSES:
            raise ValueError(f"unknown indeterminate status: {self.status!r}")
        object.__setattr__(self, 'alternatives', tuple((str(name), value) for name, value in self.alternatives))

    def __bool__(self):
        raise TypeError(f"{self.status} result has no truth value; resolve or display it explicitly")


@dataclass(frozen=True)
class YearsOutcome:
    """One complete result from a planetary-years route.

    Conditional years keep the deciding sentence, grade, number, and unit
    together so a consumer cannot accidentally display or rank only the
    numeric part of one alternative.
    """

    sentence: str | None
    grade: str | None
    number: float | None
    unit: str | None
    text: str


def _same_years_outcome(left, right):
    """Whether two routes settle the same grant despite different steps."""
    return (isinstance(left, YearsOutcome) and isinstance(right, YearsOutcome)
            and (left.sentence, left.grade, left.number, left.unit)
            == (right.sentence, right.grade, right.number, right.unit))


def is_unresolved(value):
    return isinstance(value, UnresolvedResult)


def doctrinal_and(*values):
    """Three-valued conjunction: known False settles it; otherwise an
    indeterminate operand survives. Only booleans and UnresolvedResult are
    admitted so a number or string cannot acquire a truth value here."""
    unknown = None
    for value in values:
        if value is False:
            return False
        if is_unresolved(value):
            if unknown is None:
                unknown = value
        elif value is not True:
            raise TypeError('doctrinal_and accepts only bool or UnresolvedResult values')
    return unknown if unknown is not None else True


def doctrinal_or(*values):
    """Three-valued disjunction: known True settles it; otherwise an
    indeterminate operand survives."""
    unknown = None
    for value in values:
        if value is True:
            return True
        if is_unresolved(value):
            if unknown is None:
                unknown = value
        elif value is not False:
            raise TypeError('doctrinal_or accepts only bool or UnresolvedResult values')
    return unknown if unknown is not None else False

# Connection uncertainty is evaluated at the outer judgment boundary. Each
# branch is a permitted Boolean completion of a missing connection fact, not
# a doctrinal ruling. Repeated uses of the same fact share the same decision.
# Nested evaluators run within that branch, so counts and exclusions are
# calculated before alternative outcomes are compared.
_CONNECTION_EVALUATION = threading.local()


class _ConnectionChoice(BaseException):
    def __init__(self, key, result, options=(False, True)):
        self.key, self.result, self.options = key, result, options


def _connection_decision(row, value):
    decisions = getattr(_CONNECTION_EVALUATION, 'decisions', None)
    if not is_unresolved(value) or decisions is None:
        return value
    if row.get('strike_tie') and 'equally placed' in value.reason:
        key = ('strike first body', row['body_connection_from'], row['strike_tie'])
        if key not in decisions:
            raise _ConnectionChoice(key, value, tuple(p for p, _ in row['strike_tie']))
        return decisions[key] == row['body_connection_to']
    positions = row.get('positions', (None, None))
    pair = tuple(sorted(((row['p1'], positions[0]), (row['p2'], positions[1]))))
    key = (reading('CONNECTION_PROFILE'), pair, row.get('deviation'), row.get('relative_speed'), value.reason)
    if key not in decisions:
        raise _ConnectionChoice(key, value)
    return decisions[key]


def _connection_unknown(values, reason='the result depends on an unresolved connection'):
    unique = []
    for value in values:
        if not any(repr(value) == repr(v) for v in unique):
            unique.append(value)
    if len(unique) == 1:
        return unique[0]
    return UnresolvedResult(reason, 'Sahl, The Introduction Ch. 3, 7–10, 20–21',
        alternatives=tuple((f'permitted outcome {i + 1}', v) for i, v in enumerate(unique)),
        display_alternatives=all(isinstance(v, (str, int, float, bool, type(None))) for v in unique))


# A list of labels whose outcomes disagree is split label by label (the
# owner's ruling of 2026-09-25, option 1): a label present in every outcome is
# settled and stays in its list; a label present in only some goes to the
# list's Unresolved channel as an UnresolvedResult naming the connection it
# depends on. Nothing is dropped. The channel is always "Unresolved " + the
# field's name, but only the fields below have one, each because a page or
# the export renders it; every other list of strings still becomes one
# UnresolvedResult when the outcomes disagree (see the list in the test file
# tests/test_label_merge_2026_09_25.py).
_LABEL_CHANNELS = {
    # Planetary Condition (evaluate_abu_mashar_condition): its table, details
    # line and export.
    'Positive Labels': 'Unresolved Positive Labels',
    'Negative Labels': 'Unresolved Negative Labels',
    # Sahl's Corruption of the Moon (evaluate_corruption_of_the_moon): its
    # Defects cell and export.
    'labels': 'Unresolved labels',
    # One Strength or Weakness testimony's facts (evaluate_strength_of_planets,
    # evaluate_weakness_of_planets): the tick grids' row detail and the export.
    'facts': 'Unresolved facts',
}


def _connection_names(key):
    """The planets of one undecided connection, from its decision key."""
    if isinstance(key, tuple) and key and key[0] == 'strike first body':
        names = [key[1]] + [planet for planet, _ in key[2]]
    elif isinstance(key, tuple) and len(key) > 1 and isinstance(key[1], tuple):
        names = [part[0] for part in key[1] if isinstance(part, tuple) and part]
    else:
        names = []
    names = in_planet_order(set(n for n in names if isinstance(n, str)))
    return ' and '.join(names) if names else ''


def _connection_context_text(keys, context):
    """'an unresolved connection between X and Y (reason)' for the decision
    keys a value depends on, in first-seen order."""
    choices = context[1] if context else {}
    parts = []
    for key in keys:
        names = _connection_names(key)
        result = choices.get(key)
        part = f"between {names}" if names else ''
        if result is not None:
            part = f"{part} ({result.reason})" if part else f"({result.reason})"
        if part and part not in parts:
            parts.append(part)
    if not parts:
        return 'an unresolved connection'
    return 'an unresolved connection ' + '; '.join(parts)


def _connection_source(keys, context):
    choices = context[1] if context else {}
    sources = list(dict.fromkeys(choices[k].source for k in keys if k in choices))
    return '; '.join(sources) or 'Sahl, The Introduction Ch. 3, 7–10, 20–21'


def _connection_keys(present, context):
    """The decision keys on which presence in an outcome turns: those whose
    decided value differs between the outcomes where something holds and
    those where it does not. All of them when that cannot be told."""
    if not context:
        return []
    decided = context[0]
    keys = list(dict.fromkeys(k for d in decided for k in d))
    relevant = [k for k in keys
                if {repr(d.get(k)) for d, p in zip(decided, present) if p}
                != {repr(d.get(k)) for d, p in zip(decided, present) if not p}]
    return relevant or keys


def _is_label_list(value):
    return isinstance(value, (list, tuple)) and all(isinstance(item, str) for item in value)


def _split_labels(lists, context=None):
    """(settled, open) for one label list's outcomes. Settled: each label as
    many times as every outcome holds it, in first-seen order across the
    outcomes. Open: each label an outcome holds beyond that, in first-seen
    order, as an UnresolvedResult carrying the connection it turns on."""
    from collections import Counter
    counts = [Counter(labels) for labels in lists]
    order = list(dict.fromkeys(label for labels in lists for label in labels))
    settled, opened = [], []
    for label in order:
        held = [c[label] for c in counts]
        settled.extend([label] * min(held))
        for extra in range(min(held), max(held)):
            present = [n > extra for n in held]
            keys = _connection_keys(present, context)
            some = 'one permitted completion' if len(lists) == 2 else 'some permitted completions'
            other = 'the other' if len(lists) == 2 else 'others'
            opened.append(UnresolvedResult(
                f"{label}: holds under {some} of {_connection_context_text(keys, context)} and not under {other}",
                _connection_source(keys, context),
                alternatives=(('holds', True), ('does not hold', False)),
                display_alternatives=False))
    return settled, opened


def _connection_merge(values, context=None):
    """Retain common facts; mark changing cells and conditional rows.

    Testimony counts count only confirmed testimonies. An uncertain row is
    visible with an explicit Status, never silently promoted to a finding.
    A list of labels with an Unresolved channel (_LABEL_CHANNELS) keeps the
    labels every outcome holds and moves the rest to the channel.

    ``context``, when evaluate_with_connection_uncertainty supplies it, is
    (the decisions each outcome was evaluated under, the undecided
    connections by key), aligned with ``values``.
    """
    if all(repr(v) == repr(values[0]) for v in values[1:]):
        return values[0]
    if all(isinstance(v, dict) for v in values):
        keys = list(dict.fromkeys(k for v in values for k in v))
        result = {k: _connection_merge([v.get(k) for v in values], context) for k in keys}
        for field, channel in _LABEL_CHANNELS.items():
            lists = [v.get(field) for v in values]
            opened = []
            if all(_is_label_list(labels) for labels in lists) and any(
                    list(labels) != list(lists[0]) for labels in lists[1:]):
                settled, opened = _split_labels(lists, context)
                result[field] = type(lists[0])(settled)
            channels = [v.get(channel, ()) for v in values]
            if (opened or any(repr(c) != repr(channels[0]) for c in channels[1:])) and all(
                    isinstance(c, (list, tuple)) for c in channels):
                union = list({repr(item): item for c in channels for item in c}.values())
                result[channel] = tuple(union) + tuple(opened)
        if 'Testimonies' in result and 'Count' in result:
            testimonies = result['Testimonies']
            if isinstance(testimonies, list):
                uncertain = [t for t in testimonies if is_unresolved(t.get('Status')) or is_unresolved(t.get('result'))]
                certain = [t for t in testimonies if t not in uncertain]
                for t in uncertain:
                    t['result'] = t.get('Status') if is_unresolved(t.get('Status')) else t['result']
                result['Count'] = len(certain)
                if uncertain:
                    result['Unresolved Count'] = len(uncertain)
                result['Labels'] = [t['sentence'] if isinstance(t['sentence'], str) else f"Established testimony ({t['n']})" for t in certain]
                for k in ('Strength Testimonies', 'Weakness Testimonies'):
                    if k in result:
                        result[k] = ', '.join(result['Labels'])
        return result
    if all(isinstance(v, list) for v in values) and all(isinstance(r, dict) for v in values for r in v):
        identity = ('Chart', 'Planet', 'n', 'Number', 'Type', 'Kind', 'Condition', 'Companion',
                    'Receiver', 'Received', 'Carrier', 'Separates From', 'Connects To',
                    'Connecting', 'With', 'Hands Over To', 'Blocked', 'Blocked By', 'From Reaching',
                    'Collector', 'Collects', 'Manner', 'Returned By', 'Yields To', 'Other Contact',
                    'Favored By', 'Direction', 'Via', 'Enclosed By', 'Separating From', 'Connecting To',
                    'Pair', 'Aspect (whole sign)', 'Item', 'Testimony', 'Question', 'Refinement', 'Factor')
        def key(row):
            parts = tuple((k, repr(row[k])) for k in identity if k in row)
            return parts or tuple((k, repr(v)) for k, v in row.items())
        # Never collapse distinct rows just because a table shares an identity
        # field, and preserve multiplicity when identical rows are intentional.
        ambiguous = set()
        for rows in values:
            seen = set()
            for row in rows:
                k = key(row)
                if k in seen:
                    ambiguous.add(k)
                seen.add(k)
        maps = []
        for rows in values:
            mapping, occurrences = {}, {}
            for row in rows:
                k = key(row)
                if k in ambiguous:
                    k = (k, repr(row))
                n = occurrences.get(k, 0)
                occurrences[k] = n + 1
                mapping[(k, n)] = row
            maps.append(mapping)
        keys = list(dict.fromkeys(k for m in maps for k in m))
        result = []
        for k in keys:
            present = [m[k] for m in maps if k in m]
            row = _connection_merge(present, context and (
                [d for m, d in zip(maps, context[0]) if k in m], context[1]))
            if len(present) != len(values):
                row = dict(row, Status=_connection_unknown([True, False],
                           'this finding depends on an unresolved connection'))
                if isinstance(row.get('Testimonies'), list):
                    row['Testimonies'] = [dict(t, result=row['Status']) for t in row['Testimonies']]
                    row['Count'], row['Labels'] = 0, []
                    row['Unresolved Count'] = len(row['Testimonies'])
                    for field in ('Strength Testimonies', 'Weakness Testimonies'):
                        if field in row:
                            row[field] = ''
            result.append(row)
        return result
    return _connection_unknown(values)


def evaluate_with_connection_uncertainty(function, *args, **kwargs):
    """Evaluate a complete judgment before collapsing missing connection facts.

    Can also surround a harness predicate, keeping its original meaning while
    yielding an unresolved result if its possible Boolean answers disagree.
    """
    if getattr(_CONNECTION_EVALUATION, 'decisions', None) is not None:
        return function(*args, **kwargs)
    pending, outcomes, decided, choices = [{}], [], [], {}
    try:
        while pending:
            decisions = pending.pop()
            _CONNECTION_EVALUATION.decisions = decisions
            try:
                outcomes.append(function(*args, **kwargs))
                decided.append(decisions)
            except _ConnectionChoice as choice:
                choices.setdefault(choice.key, choice.result)
                pending.extend(decisions | {choice.key: option} for option in choice.options)
    finally:
        _CONNECTION_EVALUATION.decisions = None
    context = (decided, choices)
    merged = _connection_merge(outcomes, context)
    finish = getattr(function, '_connection_finish', None)
    if finish is not None and len(outcomes) > 1:
        merged = finish(merged, outcomes, context)
    return merged


def _connection_aware(function=None, *, finish=None):
    """Evaluate ``function`` under every permitted completion of its
    undecided connections and merge the outcomes. ``finish(merged,
    outcomes, context)``, when given, recomputes what the generic merge
    cannot: counts whose known subtotal depends on which section each
    settled label belongs to."""
    if function is None:
        return lambda f: _connection_aware(f, finish=finish)
    if finish is not None:
        function._connection_finish = finish
    @wraps(function)
    def run(*args, **kwargs):
        return evaluate_with_connection_uncertainty(function, *args, **kwargs)
    return run


# ==========================================
# THE READINGS OF ONE RUN
# ==========================================
# The seven configurable readings are the reader's, and they belong to one
# run of the script rather than to this module. While the engine was the top
# half of app.py each run executed it into a namespace of its own, so a
# reading assigned at the top of a run reached that run's evaluators and no
# one else's. The engine is a module now, imported once, and Streamlit runs
# every session's script in its own thread against that one module: a plain
# module global would be shared, and an evaluator could be handed another
# reader's rule in the middle of a run. So a reading is per-thread state --
# app.py pins them with set_readings() at the top of each run, and every
# evaluator asks for one through reading().
#
# The module constant of each name stays where it always was, next to the
# doctrine that explains it, and is the default a thread that has pinned
# nothing falls back to: an engine imported with no run behind it answers
# with the course text's own reading, as it did before the split.
_RUN = threading.local()

READINGS = ('CONNECTION_PROFILE', 'EASTERN_RULE', 'MOON_RAYS_ORB', 'MARS_WEST_RAYS_18',
            'DOMAIN_RULE', 'LOT_HOUSE_CUSP', 'SOFTENED_INFORTUNE')

def set_readings(**values):
    """Pin this thread's readings for this run. An unrecognised name is an
    error, not a setting that silently does nothing: a reading the engine
    does not read is a reading the page only thinks it has changed."""
    for name, value in values.items():
        if name not in READINGS:
            raise KeyError(f"{name!r} is not a reading the engine reads; it reads {', '.join(READINGS)}")
        setattr(_RUN, name, value)

def reading(name):
    """This thread's value for `name`, or the module's own default."""
    return getattr(_RUN, name, globals()[name])

# ==========================================
# 0. SAVED CHART PERSISTENCE
# ==========================================
# What this app calls itself. Until 2026-09-16 nothing in the code carried a
# version at all: a record written by one build and an analysis exported from
# another could not be told apart, which is half of what F08 of the review of
# that date asked for. It is written into every saved record ("saved_with")
# and into every exported analysis, it is shown in one place on the pages --
# the Sources page's citation-key caption, the owner's one exception to the
# rule that page text carries no build process -- and docs/RELEASING.md sets
# it before a tag. A release's value is the tag without the 'v' (1.4.0); a
# '-dev' suffix means a working tree between releases.
APP_VERSION = "1.1.0"

# Charts are saved as {name: {date_string, time_string, location_query}} in a
# small JSON file. Only the raw natal inputs are stored -- the full chart is
# cheaply recomputed on load rather than serialized.
#
# This lives in the OS's per-user data directory, NOT next to app.py: a
# packaged build's own folder (_internal) gets replaced whole by every new
# download, which used to silently wipe saved charts on every update unless
# the file was manually copied out and back in first.
APP_DIR_NAME = "Zij"
# What the folder was called while the app was the Traditional Astrology
# Engine (renamed 2026-09-22). A chart saved then is not left behind: the
# first run under the new name moves the whole folder across, once, and
# only when the new one does not exist yet.
_LEGACY_APP_DIR_NAME = "TraditionalAstrologyEngine"

def _user_data_path() -> Path:
    """Where the per-user folder is, whether or not it exists or can be made.

    C-08 of the outside pass (ruling 150): an empty or relative APPDATA or
    XDG_DATA_HOME was taken as given, so the folder was made under whatever
    directory the app was launched from. Either counts as unset, as the XDG
    specification says of its own variable (_absolute_environment_folder)."""
    if sys.platform == "win32":
        base = _absolute_environment_folder("APPDATA") or str(Path.home() / "AppData" / "Roaming")
    elif sys.platform == "darwin":
        base = str(Path.home() / "Library" / "Application Support")
    else:
        base = _absolute_environment_folder("XDG_DATA_HOME") or str(Path.home() / ".local" / "share")
    return Path(base) / APP_DIR_NAME


def _absolute_environment_folder(name):
    """The environment's `name` where it names a folder by an absolute path;
    None where it is unset, empty or relative (C-08, ruling 150)."""
    value = os.environ.get(name, "")
    return value if value and os.path.isabs(value) else None

def _user_data_dir() -> Path:
    """The per-user folder, made if need be; raises OSError when it cannot
    be made."""
    return _make_user_data_dir(_user_data_path())

class DataFolderRefused(PermissionError):
    """C-03 of the outside pass (ruling 150): the data folder stands and
    belongs to another account. Nothing is read from it or written in it."""


# What the data folder's refusal gives as its reason, in the place of the
# system's words (data_folder_state).
DATA_FOLDER_NOT_OURS = "it belongs to another account"


def _make_user_data_dir(path) -> Path:
    """Make the per-user folder `path` as a launch makes it -- the folder
    kept under the app's former name moved across first, once -- and return
    it; raises OSError when it cannot be made.

    C-03 of the outside pass (ruling 150): the folder took its mode from the
    umask alone (0777 under umask 000), so other accounts could read the
    saved charts and plant files in it. A folder made here is made 0700 --
    asked of mkdir and set after it, since the umask cuts what mkdir is
    asked (0o300 under 0o444) and os.chmod is not cut -- and one of this
    account's that is wider is narrowed (_keep_the_data_folder_ours); one
    that belongs to another account is refused (DataFolderRefused).

    The folder moved or copied in from the former name stands at `path`
    with the former folder's mode until it is narrowed here, after it is
    in place; the files in it keep their own modes, and the former folder
    a copy was made from is left as it was."""
    legacy = path.parent / _LEGACY_APP_DIR_NAME
    _remove_dead_copies(path, legacy)
    if not path.exists() and legacy.is_dir():
        # One move, atomic on the one filesystem these two share; a copy
        # only if the move is refused, and then the old folder stays put
        # rather than leaving the charts in neither place.
        try:
            legacy.rename(path)
        except OSError:
            _copy_the_former_folder(legacy, path)
    try:
        path.mkdir(mode=0o700, parents=True)
    except FileExistsError:
        if not path.is_dir():
            raise
    else:
        try:
            os.chmod(path, 0o700)
        except OSError:
            pass                        # a filesystem that keeps no modes
    _keep_the_data_folder_ours(path)
    return path


def _not_this_accounts(folder):
    """Whether `folder` stands and belongs to another account (a link
    followed: the folder it names is the one judged, K-07 and SB-12). False
    where the system has no owners to compare (Windows: a folder under
    APPDATA is the account's own by its access list) or `folder` cannot be
    looked at (that is the folder's own case, data_folder_state's)."""
    if not hasattr(os, "getuid"):
        return False
    try:
        return _owner_of(folder) != os.getuid()
    except (OSError, ValueError):
        return False


def _owner_of(folder):
    """The id of the account `folder` belongs to, a link followed."""
    return os.stat(folder).st_uid


def _keep_the_data_folder_ours(path):
    """C-03 (ruling 150): refuse the data folder `path` where it belongs to
    another account; else take from it any permission it gives the group or
    others (0755 and 0777 become 0700). The owner's own bits are left as
    they are: a folder its owner has made unwritable stays so, and is said
    (K-09). Where the change of mode is refused (a filesystem that keeps
    no modes, or sets them for itself) the folder is left as it is, and
    nothing is said. A link in the folder's place is followed, so the folder it
    names is the one judged and narrowed (K-07, SB-12). On Windows the mode
    calls change nothing that matters: a folder under APPDATA is closed to
    other accounts by its access list."""
    if _not_this_accounts(path):
        raise DataFolderRefused(errno.EPERM, DATA_FOLDER_NOT_OURS, str(path))
    try:
        mode = stat.S_IMODE(os.stat(path).st_mode)
        if mode & 0o077:
            os.chmod(path, mode & ~0o077)
    except (OSError, ValueError):
        pass


def _copy_the_former_folder(legacy, path):
    """The folder under the app's former name, copied whole to `path` when
    it cannot be moved there, and published only once complete.

    N05 of lane SC2 (the outside audit of face757): the copy was made at
    `path` itself, which existed from its first file on. A second launch
    took the half-made folder for the app's own, saved into it under the
    store's lock, and the copy's next file -- the old store -- went over that
    save. The copy is now made in a folder of its own beside `path`, and
    renamed to `path` whole, only while there is still no folder of the
    app's there: a folder another launch has made in the meantime, and
    anything saved into it, is never written over. A copy some of whose
    files could not be copied (a link to nothing, a file this account may
    not read) is published with the rest, as the copy made in place left
    them. A copy not published is removed; it is a copy, and the former
    folder keeps every file it was made from.

    N05 of SC2's check (lane SC3): a file whose copy failed part way was
    published cut short -- the store's, which the load then copied aside
    and named as "the original file" -- and one whose copy failed before
    its first byte was simply missing, the load listing no chart and saying
    nothing. A file of the copy that is not byte for byte the former
    folder's is now taken out before it is published (the former folder
    keeps it whole), and a load that finds no store moves the former
    folder's in, under the store's lock (bring_in_the_old_store). The copy
    is made in a folder this launch holds a lock on (flock, where the
    system has it) from its making to its end, so that a later launch can
    tell a copy left by a launch killed on the way -- which used to stay
    beside the data folder for good -- from one still being made
    (_remove_dead_copies)."""
    for _attempt in range(64):
        staging = path.with_name(f".{path.name}.{secrets.token_hex(8)}.copying")
        try:
            # Made owner-only, but copytree gives it the former folder's
            # mode at its end: it is published at that mode, and narrowed
            # only after (_keep_the_data_folder_ours).
            os.mkdir(staging, 0o700)
        except FileExistsError:
            continue                    # a name already there: another's, never written into
        except OSError:
            return
        held = _hold_a_copy(staging)
        if held is _COPY_TAKEN:
            continue                    # a later launch took it for a dead copy: it is that launch's to remove
        try:
            try:
                shutil.copytree(legacy, staging, dirs_exist_ok=True)
            except shutil.Error:
                pass                    # every file it could copy is copied
            except OSError:
                shutil.rmtree(staging, ignore_errors=True)
                return
            _drop_copies_not_whole(staging, legacy)
            try:
                if not os.path.lexists(path):
                    # os.rename refuses a folder that holds anything (and on
                    # Windows any folder at all), so a folder made and
                    # written in since this look is still not written over.
                    os.rename(staging, path)
                    return
            except OSError:
                pass
            shutil.rmtree(staging, ignore_errors=True)
            return
        finally:
            if held is not None:
                os.close(held)


# What _hold_a_copy gives back for a copy's folder another launch holds, or
# that is no longer the folder named.
_COPY_TAKEN = object()


def _hold_a_copy(staging):
    """A descriptor of the copy's folder `staging` with an exclusive flock
    on it, held while the copy is made (or while a dead copy is removed);
    _COPY_TAKEN where another launch holds it or the name no longer leads to
    it; None where no lock can be had (no flock on this system, or a
    filesystem that refuses it on a folder)."""
    if fcntl is None:
        return None
    flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        fd = os.open(staging, flags)
    except FileNotFoundError:
        return _COPY_TAKEN
    except OSError:
        return None
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        os.close(fd)
        return _COPY_TAKEN
    except OSError:
        os.close(fd)
        return None
    try:
        if os.path.samestat(os.fstat(fd), os.lstat(staging)):
            return fd
    except OSError:
        pass
    os.close(fd)
    return _COPY_TAKEN


def _same_bytes(a, b):
    """Whether the files `a` and `b` hold the same bytes; False when either
    cannot be read."""
    try:
        if os.stat(a).st_size != os.stat(b).st_size:
            return False
        with open(a, "rb") as one, open(b, "rb") as other:
            while True:
                left, right = one.read(1 << 20), other.read(1 << 20)
                if left != right:
                    return False
                if not left:
                    return True
    except OSError:
        return False


def _drop_copies_not_whole(staging, legacy):
    """Take out of the copy `staging` each file that is not byte for byte
    its counterpart in the former folder `legacy` (a copy cut short): it is
    a copy, and the former folder keeps the file whole."""
    for root, _dirs, files in os.walk(staging):
        for name in files:
            copy = Path(root) / name
            if not _same_bytes(legacy / copy.relative_to(staging), copy):
                try:
                    os.unlink(copy)
                except OSError:
                    pass


def _only_a_copy(staging, legacy):
    """Whether every file in `staging` is in the former folder `legacy`, at
    the same place and with the same bytes, so that removing it loses
    nothing; False for anything that is not a plain file or folder."""
    try:
        for root, dirs, files in os.walk(staging):
            for name in dirs + files:
                here = Path(root) / name
                mode = os.lstat(here).st_mode
                if stat.S_ISDIR(mode):
                    continue
                if not stat.S_ISREG(mode) or not _same_bytes(legacy / here.relative_to(staging), here):
                    return False
    except OSError:
        return False
    return True


def _remove_dead_copies(path, legacy):
    """N05 of SC2's check (lane SC3): a copy of the former folder left
    beside the data folder `path` by a launch killed while making it
    (`.<name>.<16 hex>.copying`) is removed: only one no launch holds any
    more (_hold_a_copy) and only while it is nothing but a copy of what the
    former folder `legacy` still holds. One still being made, one holding
    anything the former folder does not, and every one where no lock can
    tell (Windows, a filesystem that refuses it) are left."""
    form = re.compile(r"\." + re.escape(path.name) + r"\.[0-9a-f]{16}\.copying")
    try:
        names = os.listdir(path.parent)
    except OSError:
        return
    for name in names:
        if not form.fullmatch(name):
            continue
        staging = path.parent / name
        held = _hold_a_copy(staging)
        if held is None or held is _COPY_TAKEN:
            continue
        try:
            if _only_a_copy(staging, legacy):
                shutil.rmtree(staging, ignore_errors=True)
        finally:
            os.close(held)

# L6R-N4 of the re-pass of 2026-10-04: a folder that cannot be made (a base
# the account cannot write in, a file where the folder should be) used to
# raise here, at the engine's import, and the app died before any page with
# a raw traceback. The paths are still named, under the folder that could
# not be made, so that every read of them finds nothing and every write
# fails as a write; the reason is kept for data_folder_problem() below.
try:
    DATA_DIR = _user_data_dir()
    DATA_DIR_ERROR = None
except OSError as _data_dir_exc:
    DATA_DIR = _user_data_path()
    DATA_DIR_ERROR = _data_dir_exc.strerror or str(_data_dir_exc)


def data_folder_state():
    """What the folder holding the saved charts and the preferences cannot
    be, and the system's reason: ('made', reason) for a folder that could
    not be made, ('found', reason) for one gone since it was made,
    ('opened', reason) for one this account cannot enter, ('written in',
    reason) for one it cannot write in; (None, None) when it can be used.

    A folder that could not be made at launch is tried again on each call,
    so that one put right while the app is open is used from then on -- and
    made as the launch makes it: the G2 check found that a bare mkdir here
    left the folder under the former name unmoved, after which the move
    could never run (the new folder now existing) and its saved charts
    dropped out of the app without a word.

    K-09 of the re-pass's follow-ups: a folder that is there but that this
    account cannot enter (mode 000) or write in (mode 555) was taken as
    usable. Nothing was said: the one that cannot be entered opened with a
    picker empty of the charts it holds, and in either "Set as home" showed
    a home for the session that no file kept. Each call now asks the
    system whether this account may enter the folder and write in it (two
    access tests, no file made), so a folder put right while the app is
    open is used from then on, as above.

    SC-10 of the notes lanes (2026-10-06): a folder gone since the launch
    (removed, or a file or a broken link in its place) was left to the
    writes, which failed each in its own words ("Could not write ...", "the
    preferences file could not be written"), neither naming the folder.
    It is ('found', reason): said, and refused by Save and "Set as home",
    as the others are. It is not made again here -- the launch makes the
    folder; one removed while the app is open may be on its way back.

    C-03 of the outside pass (ruling 150): a folder that belongs to another
    account is ('used', DATA_FOLDER_NOT_OURS), and nothing is read from it
    or written in it (_not_this_accounts)."""
    global DATA_DIR_ERROR
    if DATA_DIR_ERROR is not None:
        try:
            _make_user_data_dir(DATA_DIR)
            DATA_DIR_ERROR = None
        except DataFolderRefused:
            DATA_DIR_ERROR = DATA_FOLDER_NOT_OURS
            return 'used', DATA_DIR_ERROR
        except OSError as exc:
            DATA_DIR_ERROR = exc.strerror or str(exc)
            return 'made', DATA_DIR_ERROR
    if not os.path.isdir(DATA_DIR):
        try:
            os.stat(DATA_DIR)
            reason = os.strerror(errno.ENOTDIR)
        except OSError as exc:
            reason = exc.strerror or os.strerror(errno.ENOENT)
        return 'found', reason
    if _not_this_accounts(DATA_DIR):
        return 'used', DATA_FOLDER_NOT_OURS
    if not os.access(DATA_DIR, os.X_OK):
        return 'opened', os.strerror(errno.EACCES)
    if not os.access(DATA_DIR, os.W_OK):
        return 'written in', _unwritable_folder_reason(DATA_DIR)
    return None, None


def _unwritable_folder_reason(path):
    """The system's words for a folder the account cannot write in: the
    filesystem's own when it is mounted read-only, else no permission."""
    try:
        if os.statvfs(path).f_flag & os.ST_RDONLY:
            return os.strerror(errno.EROFS)
    except (OSError, AttributeError):      # no statvfs on Windows
        pass
    return os.strerror(errno.EACCES)


def data_folder_problem():
    """Why the folder holding the saved charts and the preferences cannot be
    used, or None when it can: data_folder_state()'s reason. Since K-09 that
    covers a folder that is there but that this account cannot enter or
    write in, as well as one that could not be made."""
    return data_folder_state()[1]

SAVED_CHARTS_PATH = DATA_DIR / "saved_charts.json"
# Where this file used to live -- checked once so anyone upgrading from
# before this change doesn't have to move it by hand.
_LEGACY_SAVED_CHARTS_PATH = Path(__file__).parent / "saved_charts.json"

def _validate_chart_mapping(charts):
    """The saved-charts file is {chart name: entry dict}. Valid JSON is not
    enough: '[]' parsed fine and then crashed the sidebar at .keys(). Only
    the shape the UI actually indexes is checked -- a mapping of string
    names to mapping entries -- so an older entry missing a field still
    loads.

    The SHAPE only, deliberately: one entry whose fields are the wrong type
    must not condemn the whole file, which is what raising here would do
    (the loader would copy the file aside and open with an empty picker).
    An entry's own fields are checked, one entry at a time and without
    raising, by chart_record_fault() below -- a record that fails it stays
    in the mapping and in the file, and is refused only at the point where
    the sidebar would otherwise hand it to a widget."""
    if not isinstance(charts, dict):
        raise ValueError(f"saved charts root must be a mapping, got {type(charts).__name__}")
    for name, entry in charts.items():
        if not isinstance(name, str) or not isinstance(entry, dict):
            raise ValueError(f"saved chart {name!r} is not a name -> mapping entry")
        # B-04 (ruling 146): a name holding a lone surrogate -- the JSON
        # escape "\ud800", valid JSON -- is a str no page can carry: the
        # sidebar's picker raised on it before any page was drawn, at every
        # launch. Such a name is as unusable as a name that is not a str,
        # and condemns the store the same way: it is copied aside and named.
        if not _text_encodes(name):
            raise ValueError(f"saved chart {name!r} has a name that is not text a page can show")
    return charts


def _text_encodes(text):
    """Whether `text` encodes as UTF-8, which is what every page element
    needs of it. A str parsed from JSON can still fail: a lone surrogate
    escape ("\\ud800") parses to a str that no element can carry, while a
    surrogate PAIR written as two escapes parses to the one character it
    names and encodes. The browser sends UTF-8, so the app never makes
    such text itself; a hand edit or an import does (B-04, ruling 146)."""
    try:
        text.encode("utf-8")
    except UnicodeEncodeError:
        return False
    return True


def _is_real_number(value):
    """A finite int or float -- and not a bool, which is an int in Python
    and is never a coordinate, an offset or an age."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return False
    # L6-03: math.isfinite converts an int to a float and raises
    # OverflowError past ~1.8e308, inside the validator meant to refuse the
    # record. No coordinate, offset or age has more than 16 digits.
    if isinstance(value, int) and abs(value) >= 10 ** 16:
        return False
    return math.isfinite(value)


def record_number(value):
    """A stored field as the number it means, or None when it means no
    number. A number WRITTEN AS TEXT counts: '43.7792' is that latitude,
    and _records_match already reads it as that latitude when it decides
    whether a record has been edited -- so a loader that refused it would
    have the app calling one record two things at once. What does not
    count is text that is not a number, a bool, or an infinity."""
    if _is_real_number(value):
        return float(value)
    if isinstance(value, str):
        try:
            number = float(value.strip())
        except ValueError:
            return None
        return number if math.isfinite(number) else None
    return None


def _is_clock_string(value):
    """'HH:MM:SS' (the form _chart_record writes), as a real time."""
    if not isinstance(value, str):
        return False
    m = re.fullmatch(r"(\d{1,2}):(\d{2}):(\d{2})", value.strip())
    if not m:
        return False
    h, mi, s = (int(part) for part in m.groups())
    return h < 24 and mi < 60 and s < 60


# Each field of a saved record, and what the sidebar needs it to be before
# it can be written into a widget key. The check is by TYPE and, for the
# numbers, by RANGE: a type the sidebar cannot consume raises where it is
# consumed (an int time_string has no .split, a str latitude will not
# compare with a float), and that took the whole script down on load and at
# launch. A wrong VALUE inside the right type is left to the draft rules
# that already handle one -- a target_date that will not parse keeps the
# last target that did, a time_standard the app no longer offers raises the
# "saved before the time standard was stored" flag. Two exceptions are
# faults here, so that no chart is cast on them: a number out of range,
# which the widgets would silently pull to a bound; and a date_string the
# date parser cannot read, which went into the date box with the box's own
# error while the record's other fields were cast at the previous chart's
# date under the record's name. Such a record is refused at load as a
# malformed time is (HP-10): K-12 of the re-pass's follow-ups, the owner's
# ruling 42 of 2026-10-06.
# (utc_offset out of +-14 is its own case, reported by the loader rather
# than refused, so that the record still loads and says what it holds.)
CHART_RECORD_FIELDS = (
    ('date_string', 'date', 'date, written down as text'),
    ('time_string', 'time', 'time of day as HH:MM:SS'),
    ('time_standard', 'time standard', 'time standard, written down as text'),
    ('utc_offset', 'UTC offset', 'number of hours'),
    ('lat', 'latitude', 'number between -90 and 90'),
    ('lon', 'longitude', 'number between -180 and 180'),
    ('location_query', 'place', 'place, written down as text'),
    ('target_mode', 'target', 'target, written down as text'),
    ('target_date', 'target date', 'date, written down as text'),
    ('target_age', 'target age', 'whole number of years, zero to 9999'),
)


def _chart_field_is_usable(field, value):
    # B-04 (ruling 146): the two text fields a page draws as they are stored
    # -- the place, in the sidebar's place box, and a time standard this app
    # does not offer, in the sidebar's sentence that names it -- must also
    # be text a page can carry; one holding a lone surrogate stopped the
    # page (and the launch, as the last chart). The other three are matched
    # or parsed before anything is drawn, and are left as they were.
    if field in ('time_standard', 'location_query'):
        return isinstance(value, str) and _text_encodes(value)
    if field in ('date_string', 'target_mode', 'target_date'):
        return isinstance(value, str)
    if field == 'time_string':
        return _is_clock_string(value)
    number = record_number(value)
    if number is None:
        return False
    if field == 'lat':
        return -90.0 <= number <= 90.0
    if field == 'lon':
        return -180.0 <= number <= 180.0
    if field == 'target_age':
        # Bounded above as well: a value past a C long overflows the
        # ephemeris call on load (the hostile pass of 2026-09-22, H1);
        # 9999 is past any birthday the ephemeris can reach, so an age
        # merely out of reach still loads and is named as such.
        return 0 <= number <= 9999 and number.is_integer()
    return True                                    # utc_offset: any number; the range is H5's


# --- The readings a record carries (schema 2, 2026-09-16) ----------------
# F03 of the review of 2026-09-16: a chart saved under Abu Ma'shar's
# connection rule came back under Sahl, because a record held the nativity
# and nothing about how it had been read. From this version a record also
# carries the doctrinal readings in force when it was saved, under
# "readings" (store key -> value, app.py's READINGS_REGISTRY), and says so
# in "saved_with": {"app": APP_VERSION, "schema": CHART_RECORD_SCHEMA}.
#
# A record written before this carries neither, and is schema 1: it loads
# exactly as it always did and is told apart by the absence, never by a
# migration -- nothing is written into an old record until the reader saves
# it again.
CHART_RECORD_SCHEMA = 2

# Each stored reading and what it may hold: the NAME of a module-level
# tuple or mapping of its options, read at call time because most of them
# are defined further down this file, or bool for a checkbox. The store
# keys are app.py's READINGS_REGISTRY's, and a test holds the two in step.
CHART_RECORD_READINGS = (
    ('_connection_rule', 'CONNECTION_PROFILES'),
    ('_eastern_rule', 'EASTERN_RULE_OPTIONS'),
    ('_fitting_infortune', bool),
    ('_moon_rays_15', bool),
    ('_mars_west_18', bool),
    ('_domain_rule', 'DOMAIN_RULE_OPTIONS'),
    ('_lot_house_cusp', 'LOT_HOUSE_CUSP_OPTIONS'),
    ('_pn4_monthly_turn', 'PN4_MONTHLY_TURN_OPTIONS'),
    ('_reading_depth', 'READING_DEPTH_OPTIONS'),
)


def _reading_options(spec):
    """The values a stored reading may hold. A string spec names a
    module-level tuple (or a mapping, whose KEYS are the options, which is
    how the connection rule's profiles are written)."""
    if spec is bool:
        return (False, True)
    values = globals()[spec]
    return tuple(values.keys() if isinstance(values, dict) else values)


def _reading_value_is_usable(store_key, value):
    for key, spec in CHART_RECORD_READINGS:
        if key != store_key:
            continue
        if spec is bool:
            return isinstance(value, bool)
        return value in _reading_options(spec)
    return True            # a key this app does not know: ignored, not a fault


def _readings_fault(readings):
    """The first stored reading this app cannot set, as (its name for a
    reader, what it is not), or None.

    A key this app does not know is IGNORED, not refused: a record written
    by a later build, or by one with a reading since withdrawn, is still
    this reader's nativity and still loads. What is refused is a value the
    widget could not take -- 'Ptolemy' for the connection rule, a string
    for a checkbox -- because seeding one into a widget key raises where the
    widget reads it, which is H3's lesson about every other field."""
    if not isinstance(readings, dict):
        return ('saved readings', 'mapping of readings')
    for store_key, value in readings.items():
        if not _reading_value_is_usable(store_key, value):
            return (store_key.lstrip('_').replace('_', ' '), 'reading this app offers')
    return None


def chart_record_fault(entry):
    """The first field of a saved record the sidebar cannot load, as
    (field's name for a reader, what it is not), or None when the record
    can be loaded. A field the record does not carry, or carries as null,
    is not a fault: records written before a field existed still load, and
    a record carrying no "readings" at all is schema 1 and loads as it
    always did.

    The record is never altered and never dropped -- the caller reports the
    fault and leaves the form as it was, and the file keeps the record
    exactly as it found it."""
    if not isinstance(entry, dict):
        return ('record', 'mapping of fields')
    for field, label, expected in CHART_RECORD_FIELDS:
        value = entry.get(field)
        if field in ('date_string', 'time_string') and field in entry and value is None:
            return (label, expected)      # the loader needs these two; a null is not an absence
        if field not in entry or value is None:
            continue
        if not _chart_field_is_usable(field, value):
            return (label, expected)
        # K-12 (ruling 42): a date the parser cannot read, in the date box's
        # own form, which the sidebar's date error names.
        if field == 'date_string' and parse_iso_date(value) is None:
            return (label, 'calendar date as YYYY-MM-DD')
    if entry.get('readings') is not None:
        fault = _readings_fault(entry['readings'])
        if fault is not None:
            return fault
    return None


# L6R-N3 of the re-pass of 2026-10-04: the fields a record cannot be cast
# without. chart_record_fault lets an absent field pass, so that a record
# written before a field existed still loads, and the loader writes only the
# fields a record carries, leaving every other box as it stood. For the
# target and for a time standard saved before it was stored that is the
# design (the last target is kept; the missing standard is flagged in the
# sidebar). For the date, the time, and the offset of a record held under
# the manual standard it is not: such a record was cast under its own name
# at the PREVIOUS chart's date, time or offset, so the chart depended on what
# had been open before it. Every record this app writes carries all three,
# so only a hand edit or an import makes such a record, and it is refused on
# load as a null date or time is (HP-10), with its sentence, and nothing is
# cast.
#
# K-11 of the re-pass's follow-ups (2026-10-05): the place, likewise. A
# record carrying neither its coordinates (lat and lon) nor a place query
# was cast under its own name at the previous chart's place. A record with a
# query and no coordinates is not lacking: it was saved before coordinates
# were stored with a chart, and the loader puts its query into the city box
# on purpose (_restore_chart, app.py).
def chart_record_lack(entry):
    """The first field `entry` must carry to be cast under its own name and
    does not carry, as the field's name for a reader, or None.

    Absent and null are one here: the date and the time always, the UTC
    offset when the record's time standard is the manual one (an old label
    read as the option it is now), and the place when the record carries
    neither both coordinates nor a place query. A record chart_record_fault
    refuses is that function's to name, so a value that is not a mapping is
    None here."""
    if not isinstance(entry, dict):
        return None
    for field, label in (('date_string', 'date'), ('time_string', 'time')):
        if entry.get(field) is None:
            return label
    if (time_standard_current(entry.get('time_standard')) == TIME_STANDARD_OPTIONS[2]
            and entry.get('utc_offset') is None):
        return 'UTC offset for its manual time standard'
    if ((entry.get('lat') is None or entry.get('lon') is None)
            and entry.get('location_query') is None):
        return 'place'
    return None


def chart_record_schema(entry):
    """Which schema a stored record is written in: 2 when it carries the
    readings that were in force, 1 when it was written before this app
    stored them. What the number is READ FOR is the load: a schema-1 record
    has nothing to restore and gets a sentence saying so, while a schema-2
    record's readings are offered. A record that merely says it is schema 2
    without carrying readings is read by what it holds, not by what it
    claims."""
    if not isinstance(entry, dict) or not isinstance(entry.get('readings'), dict):
        return 1
    return CHART_RECORD_SCHEMA


def chart_record_readings(entry):
    """The readings a record was saved under, as {store key: value}, or {}
    when it carries none. Only the keys this app knows are returned -- the
    rest are kept in the file and not acted on."""
    if chart_record_schema(entry) == 1:
        return {}
    known = {key for key, _spec in CHART_RECORD_READINGS}
    return {key: value for key, value in entry['readings'].items() if key in known}


# The offset a manual time standard can be cast at, east positive. The
# widget's own bounds, kept here so the loader can read a stored offset
# against them BEFORE the widget silently pulls an out-of-range one to a
# bound -- and to the wrong bound: a stored 99 came back as -14.
UTC_OFFSET_LIMIT = 14.0


def utc_offset_in_range(value):
    number = record_number(value)
    return number is not None and -UTC_OFFSET_LIMIT <= number <= UTC_OFFSET_LIMIT

def _parse_chart_mapping(data):
    """The validated mapping in the store's bytes `data`. Raises ValueError
    or RecursionError when they are not a store; both readers (the load's
    and the write's, saved_charts_as_they_stand) read through this one.

    - L6-04: utf-8-sig reads what Notepad writes (a leading BOM) and reads
      a BOM-less file unchanged. UnicodeDecodeError and JSONDecodeError
      are ValueErrors, as are the wrong shape and an integer literal past
      Python's digit limit.
    - K-01 of the re-pass's follow-ups (2026-10-05): JSON nested past the
      interpreter's depth raises RecursionError, and is no more a store
      than they are. The load caught only the ValueErrors, so such a file
      stopped the launch with a raw traceback.
    - K-04: a chart named twice. The parser keeps the last record under a
      repeated name and drops the first without a word, and the next save
      wrote the store again without it, so a hand edit's first record was
      in no file. A store naming a chart twice is not a store: it is
      copied aside before anything writes over it, as any malformed store
      is, and the copy is named. Only the chart names are held to this; a
      field repeated inside one record is that record's own business.
    - SC-05 of the notes lanes (2026-10-06): the reader goes deeper than
      the writer. A record nested about 50,000 deep was read and listed,
      and the next Save died on a raw "Stack overflow" in json.dumps, the
      store unchanged and every later Save the same. A store this app
      could not write back is no more a store than one it cannot read: its
      text is made here, as write_saved_charts makes it, and the
      RecursionError that making raises is raised, so that the loader
      copies the bytes aside and names the copy, and a save writes in its
      place, as for any malformed store.
    - S04 of SC2's check (lane SC3): making that text is itself the danger
      for a store nested a few hundred deep -- each level's lines carry its
      indentation, so 1.2 MB of JSON is some 700 MB of text, and a 3.2 MB
      stray raised MemoryError out of the load (where memory was bounded;
      elsewhere it took the memory). The text's length is first counted as
      the writer would make it, piece by piece and without making it, and a
      store whose text would pass STORE_TEXT_LIMIT is not a store: this app
      could not write it back."""
    repeated = []

    def _pairs(pairs):
        mapping = dict(pairs)
        if len(mapping) != len(pairs):
            repeated.append(mapping)
        return mapping

    charts = json.loads(data.decode("utf-8-sig"), object_pairs_hook=_pairs)
    if any(mapping is charts for mapping in repeated):
        raise ValueError("a saved chart is named twice")
    _validate_chart_mapping(charts)
    _within_the_store_text_limit(charts)
    _saved_charts_text(charts)
    return charts


# S04 of SC2's check (lane SC3): the most text a store may come to as the
# writer makes it (characters). A chart's record as written is some 225
# characters, so this is a store of some three hundred thousand charts (SC3's
# check wrote 298,261 before passing it) -- far past any reader's -- and text
# this app can still make and write. The writer refuses a store past it as
# the reader does (finding 10 of that check), so that the app never writes
# what it will not read back.
STORE_TEXT_LIMIT = 64 * 1024 * 1024


def _within_the_store_text_limit(charts):
    """Count the text write_saved_charts would make of `charts` (the same
    encoder, indented, piece by piece, never joined) and raise ValueError
    once it passes STORE_TEXT_LIMIT; RecursionError where the writer's own
    would."""
    length = 0
    for piece in json.JSONEncoder(indent=2).iterencode(charts):
        length += len(piece)
        if length > STORE_TEXT_LIMIT:
            raise ValueError("the saved charts would be more text than this app writes")


class NotAPlainFile(OSError):
    """SB-05 of the security sweep (ruling 157): what stands at a name the
    app reads is not a regular file -- a pipe, a device, a directory -- or
    is a file past the bound its reader sets. It is not read."""


def _read_regular_file(path, limit=None):
    """The bytes of the regular file at `path` (a link followed, so that a
    store the owner keeps as a link is read: K-07); NotAPlainFile for
    anything else, and for a file of more than `limit` bytes when a limit
    is given.

    SB-05 (ruling 157): a pipe at the store's name, the preferences', an
    old store's or a recovery copy's held the load for ever, the page never
    drawn, and a link to an endless device at the preferences' name filled
    the memory. The name is opened without waiting (O_NONBLOCK: a pipe
    opens at once, with no writer) and judged by what was opened, so that
    nothing put in its place between a look and the open is read."""
    flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NONBLOCK", 0)
    fd = os.open(path, flags)
    try:
        regular = stat.S_ISREG(os.fstat(fd).st_mode)
    except OSError:
        os.close(fd)
        raise
    if not regular:
        os.close(fd)
        raise NotAPlainFile(errno.EINVAL, "not a regular file", str(path))
    with os.fdopen(fd, "rb") as handle:
        if limit is None:
            return handle.read()
        data = handle.read(limit + 1)
    if len(data) > limit:
        raise NotAPlainFile(errno.EFBIG, os.strerror(errno.EFBIG), str(path))
    return data


# The name of the recovery copy the last load made, or None. Read by the
# sidebar, which says so once per session (F04 of the review of 2026-09-16:
# a malformed store showed an empty picker and the next save overwrote the
# only copy of the bytes). A module-level name rather than a second return
# value, because load_saved_charts() is called for its mapping in the app
# and in the tests alike and that signature stays as it is.
LAST_STORE_ERROR = None
# True when the last load found the store unreadable, whether or not a
# recovery copy could be made (L6-09: a directory in the store's place has
# no bytes to copy, and used to open with an empty picker and no sentence).
LAST_STORE_UNREADABLE = False


def _owner_only(fd):
    """C-03 (ruling 150): give the file just made on `fd` mode 0600 exactly.
    Its open asked for 0600, which the umask can only cut (to 0o200 under
    0o444, a copy its owner could not read back); os.fchmod is not cut. No
    fchmod on Windows, where the copy takes the folder's access list."""
    if os.name != "nt" and hasattr(os, "fchmod"):
        try:
            os.fchmod(fd, 0o600)
        except OSError:
            pass


def _preserve_unreadable_store(path, data=None, limit=None):
    """Copy an unreadable store beside itself, once per content, as
    ``saved_charts.json.unreadable-<YYYYMMDD-HHMMSS>`` (in a folder that
    cannot be listed, ``...unreadable-<16 hex of its digest>``); the copy's file name,
    or None if the bytes could not be read or written. The same bytes are
    not copied twice: a session that opens the app repeatedly against one
    broken file leaves one recovery copy, not one per launch. `data`, when
    given, is the bytes the caller has already read and judged, so that the
    copy holds exactly what was judged unreadable.

    SB-05 (ruling 157): only a regular file is read, of no more than `limit`
    bytes when one is given (_read_regular_file); a pipe at a copy's name is
    passed over, as any other name already taken is. C-03 (ruling 150): a
    copy is made owner-only (0600), whatever the umask."""
    if data is None:
        try:
            data = _read_regular_file(path, limit)
        except OSError:
            return None
    # SC-13 of the notes lanes (2026-10-06): the copies were looked for by a
    # glob, which finds nothing in a folder this account may enter and write
    # in but not list (mode 0300), so each launch copied the same bytes again
    # under a new name. Where the folder cannot be listed, the copy is named
    # by its content instead, and found by that name.
    try:
        names = os.listdir(path.parent)
    except OSError:
        names = None
    if names is None:
        stem = f"{path.name}.unreadable-{hashlib.sha256(data).hexdigest()[:16]}"
        try:
            if _read_regular_file(path.with_name(stem)) == data:
                return stem
        except OSError:
            pass
    else:
        for previous in sorted(n for n in names if n.startswith(path.name + ".unreadable-")):
            try:
                if _read_regular_file(path.with_name(previous)) == data:
                    return previous
            except OSError:
                continue
        stem = f"{path.name}.unreadable-{datetime.now():%Y%m%d-%H%M%S}"
    # Two different wrecks within one second: the second keeps its own copy
    # rather than writing over the first one's bytes.
    #
    # N01 of lane SC2 (the outside audit of face757): the name was asked
    # free (exists()) and then written (write_bytes), so two loads holding
    # two different unreadable contents in one second -- the file replaced
    # by an editor between their reads; the loads hold no lock here -- chose
    # one name, and the second's bytes went over the first's while both
    # named the copy as kept. Each copy is now made new or not at all
    # (O_CREAT|O_EXCL, as _keep_stray_aside makes its copies): a name
    # already there is never opened or written over. One that already holds
    # these very bytes (another load of the same content, a moment before)
    # is that content's copy, and is named; any other is passed over for
    # the next free -2, -3, ...
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0)
    for n in range(1, 1000):
        name = stem if n == 1 else f"{stem}-{n}"
        copy = path.with_name(name)
        try:
            fd = os.open(copy, flags, 0o600)
        except FileExistsError:
            try:
                if _read_regular_file(copy) == data:
                    return name
            except OSError:
                pass
            continue
        except OSError:
            return None
        try:
            with os.fdopen(fd, "wb") as handle:
                _owner_only(handle.fileno())
                handle.write(data)
        except OSError:
            try:
                os.unlink(copy)             # this copy's own, made just now: no other's is ever named
            except OSError:
                pass
            return None
        return name
    return None

def _write_text_atomically(path, text):
    """Write to a sibling temp file and os.replace() it over the target, so
    a crash or full disk mid-write leaves the previous file intact rather
    than a truncated one that loses every saved chart.

    The temp file's bytes are flushed and synced (os.fsync) before it
    replaces the target, so a crash of the system after the replace finds
    the new bytes or the previous file, never an empty one; a failed sync
    fails the write. On Linux and macOS the folder is synced after the
    replace as well, so the replace itself is kept when this returns; a
    folder whose sync is refused is passed over, and the write stands. On
    Windows the folder is not synced: a crash soon after the write can
    still bring back the previous file, whole. On macOS fsync does not
    empty the drive's own cache, so a power cut can still lose what it
    holds there.

    The bytes written are `text` encoded as UTF-8 and nothing else (no
    newline translation), so that a caller knows them without reading the
    file back: K-03, write_saved_charts' digest.

    K-07 of the re-pass's follow-ups (2026-10-05): a file kept as a
    symbolic link (to one in a synced folder, say) was replaced by a regular
    file, and the file it named was never written again. The link is
    followed: the temp file is made beside the file it names -- on that
    file's own filesystem, which os.replace needs -- and replaces that file,
    and the link stays as it was.

    K-06: a file made read-only (0444) came back writable (0644), because
    os.replace needs only the folder's permission and the temp file had the
    account's default mode. The file's mode is carried onto the temp file
    before the replace.

    C-03 of the outside pass and D-05 of the deep scan (rulings 150 and
    157): the temp file was made 0o666, cut by the umask, and held the bytes
    at that mode until the carry -- 0666 under umask 000, beside a store of
    0600. It is now made at the target's own mode (_new_temp_file), so it is
    never wider than its target at any moment, and a first-ever file is
    made owner-only, 0600, whatever the umask; an existing file's mode is
    still carried (K-06).

    HP2-01 of the second hostile pass (ruling 63): every write of one file
    went through one temp name, `<file>.tmp`. Two writes in flight at once
    (two windows, or two launches of the app on one folder) shared it: the
    second truncated and refilled the first's temp file, the first's replace
    installed the second's bytes and reported success, and the second's
    replace found no temp file and reported a failure. Each write now makes
    a temp file of its own, made new or not at all (O_CREAT|O_EXCL: a name
    already there is never opened, so never another writer's)."""
    try:
        target = Path(os.path.realpath(path))
    except (OSError, ValueError):
        target = Path(path)
    try:
        mode = stat.S_IMODE(os.stat(target).st_mode)
    except OSError:
        mode = None
    data = text.encode("utf-8")
    tmp, fd = _new_temp_file(target, 0o600 if mode is None else mode)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        # The umask may have cut the mode asked of the open (0o200 under
        # 0o444); os.chmod is not cut, and gives the file its mode exactly.
        os.chmod(tmp, 0o600 if mode is None else mode)
        os.replace(tmp, target)
    except OSError:
        # L6-09: a failed replace (a directory in the store's place) leaves
        # no stray temp file behind -- made writable first, since a
        # read-only file cannot be removed on every system. Only this
        # write's own temp file is removed: no other writer's is ever named.
        try:
            os.chmod(tmp, stat.S_IREAD | stat.S_IWRITE)
        except OSError:
            pass
        try:
            tmp.unlink()
        except OSError:
            pass
        raise
    _sync_folder(target.parent)


def _sync_folder(folder):
    """Sync `folder` itself to the disk, so that a replace made in it is
    kept; on Linux and macOS only (Windows opens no folder for this). A
    folder that cannot be opened or synced (a filesystem that refuses it)
    is passed over: the file's own bytes were synced before the replace."""
    if os.name == "nt":
        return
    try:
        fd = os.open(folder, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    except OSError:
        return
    try:
        os.fsync(fd)
    except OSError:
        pass
    finally:
        os.close(fd)


def _new_temp_file(target, mode=0o600):
    """A temp file of this write's own beside `target`, made new at `mode`
    (the target's own, or 0600 for a first-ever file: D-05, ruling 157) --
    the umask may cut it narrower, never wider -- and its descriptor open
    for writing: `<name>.<random>.tmp`, so that what looks for a stray temp
    file (`*.tmp`) still finds one. A name already taken is passed over for
    another; any other refusal (a folder this account cannot write in) is
    raised, as the plain write raised it."""
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0)
    for _attempt in range(64):
        tmp = target.with_name(f"{target.name}.{secrets.token_hex(8)}.tmp")
        try:
            return tmp, os.open(tmp, flags, mode & 0o777)
        except FileExistsError:
            continue
    raise FileExistsError(errno.EEXIST, os.strerror(errno.EEXIST), str(target.parent))


# --- The store's lock and the preferences' lock (lane KS, ruling 63) -----
# HP2-02 and HP2-03 of the second hostile pass: a save read the store, put
# its record into what it read and wrote the whole file back, and
# remember_preference / forget_preference did the same with one key of the
# preferences; nothing was held across the three steps. Another window's
# write landing between this window's read and its write was written over,
# and both windows said it was done. Each read-change-write is now made
# under a lock, the store's and the preferences' each its own:
#
# - a thread lock, for the windows of one server (Streamlit runs each
#   window's script in a thread of its own);
# - and a lock on a file in the data folder, for two launches of the app on
#   one folder: fcntl.flock where the system has it (a second descriptor of
#   the file is refused while the first holds it, in the same process as in
#   another), msvcrt's lock on the file's first byte on Windows, and the
#   thread lock alone where neither is to be had (no lock module, or a lock
#   call that answers ENOSYS, not provided by this system) or the file
#   cannot be made (a folder this account cannot write in: the write then
#   fails as a write, and the sidebar's sentence about the folder stands as
#   before).
#
# The lock file is not the store itself, which os.replace swaps for a new
# file at every write (a lock on the old one would lock nothing), nor beside
# the file a linked store names, which is the reader's folder, not the
# app's. It lives only while it is held: the holder removes it before it
# lets go, and a writer that was waiting on a file so removed finds, once it
# has it, that the name no longer leads to it, and takes the lock on the
# file now there instead. So no lock file is left in the folder.
#
# The two locks are separate because a save, holding the store's lock,
# then remembers its chart as the last one opened; one lock taken twice
# would wait on itself. Where both are held the store's is taken first.
#
# Ruling 77 (SC-04 of Sol's pass): each lock is waited on for a bounded
# time, LOCK_WAIT_SECONDS in all -- the thread lock's wait and the file
# lock's, however many hand-overs are lost on the way. Past it DataLockBusy
# is raised and nothing is written; the page says another window of the app
# is holding the data and to try again. A second launch stopped or hung while
# it held a lock used to leave every Save of every window waiting without
# end. The file lock is asked for without blocking and asked again after a
# short pause (flock and msvcrt's lock take no time limit).
#
# Ruling 73: a writer that loses a hand-over (the file it waited on removed
# by its holder, and another writer already holding the file now under the
# name) waits on the new file in its turn; it never goes ahead on the thread
# lock alone while a file lock is to be had (the KS re-check's R2-3: a cap
# of sixteen such losses let it, and writes were lost).
#
# Ruling 109 (lane SC3): ruling 63's fallback is narrowed to the thread lock
# alone where no file lock can be had at all -- no lock call on this system,
# a folder this account cannot write in. A
# directory, a link (dangling, or to a file elsewhere) or a file this account
# can open in no way standing under the lock file's name used to end the
# lock between launches silently and for good; a write meeting one is now
# refused (DataLockBlocked), nothing is written, and the obstruction is left
# as it is. A lock file this account can open only for reading, or only for
# writing, is no obstruction (ruling 113, amending 109's list): flock takes a
# descriptor opened either way.
# Under a umask that takes away the owner's write, a launch's own lock file
# is made read-only (0o666 masked), and every other launch went in on the
# thread lock alone while it was held (SC2's check, the data on D01); a
# launch killed while holding it left it so for good.
#
# A lock call that fails for any reason but another holder's, on a system
# that has the call -- a network folder with no lock service, a filesystem
# that does not support locks -- refuses the write (DataLockUnavailable):
# nothing is written, and the page says so (for the saved charts, that their
# folder could not be locked; for a preference, as for any write the file
# did not take). Going on with the thread lock alone there let two launches on
# one folder each report a save while one of the two was lost. The lock file
# made for the attempt is left where it is, and the next write opens it as
# it stands.

LOCK_WAIT_SECONDS = 10.0


class DataLockBusy(Exception):
    """The saved charts' or the preferences' lock was held elsewhere past
    LOCK_WAIT_SECONDS: by another window of the app, or another launch of it
    on the same folder. Nothing has been written."""


class DataLockBlocked(DataLockBusy):
    """Ruling 109: something stands under a lock file's name that is no lock
    file this app can use -- a directory, a link, a file this account can
    open in no way -- on a system that offers file locks. Nothing has been
    written, and what stands there is left as it is. `folder` is the folder
    it stands in: the data folder, or the folder of the file a linked store
    or preferences file names. A DataLockBusy, so that whatever gives up on
    a busy lock gives up here too and writes nothing."""

    def __init__(self, folder):
        super().__init__(str(folder))
        self.folder = str(folder)


class DataLockUnavailable(DataLockBusy):
    """The lock call itself failed on a lock file in `folder`, for a reason
    other than another holder's (a network folder with no lock service, a
    filesystem that does not support locks), on a system that has the call.
    Nothing has been written: without the lock, a write from another launch
    of the app on the same folder could be lost unseen. A DataLockBusy, so
    that whatever gives up on a busy lock gives up here too."""

    def __init__(self, folder):
        super().__init__(str(folder))
        self.folder = str(folder)

_STORE_THREAD_LOCK = threading.Lock()
_PREFERENCES_THREAD_LOCK = threading.Lock()


def saved_charts_lock(wait=None):
    """The store's lock, held with `with` across a read of the store, the
    change made to it and its write. `wait`, when given, bounds the wait for
    the lock in place of LOCK_WAIT_SECONDS (a tidying that can as well be
    left to the next launch waits a moment for the lock); it bounds nothing
    done once the lock is held."""
    return _data_lock(_STORE_THREAD_LOCK, _lock_files(SAVED_CHARTS_PATH, "saved_charts.lock"), wait)


def preferences_lock(wait=None):
    """The preferences' lock, held across a read of the preferences file,
    the change made to it and its write; `wait` as in saved_charts_lock."""
    return _data_lock(_PREFERENCES_THREAD_LOCK, _lock_files(PREFERENCES_PATH, "preferences.lock"), wait)


def _lock_files(path, name):
    """The lock files a write of `path` holds: `name` in the data folder
    (ruling 63) and, where `path` is a link to a file in another folder,
    `name` beside that file as well.

    N02 of lane SC2 (the outside audit of face757): the writes follow a link
    to the file it names (K-07), but the lock was the data folder's alone.
    Two launches on two data folders whose stores (or preferences) are
    links to one file each held their own folder's lock, both read, and the
    second write lost the first's record, though both had said it was done.
    The lock beside the file the link names is the one every launch that
    writes that file takes, from whichever folder it links. It lives only
    while it is held, as the data folder's does. The two are taken in one
    order everywhere (by their folders' real paths), so that two launches
    each holding one never wait on each other; where the one beside the file
    cannot be had at all (a folder this account cannot write in, a lock
    call that answers ENOSYS), the data folder's is held alone, as ruling
    63's fallback holds the thread lock alone. Something standing under its
    name there refuses the write (ruling 109), as under the data folder's,
    and so does a lock call that fails there for any other reason
    (DataLockUnavailable)."""
    own = path.parent / name
    try:
        here = os.path.realpath(path.parent)
        there = os.path.dirname(os.path.realpath(path))
    except (OSError, ValueError):
        return [own]
    if here == there:
        return [own]
    return [lock for _where, lock in sorted(((here, own), (there, Path(there) / name)))]


@contextmanager
def _data_lock(thread_lock, lock_paths, wait=None):
    """Hold `thread_lock` and the file lock of each of `lock_paths`, in
    order, all within one LOCK_WAIT_SECONDS (or `wait`); DataLockBusy, with
    none held, past it."""
    if wait is None:
        wait = LOCK_WAIT_SECONDS
    deadline = _clock.monotonic() + wait
    if not thread_lock.acquire(timeout=max(0.0, wait)):
        raise DataLockBusy()
    held = []
    try:
        for lock_path in lock_paths:
            fd = _take_file_lock(lock_path, deadline)
            if fd is not None:
                held.append((fd, lock_path))
        yield
    finally:
        try:
            for fd, lock_path in reversed(held):
                _give_file_lock(fd, lock_path)
        finally:
            thread_lock.release()


def _take_file_lock(lock_path, deadline=None):
    """The descriptor of `lock_path`, made if need be and locked, or None
    where no file lock can be had (no lock call on this system: no lock
    module, or a call that answers ENOSYS; a folder this account cannot
    write in). A lock call that fails for any other reason than another
    holder's (a network folder with no lock service, ENOLCK; a filesystem
    that does not support locks, EOPNOTSUPP) refuses the write:
    DataLockUnavailable, naming the folder, the file lock not held.

    A link under the name is not followed (O_NOFOLLOW, where the system has
    it: the KS check found that a dangling link made its target, outside the
    data folder), and a directory cannot be opened for writing. Ruling 109:
    a link, a directory, or a file this account can open in no way, under
    the name, refuses the write (DataLockBlocked, naming the folder), and
    is left as it stands; ruling 63's fallback, the thread lock alone, is
    for where no file lock can be had at all.

    Lane SC3, ruling 113 (amending ruling 109's list): a lock file this
    account may only read (the app's own, made under a umask that takes the
    owner's write, or left by a launch killed while it held one) or only
    write is opened as it allows -- flock takes a descriptor opened for
    reading or for writing alike -- and locked as it stands, not refused.
    One it may only read is no holder's to remove (_give_file_lock).

    R-3 of the KS re-check: Windows' Python has no O_NOFOLLOW, so a link
    under the name was opened through, the file opened never was the name,
    and the writer reopened it without end, holding the thread lock: every
    Save hung. So the name is looked at, not followed, before the open --
    anything there but a regular file and nothing is opened -- and again
    after it, which closes the moment between the two.

    Ruling 73: a writer whose file was removed by its holder, another
    writer already holding the file now under the name, takes its turn on
    that one; ruling 77: all within `deadline` (LOCK_WAIT_SECONDS from now
    when not given), past which DataLockBusy, the file lock not held."""
    if fcntl is None and msvcrt is None:
        return None
    if deadline is None:
        deadline = _clock.monotonic() + LOCK_WAIT_SECONDS
    while True:
        if _clock.monotonic() >= deadline:
            raise DataLockBusy()
        if _lock_name_kind(lock_path) == 'other':
            raise DataLockBlocked(lock_path.parent)
        fd = _open_lock_file(lock_path)
        if fd is _LOCK_NAME_EMPTIED:
            continue                    # its holder removed it between the looks: the name again
        if fd is None:
            return None
        try:
            opened_regular = stat.S_ISREG(os.fstat(fd).st_mode)
        except OSError:
            opened_regular = False
        if not opened_regular or _lock_name_kind(lock_path) == 'other':
            os.close(fd)
            raise DataLockBlocked(lock_path.parent)
        try:
            _wait_for_file_lock(fd, deadline)
        except DataLockBusy:
            os.close(fd)
            raise
        except OSError as exc:
            os.close(fd)
            # No lock call on this system: the thread lock alone. (Read
            # guarded: a system without the name never matches, and refuses.)
            if exc.errno == getattr(errno, "ENOSYS", None):
                return None
            raise DataLockUnavailable(lock_path.parent) from exc
        if _still_named(fd, lock_path):
            return fd
        # The holder this write waited on removed the file before letting
        # go: the lock to take is on the one now under the name.
        os.close(fd)


# The errors a lock asked for without blocking is refused with while
# another holds it: flock's EWOULDBLOCK, msvcrt's EACCES (EDEADLK, Windows'
# EDEADLOCK, is msvcrt's only for a blocking LK_LOCK or LK_RLCK after its
# retries, never for this LK_NBLCK; macOS has no EDEADLOCK).
_LOCK_REFUSALS = frozenset({errno.EAGAIN, errno.EWOULDBLOCK, errno.EACCES, errno.EDEADLK})


def _wait_for_file_lock(fd, deadline):
    """Lock `fd` (flock, or msvcrt's lock on the file's first byte), asking
    without blocking and again after a pause that grows to a tenth of a
    second while another holds it; DataLockBusy at `deadline`. Any other
    refusal is raised as the OSError it is."""
    pause = 0.005
    while True:
        try:
            if fcntl is not None:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
            else:
                os.lseek(fd, 0, os.SEEK_SET)
                msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
            return
        except OSError as exc:
            if exc.errno not in _LOCK_REFUSALS:
                raise
        left = deadline - _clock.monotonic()
        if left <= 0:
            raise DataLockBusy()
        _clock.sleep(min(pause, left))
        pause = min(pause * 2, 0.1)


# What _open_lock_file gives back when the file under the name went between
# the open that was refused and the look after it: the name is taken again.
_LOCK_NAME_EMPTIED = object()


def _open_lock_file(lock_path):
    """A descriptor of the lock file `lock_path`, made if need be; None
    where none can be had (ruling 63's fallback: a folder this account
    cannot write in, a folder gone, a filesystem that cannot be written);
    _LOCK_NAME_EMPTIED where the file went in the meantime; DataLockBlocked
    for something under the name that is no lock file this app can use
    (ruling 109).

    The file is made exclusively (O_CREAT|O_EXCL), and anything already
    under the name is opened as it stands: read and write where the account
    may; otherwise read only, or write only, as the file allows (lane SC3,
    ruling 113: the app's own lock file under a umask that takes the
    owner's write is read-only). Those opens do not create, follow no link
    and do not wait (O_NONBLOCK: a pipe put under the name in between is
    opened at once, and found no regular file by the caller's look after
    the open).

    Finding 2 of SC3's check: the make used to be one read-write open with
    O_CREAT, which a folder this account cannot write in and a read-only
    file standing under the name refuse alike. A look after the refusal told
    them apart, and a file let go by its holder in between (removed at its
    release) looked like the folder's refusal: the write went in on the
    thread lock alone while a third launch made and locked a new file, and
    saves were lost. An exclusive make meets anything under the name as
    EEXIST, so a refusal of it is the folder's own, with no look between to
    be overtaken; a file gone before it could be opened as it stands is the
    name taken again. O_EXCL follows no link either, so a dangling link put
    under the name is never made into a file outside, O_NOFOLLOW or not."""
    plain = getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        return os.open(lock_path, os.O_RDWR | os.O_CREAT | os.O_EXCL | plain, 0o600)   # D-10: owner-only
    except FileExistsError:
        pass                            # something stands under the name: opened as it stands, below
    except OSError:
        # Nothing stood under the name (an exclusive make meets anything
        # there as EEXIST): the folder refused the file's making, or the name
        # cannot be looked at -- no file lock to be had.
        if _lock_name_kind(lock_path) == 'other':
            raise DataLockBlocked(lock_path.parent)
        return None
    for access in (os.O_RDWR, os.O_RDONLY, os.O_WRONLY):
        try:
            return os.open(lock_path, access | plain | getattr(os, "O_NONBLOCK", 0))
        except PermissionError:
            continue
        except FileNotFoundError:
            return _LOCK_NAME_EMPTIED   # let go by its holder since the make: the name again
        except OSError:
            # A link (ELOOP under O_NOFOLLOW), a directory (EISDIR) is refused;
            # anything else (a filesystem that cannot be written) is no file lock.
            if _lock_name_kind(lock_path) == 'other':
                raise DataLockBlocked(lock_path.parent)
            return None
    kind = _lock_name_kind(lock_path)
    if kind == 'absent':
        return _LOCK_NAME_EMPTIED
    if kind == 'unseen':
        return None
    raise DataLockBlocked(lock_path.parent)     # a file this account can open in no way, or another thing now


def _opened_for_writing(fd):
    """Whether the descriptor `fd` was opened for writing (read and write,
    or write only)."""
    try:
        return fcntl.fcntl(fd, fcntl.F_GETFL) & getattr(os, "O_ACCMODE", 3) != os.O_RDONLY
    except OSError:
        return True


def _lock_name_kind(lock_path):
    """What stands under the lock name, the name itself looked at (a link
    not followed): 'absent', 'file' (a regular file), 'other', or 'unseen'
    when the name cannot be looked at (a folder this account may not search,
    or one gone): that is the folder's own case, said by the folder's
    sentence, and no obstruction under the name (ruling 109)."""
    try:
        mode = os.lstat(lock_path).st_mode
    except FileNotFoundError:
        return 'absent'
    except OSError:
        return 'unseen'
    return 'file' if stat.S_ISREG(mode) else 'other'


def _still_named(fd, lock_path):
    """Whether `lock_path` still names the file open on `fd` (the name
    itself, a link not followed)."""
    try:
        return os.path.samestat(os.fstat(fd), os.stat(lock_path, follow_symlinks=False))
    except OSError:
        return False


def _give_file_lock(fd, lock_path):
    """Remove the lock file and let the lock go. With flock the file is
    removed while still held, so that no one can lock it afresh after; on
    Windows a file open elsewhere cannot be removed at all, so the lock is
    let go first and the removal is tried after, and refused while another
    writer has the file open.

    The name is removed only while it still names this holder's file: if
    something outside the app removed the file while it was held, and a
    newcomer has since made and locked another under the name, that one is
    the newcomer's and is left (the KS check's note 5).

    Lane SC3 (ruling 113): nor is a lock file removed that this holder could
    open only for reading. It is no launch's own making that this account may write
    (a launch opens the file it makes for writing), so it is left as it
    stands -- a lock file still, to the next launch as to this one."""
    if fcntl is not None:
        if _still_named(fd, lock_path) and _opened_for_writing(fd):
            try:
                os.unlink(lock_path)
            except OSError:
                pass
        os.close(fd)
        return
    try:
        os.lseek(fd, 0, os.SEEK_SET)
        msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
    except OSError:
        pass
    named = _still_named(fd, lock_path)
    os.close(fd)
    if named:
        try:
            os.unlink(lock_path)
        except OSError:
            pass

# SC-03 of the notes lanes (the KS check's finding 6): since each write makes
# a temporary file of its own (HP2-01), a write whose process was killed
# between that file and its replace left `<file>.<16 hex>.tmp` beside the
# file for good -- no later write took that name again. At each load the
# strays are tidied: only names of that exact form, only regular files,
# only those last written before this launch (no write of this launch can
# own one), and only under the file's own lock, which every write of it
# holds while its temporary file stands. The lock is waited on a moment
# only (_STRAY_TEMP_WAIT): a stray left now is tidied by a later load. That
# moment bounds the wait for the lock and nothing else: the listing under
# the lock, and the reading, judging, copying and removing of the strays
# after it, take what they take (ruling 140, LS-05).
#
# Ruling 91: a stray may hold the reader's last save, complete -- the write
# was killed after its bytes and before its replace. One that reads as the
# file it was written for (a store; for the preferences, an object) is kept
# aside under a recovery name, `<file>.recovered-<YYYYMMDD-HHMMSS>`, and
# only then removed; one that does not read is removed; one whose bytes
# cannot be read at all is left. The same holds for the shared name every
# write of the store went through before HP2-01, `saved_charts.json.tmp`,
# which no write of this version makes or removes.
_LAUNCHED_AT = _clock.time()
_STRAY_TEMP_WAIT = 0.25


def _recovery_stamp():
    return f"{datetime.now():%Y%m%d-%H%M%S}"


def _keep_stray_aside(target, data):
    """A recovery copy of a stray's bytes `data` beside `target`, made new
    (O_CREAT|O_EXCL): a copy already under the name -- another launch's, or
    one made in the same second -- is never written over, and the next free
    `-2`, `-3`, ... is taken. Its name, or None when none could be made."""
    stem = f"{target.name}.recovered-{_recovery_stamp()}"
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0)
    for n in range(1, 1000):
        name = stem if n == 1 else f"{stem}-{n}"
        copy = target.with_name(name)
        try:
            fd = os.open(copy, flags, 0o600)            # C-03: owner-only, as _preserve_unreadable_store's
        except FileExistsError:
            continue
        except OSError:
            return None
        try:
            with os.fdopen(fd, "wb") as handle:
                _owner_only(handle.fileno())
                handle.write(data)
        except OSError:
            try:
                os.unlink(copy)
            except OSError:
                pass
            return None
        return name
    return None


def _reads_as_a_store(data):
    try:
        _parse_chart_mapping(data)
    except (ValueError, RecursionError):
        return False
    return True


def _reads_as_preferences(data):
    try:
        return isinstance(json.loads(data.decode("utf-8-sig")), dict)
    except (ValueError, RecursionError):
        return False


def _tidy_stray_temp_files(path, lock, reads, former_name=False):
    """SC-03 and ruling 91, above: the strays beside `path`'s real target,
    listed under `lock`; `reads(bytes)` says whether a stray reads as the
    file; `former_name` takes the pre-HP2-01 `<file>.tmp` as well. Returns
    how many strays were kept aside (ruling 100: the load says so).

    S03 of lane SC2 (the outside audit of face757): the former name was
    taken as `<the linked file's name>.tmp`, and beside a store kept as a
    link to a file of another name (`shared.json`, in a folder other
    programs write in) that is any program's name for its own temporary
    file: another program's work, older than the launch, was removed, or
    kept aside and removed. The former name is ruling 91's,
    `saved_charts.json.tmp`, the one this app's earlier writer used: it is
    taken only beside a file of the store's own name."""
    try:
        target = Path(os.path.realpath(path))
    except (OSError, ValueError):
        target = Path(path)
    former_name = former_name and target.name == Path(path).name
    form = r"(?:\.[0-9a-f]{16})?\.tmp" if former_name else r"\.[0-9a-f]{16}\.tmp"
    stray_name = re.compile(re.escape(target.name) + form)
    # S04 of lane SC2 (the outside audit of face757): each stray was read,
    # parsed and copied while the lock was held -- and the parse of a store
    # makes its whole text again (SC-05), which for a stray of deep nesting
    # under a megabyte takes seconds -- so another window's Save waited past
    # its bound and was refused. Only the listing is made under the lock:
    # every write holds the lock while its temporary file stands, so a name
    # listed then is no write's in flight, and no later write takes that
    # name again (each makes a new one). The strays are read, judged, kept
    # aside and removed after the lock is let go; each is read and removed
    # only while its name still holds the very file listed.
    found = []
    try:
        with lock(wait=_STRAY_TEMP_WAIT):
            try:
                names = os.listdir(target.parent)
            except OSError:
                return 0
            for name in names:
                if not stray_name.fullmatch(name):
                    continue
                stray = target.parent / name
                try:
                    seen = os.lstat(stray)
                except OSError:
                    continue
                if stat.S_ISREG(seen.st_mode) and seen.st_mtime < _LAUNCHED_AT:
                    found.append((stray, seen))
    except DataLockBusy:
        return 0
    kept = 0
    for stray, seen in found:
        data = _read_the_stray(stray, seen)
        if data is None:
            continue                            # gone, changed, or not to be read: left
        if reads(data):
            if not _still_the_stray(stray, seen):
                continue                        # another load has kept it aside and removed it
            if _keep_stray_aside(target, data) is None:
                continue                        # not kept aside: not removed either
            kept += 1
        if _still_the_stray(stray, seen):
            try:
                os.unlink(stray)
            except OSError:
                continue
    return kept


def _same_file(a, b):
    return (a.st_dev, a.st_ino, a.st_size, a.st_mtime_ns) == (b.st_dev, b.st_ino, b.st_size, b.st_mtime_ns)


def _still_the_stray(stray, seen):
    """Whether the name `stray` still holds the file listed as `seen` (the
    name itself, a link not followed)."""
    try:
        return _same_file(os.lstat(stray), seen)
    except OSError:
        return False


def _read_the_stray(stray, seen):
    """The bytes of the file listed as `seen`, read through its name only
    while the name still holds it (a link not followed); None when it does
    not, or the bytes cannot be read."""
    flags = (os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
             | getattr(os, "O_NONBLOCK", 0))          # SB-05: a pipe put in its place is not waited on
    try:
        fd = os.open(stray, flags)
    except OSError:
        return None
    try:
        with os.fdopen(fd, "rb") as handle:
            if not _same_file(os.fstat(handle.fileno()), seen):
                return None
            return handle.read()
    except OSError:
        return None


def _old_stores():
    """Where a store was kept before the per-user folder held it, newest
    first: the folder under the app's former name (its store is there still
    when the folder was copied, not moved, and the copy did not make the
    store whole: N05 of SC2's check, below), then beside app.py
    (_LEGACY_SAVED_CHARTS_PATH).

    SB-06 of the security sweep (ruling 157): the store beside the program
    was brought in, without a word, whenever the folder held no store -- at
    the first launch, and again after every deletion of the store -- and in
    a packaged build that folder is the bundle's own. It is now brought in
    once (_IMPORTED_BESIDE_THE_PROGRAM marks the data folder when it has
    been, and the load says so), and never inside a packaged build."""
    olds = [SAVED_CHARTS_PATH.parent.parent / _LEGACY_APP_DIR_NAME / SAVED_CHARTS_PATH.name]
    if not _running_from_a_bundle() and not _the_store_beside_the_program_was_imported():
        olds.append(_LEGACY_SAVED_CHARTS_PATH)
    return olds


# SB-06 (ruling 157): the mark the data folder carries once the store beside
# the program has been brought into it. Its presence is all it says.
_IMPORTED_BESIDE_THE_PROGRAM = "saved_charts.json.imported-from-beside-the-program"


def _running_from_a_bundle():
    """Whether this is a packaged build (PyInstaller's sys.frozen, or the
    folder it unpacks into, sys._MEIPASS): the folder beside the program is
    then the bundle's own, and no store is brought in from it (SB-06)."""
    return bool(getattr(sys, "frozen", False)) or hasattr(sys, "_MEIPASS")


def _the_store_beside_the_program_was_imported():
    return os.path.lexists(SAVED_CHARTS_PATH.parent / _IMPORTED_BESIDE_THE_PROGRAM)


def _mark_the_store_beside_the_program_imported():
    """Leave the mark. The name is opened without waiting (O_NONBLOCK, as
    the store's other names are, SB-05): a pipe put there after the look
    for the mark is refused at once, not waited on for a reader."""
    try:
        os.close(os.open(SAVED_CHARTS_PATH.parent / _IMPORTED_BESIDE_THE_PROGRAM,
                         os.O_WRONLY | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_NONBLOCK", 0),
                         0o600))
    except OSError:
        pass


def _the_first_old_store():
    """(place, charts, not_a_file) for the first store kept in an old place
    (_old_stores) that is there: its charts as the loader reads a store, or
    None where it does not read (it is then left where it is); `not_a_file`
    True where what stands there is no regular file -- a pipe, a device, a
    directory -- which is not read (SB-05, ruling 157). (None, None, False)
    where there is none."""
    for old in _old_stores():
        if old.exists():
            try:
                data = _read_regular_file(old)
            except NotAPlainFile:
                return old, None, True
            except OSError:
                return old, None, False
            try:
                return old, _parse_chart_mapping(data), False
            except (ValueError, RecursionError):
                return old, None, False
    return None, None, False


def _the_old_store():
    """The charts of the first store kept in an old place (_old_stores)
    that is there, read as the loader reads a store; None where there is
    none, or it does not read (it is then left where it is)."""
    return _the_first_old_store()[1]


def bring_in_the_old_store():
    """With the store's lock held by the caller: where there is no store
    yet, write the first store kept in an old place (_the_old_store) into
    it, once. True when it was written. A store there that does not read is
    left where it is, and nothing is written. The store beside the program,
    once brought in, is marked so and not brought in again (SB-06), and
    this thread's store_notices() says it was."""
    if _not_this_accounts(SAVED_CHARTS_PATH.parent) or SAVED_CHARTS_PATH.exists():
        return False
    place, legacy, _not_a_file = _the_first_old_store()
    if legacy is None:
        return False
    try:
        _write_text_atomically(SAVED_CHARTS_PATH, json.dumps(legacy, indent=2))
    except OSError:
        return False
    if place == _LEGACY_SAVED_CHARTS_PATH:
        _mark_the_store_beside_the_program_imported()
        _STORE_LOADED.imported = True
    return True


def _move_the_old_store():
    """The store kept in an old place (_old_stores), written into the
    per-user folder once, while the store there does not exist yet. None
    when that is done, or was not to be done; the DataLockBusy (or ruling
    109's DataLockBlocked, or a DataLockUnavailable) when the store's lock
    could not be had, and nothing was written.

    S02 of lane SC2 (the outside audit of face757): the move asked whether
    the store existed and then wrote it, holding nothing, so a save made in
    between (another window, another launch) was written over by the old
    file's charts, though it had said "Saved". The question and the write
    are now made under the store's lock, the question asked again inside it;
    with the lock held elsewhere past its bound nothing is written, and a
    later load makes the move.

    S02 of SC2's check (lane SC3): such a load listed nothing and said
    nothing, and a save made before the next load wrote the store, after
    which the move was never made. The load now says so (store_notices'
    'unmoved'), and that window's save makes the move under its own lock
    (bring_in_the_old_store) before it adds its record. Only an old store
    that reads is moved, or waited for: the check of SC3 found the load
    telling the reader to reload for charts that a reload would not list
    (an old store that does not read is left as it is, said or not, as it
    always was)."""
    try:
        with saved_charts_lock():
            bring_in_the_old_store()
    except DataLockBusy as exc:
        return exc
    return None


def load_saved_charts():
    global LAST_STORE_ERROR, LAST_STORE_UNREADABLE
    LAST_STORE_ERROR = None
    LAST_STORE_UNREADABLE = False
    _STORE_LOADED.digest = None
    _STORE_LOADED.copy, _STORE_LOADED.unreadable = None, False         # S01, store_notices()
    _STORE_LOADED.unmoved = None                                        # S02 of SC2's check
    _STORE_LOADED.recovered = 0
    _STORE_LOADED.imported = _STORE_LOADED.old_not_a_file = False       # SB-06, SB-05
    if _not_this_accounts(SAVED_CHARTS_PATH.parent):
        return {}                                                       # C-03: another account's folder
    _STORE_LOADED.recovered = _tidy_stray_temp_files(SAVED_CHARTS_PATH, saved_charts_lock, _reads_as_a_store,
                                                     former_name=True)
    if not SAVED_CHARTS_PATH.exists():
        _place, old_charts, _STORE_LOADED.old_not_a_file = _the_first_old_store()
        if old_charts:                                          # ruling 118: one holding a chart
            _STORE_LOADED.unmoved = _move_the_old_store()
    if SAVED_CHARTS_PATH.exists():
        # Read once: the mapping, the digest this load leaves (K-03) and the
        # recovery copy are all of the same bytes. Only a regular file is
        # read (SB-05): anything else is a store that cannot be read.
        try:
            data = _read_regular_file(SAVED_CHARTS_PATH)
        except OSError:
            data = None
        charts = None
        if data is not None:
            _STORE_LOADED.digest = hashlib.sha256(data).hexdigest()
            try:
                charts = _parse_chart_mapping(data)
            except (ValueError, RecursionError):
                charts = None
        if charts is None:
            # Malformed JSON, or valid JSON of the wrong shape. The bytes are
            # kept beside the file before anything is allowed to write over
            # them, and the name of the copy is left where the sidebar can
            # name it.
            LAST_STORE_ERROR = _preserve_unreadable_store(SAVED_CHARTS_PATH, data)
            LAST_STORE_UNREADABLE = True
            _STORE_LOADED.copy, _STORE_LOADED.unreadable = LAST_STORE_ERROR, True
            return {}
        return charts
    return {}


# K-03 of the re-pass's follow-ups (2026-10-05): the digest of the bytes the
# last load_saved_charts() in this thread parsed. A session used to take its
# digest by reading the file a second time, just after its load (and just
# after its own write), so another window's write landing in between was
# taken as this window's own, and its next save wrote over that record under
# a bare "Saved". A Streamlit session runs its script in a thread of its own,
# so the digest is kept per thread: one window's load cannot hand another
# its digest.
_STORE_LOADED = threading.local()


def loaded_saved_charts_digest():
    """The digest of the bytes the last load_saved_charts() in this thread
    parsed -- malformed ones included, which it copied aside -- or None when
    it found no file or could not read it."""
    return getattr(_STORE_LOADED, "digest", None)


# S01 of lane SC2 (the outside audit of face757; SC_CHECK's note 27): what a
# load found for the sidebar to say -- the unreadable store's copy, or that
# no copy could be made -- was left only in LAST_STORE_ERROR and
# LAST_STORE_UNREADABLE, which every window of one server shares. Another
# window's load landing between this window's load and its read of them
# cleared this window's notice, or handed it the other's copy. They are kept
# per thread as well, as the digest is (K-03) and the preferences' notices
# are (K-2), and the app reads them through store_notices(). The module's
# names are still set, as the last load in any window left them.
#
# Ruling 100: a load that kept a cut-short save aside (ruling 91) says so,
# once and naming no file; how many it kept is kept here too.

def store_notices():
    """What this thread's -- this window's -- last load_saved_charts()
    found, as a dict: 'copy', the name of the copy an unreadable store was
    kept as (LAST_STORE_ERROR's); 'unreadable', whether the store could not
    be read (LAST_STORE_UNREADABLE's); 'recovered', how many saves cut short
    it found and kept aside beside the saved charts (ruling 100); 'unmoved',
    whether a store kept in an old place, one that reads, could not be moved
    in for the store's lock (S02 of SC2's check); 'blocked', the folder named when that
    was something standing under the lock's name (ruling 109), or None;
    'unlocked', whether that was the folder refusing the lock call itself
    (DataLockUnavailable);
    'imported', whether it brought in the store kept beside the program
    (SB-06, ruling 157); 'old_not_a_file', whether what stands where an
    older version kept its store is no regular file, and was not read
    (SB-05)."""
    unmoved = getattr(_STORE_LOADED, "unmoved", None)
    return {"copy": getattr(_STORE_LOADED, "copy", None),
            "unreadable": getattr(_STORE_LOADED, "unreadable", False),
            "recovered": getattr(_STORE_LOADED, "recovered", 0),
            "unmoved": unmoved is not None,
            "blocked": unmoved.folder if isinstance(unmoved, DataLockBlocked) else None,
            "unlocked": isinstance(unmoved, DataLockUnavailable),
            "imported": getattr(_STORE_LOADED, "imported", False),
            "old_not_a_file": getattr(_STORE_LOADED, "old_not_a_file", False)}


def saved_charts_digest(charts):
    """The digest of the bytes write_saved_charts(charts) writes. A session
    keeps the digest of what it last read or wrote, and refuses to write
    over a file whose digest has moved (L6-02); since K-03 that is the
    digest of its own bytes, never of a second read of the file."""
    return hashlib.sha256(_saved_charts_text(charts).encode("utf-8")).hexdigest()


def _saved_charts_text(charts):
    """The store's text for `charts`, as write_saved_charts writes it."""
    return json.dumps(charts, indent=2)


@dataclass(frozen=True)
class StoreAsItStands:
    """What a write finds in the store's place, read once, just before it
    writes. `state` is one of:

    - 'absent': no file; `charts` is {}, `digest` None;
    - 'readable': a store; `charts` is its mapping, `digest` its bytes';
    - 'malformed': bytes that are not a store (a hand edit's trailing comma,
      the wrong shape); `charts` None, `digest` its bytes';
    - 'unreadable': bytes that cannot be read at all (a file the account may
      not read, a directory in its place); `charts` and `digest` None.

    `copy` is the name of the recovery copy of a malformed store's bytes,
    when one was asked for and could be made; else None."""
    state: str
    charts: dict = None
    digest: str = None
    copy: str = None


def saved_charts_as_they_stand(keep_aside=False):
    """The store as a write is about to find it (G1 of the re-pass of
    2026-10-04). The digest a session compared before writing could not tell
    a missing file from one it could not read -- both were None -- so a store
    announced as unreadable was taken as unchanged and written over by the
    next save, and every saved chart with it (L6R-N1).

    A write may replace an absent or a readable store, or a malformed one
    whose bytes are kept beside it first: with `keep_aside` the malformed
    bytes are copied (once per content, as the loader copies them) and the
    copy's name is returned. An unreadable store has no bytes to copy and
    must not be replaced at all; nor may a malformed one whose copy could not
    be made (`copy` None)."""
    path = SAVED_CHARTS_PATH
    if _not_this_accounts(path.parent):
        return StoreAsItStands('unreadable', None, None, None)      # C-03: another account's folder
    try:
        present = path.exists()
    except OSError:
        present = True
    if not present:
        return StoreAsItStands('absent', {}, None, None)
    try:
        data = _read_regular_file(path)                             # SB-05
    except OSError:
        return StoreAsItStands('unreadable', None, None, None)
    digest = hashlib.sha256(data).hexdigest()
    try:
        # The loader's reading, the one parser (_parse_chart_mapping):
        # utf-8-sig, then JSON, then the shape. UnicodeDecodeError and
        # JSONDecodeError are ValueErrors, as are the wrong shape, an integer
        # literal past Python's digit limit and a chart named twice (K-04);
        # JSON nested past the interpreter's depth raises RecursionError,
        # and is no more a store than they are.
        charts = _parse_chart_mapping(data)
    except (ValueError, RecursionError):
        copy = _preserve_unreadable_store(path, data) if keep_aside else None
        return StoreAsItStands('malformed', None, digest, copy)
    return StoreAsItStands('readable', charts, digest, None)


def write_saved_charts(charts):
    """Write `charts` over the store; True when the disk took it. The bytes
    written are those saved_charts_digest(charts) digests.

    SC-05: a mapping nested past what json.dumps can write raises
    RecursionError ("Stack overflow"), which reached the page raw. The
    parser refuses such a store before a write is asked of it; a mapping
    that still cannot be written is a write that failed, as any other.

    Finding 10 of SC3's check: a store whose text passes STORE_TEXT_LIMIT,
    which the reader refuses, was written, and the next load listed nothing
    and copied it aside. It is now a write that failed, and nothing is
    written."""
    if _not_this_accounts(SAVED_CHARTS_PATH.parent):
        return False                                    # C-03: another account's folder
    try:
        _validate_chart_mapping(charts)
        _within_the_store_text_limit(charts)
        _write_text_atomically(SAVED_CHARTS_PATH, _saved_charts_text(charts))
        return True
    except (OSError, ValueError, RecursionError):
        return False

# --- Preferences (2026-09-10) -------------------------------------------
# The readings and display choices, kept across runs in the same per-user
# directory as the saved charts (UI_REVIEW_2026-09-10.md §2). Streamlit's
# own persist_state lives only as long as the session, so a restart needs
# a file. Only the store keys listed here are kept, plus the name of the
# last chart loaded, which the app opens on. Missing or unknown keys are
# ignored on read, as the saved-charts loader ignores them. The harness
# sets ALMUTEN_NO_PREFERENCES=1 so a test can neither read a real file
# nor leak a reading into the next test.
PREFERENCES_PATH = DATA_DIR / "preferences.json"
READING_DEPTH_OPTIONS = ("Course text", "Course text and supplement")
PREFERENCE_KEYS = (
    # doctrinal readings, each set on the page it affects
    '_connection_rule', '_eastern_rule', '_moon_rays_15', '_mars_west_18',   # '_five_degree_all_cusps' retired 2026-09-11
    '_fitting_infortune', '_domain_rule', '_lot_house_cusp', '_pn4_monthly_turn', '_reading_depth',
    # display
    '_wheel_layout', '_chart_bounds', '_timing_bounds', '_wheel_order', '_timing_lots', '_timing_rays',
    '_timing_twelfths', '_timing_wheel_view', '_target_mode', '_wheel_dark',
    # how many times the app has been opened, counted so that the Chart
    # page's introduction can fold itself once it has been read
    '_launches',
    # the reader's home place, set from the birthplace the sidebar has
    # resolved, for the "Here & Now" button to cast a chart at: {"label",
    # "lat", "lon"} -- validated by home_place_is_valid below
    'home_place',
)

PREFERENCE_RENAMES = (
    ('_pn4_monthly_turn', "Abu Ma'shar IX.1, 26-34", "PN IV IX.1, 26-34"),
    ('_wheel_order', "Revolution inside (Abu Ma'shar, I.6)", "Revolution inside (Abu Ma'shar's order, PN IV I.6)"),
)

# What each preference must BE. The app writes this file itself, so it is
# normally well formed; a hand-edit, a downgrade or a half-written file is
# not, and the launch block does int() on '_launches' and indexes the saved
# charts by 'last_chart' -- so a string where an int belongs used to stop
# the app from opening at all, on every page. Every key is checked against
# the type or the option tuple its own widget expects, and an entry that
# fails is dropped to its default. Silently: preferences are silent by
# design (nothing announces that a reading was restored either), and
# nothing is written back until the next _persist / _remember does it.
PREFERENCE_BOOL_KEYS = ('_moon_rays_15', '_mars_west_18', '_fitting_infortune', '_chart_bounds',
                        '_timing_bounds', '_timing_lots', '_timing_rays', '_timing_twelfths',
                        '_wheel_dark')


def _preference_option_tuples():
    """Each preference whose value is one of a named set, and that set --
    the very tuple its widget is built from, read at call time because most
    of them are defined further down this file."""
    return {
        '_connection_rule': tuple(CONNECTION_PROFILES),
        '_eastern_rule': EASTERN_RULE_OPTIONS,
        '_domain_rule': DOMAIN_RULE_OPTIONS,
        '_lot_house_cusp': LOT_HOUSE_CUSP_OPTIONS,
        '_pn4_monthly_turn': PN4_MONTHLY_TURN_OPTIONS,
        '_reading_depth': READING_DEPTH_OPTIONS,
        '_wheel_layout': WHEEL_LAYOUT_OPTIONS,
        '_wheel_order': WHEEL_ORDER_OPTIONS,
        '_timing_wheel_view': WHEEL_VIEW_OPTIONS,
        '_target_mode': TARGET_MODE_OPTIONS,
    }


def coordinates_in_range(lat, lon):
    """A pair the engine can be asked about at all: both finite, latitude
    within [-90, 90] and longitude within [-180, 180]. Polar is valid.
    The sidebar's one validation of a place (it stood in app.py until the
    home place needed it here, for the preferences file).

    An int past a float's range (10**400 in a coordinate key) is refused as
    any other impossible number is: float() raises OverflowError on it, and
    that came out of this check as a raw traceback on every run (K-13 of the
    re-pass's follow-ups, 2026-10-05)."""
    try:
        lat, lon = float(lat), float(lon)
    except (TypeError, ValueError, OverflowError):
        return False
    if not (math.isfinite(lat) and math.isfinite(lon)):
        return False
    return -90.0 <= lat <= 90.0 and -180.0 <= lon <= 180.0


HOME_PLACE_FIELDS = frozenset(("label", "lat", "lon"))


def home_place_is_valid(value):
    """Whether `value` is a home place the sidebar can cast a chart at:
    exactly the three fields, the label a non-empty string, the
    coordinates floats (an int is not one -- the app writes floats and a
    hand-edit that wrote 43 is refused with the rest), finite and in range.
    A bool, a NaN, a 91, a missing field and an extra field are all
    refused, so a hand-edited preferences.json cannot take the app down:
    the loader drops the entry and the button stands disabled."""
    if not isinstance(value, dict) or set(value) != HOME_PLACE_FIELDS:
        return False
    label, lat, lon = value["label"], value["lat"], value["lon"]
    # B-04 (ruling 146): a label no page can carry (a lone surrogate)
    # stopped the launch at the Home popover; it is refused with the rest.
    if not isinstance(label, str) or not label.strip() or not _text_encodes(label):
        return False
    if not (isinstance(lat, float) and isinstance(lon, float)):
        return False
    return coordinates_in_range(lat, lon)


def preference_is_valid(key, value):
    """Whether `value` is a value the widget behind `key` could hold."""
    if key == '_launches':
        # Below 10**16, the bound a record's number has (_is_real_number): a
        # count of 10**4300 - 1 is read by json.loads, and its increment cannot
        # be written back (B-06 of the third outside pass, ruling 146).
        return isinstance(value, int) and not isinstance(value, bool) and 0 <= value < 10 ** 16
    if key == 'last_chart':
        return isinstance(value, str)
    if key == 'home_place':
        return home_place_is_valid(value)
    if key in PREFERENCE_BOOL_KEYS:
        return isinstance(value, bool)
    options = _preference_option_tuples().get(key)
    if options is not None:
        return value in options
    return False


def preferences_enabled():
    return os.environ.get("ALMUTEN_NO_PREFERENCES") != "1"


# SB-05 of the security sweep (ruling 157): the most bytes a preferences file
# may hold, as the store has its STORE_TEXT_LIMIT. A file of every key with
# a long home place's name is a few kilobytes; one past this is not read
# (nor copied aside), and the writer refuses to write one, so that the app
# never writes what it will not read back.
PREFERENCES_BYTE_LIMIT = 1024 * 1024

# The name of the copy the last read of an unreadable preferences file made,
# or None; and whether that read found the file unreadable at all, whether
# or not a copy could be made. The same pair the saved charts' loader keeps
# (LAST_STORE_ERROR, LAST_STORE_UNREADABLE), read by the sidebar.
LAST_PREFERENCES_ERROR = None
LAST_PREFERENCES_UNREADABLE = False
# Ruling 77: whether the last remember_preference / forget_preference gave up
# because another window or launch held the preferences' lock past
# LOCK_WAIT_SECONDS (nothing was written), read by the sidebar.
LAST_PREFERENCES_BUSY = False

# K-2 of the KS re-check (wave 5's lane SC, 2026-10-06): the three names above
# are the module's, and every window of one server shares them. A second
# window's read or write landing between one window's call and that
# window's reading of them reset them or set them, so a window's own notice
# could be lost, or another window's shown to it. Each window now reads its
# own: what its last read or write of the preferences found is kept per
# thread as well (a window's script runs in a thread of its own; the
# store's digest is kept so for the same reason, K-03), and read through
# preferences_notices(). The module's names are still set, as the last call
# in any window left them.
_PREFERENCES_NOTICES = threading.local()
_PREFERENCES_NOTICE_DEFAULTS = (("copy", None), ("unreadable", False), ("busy", False), ("blocked", None))


def _reset_preferences_notices():
    for name, default in _PREFERENCES_NOTICE_DEFAULTS:
        setattr(_PREFERENCES_NOTICES, name, default)


def preferences_notices():
    """What this thread's -- this window's -- last read or write of the
    preferences found, as a dict: 'copy', the name of the copy an unreadable
    file was kept as (LAST_PREFERENCES_ERROR's); 'unreadable', whether the
    file could not be read (LAST_PREFERENCES_UNREADABLE's); 'busy', whether
    the lock was held elsewhere past the bound (LAST_PREFERENCES_BUSY's);
    'blocked', the folder in which something stands under the lock's name
    (ruling 109), or None; 'off', whether preferences are switched off for
    this launch (ALMUTEN_NO_PREFERENCES: SB-11, ruling 157), which holds for
    every read and write alike."""
    notices = {name: getattr(_PREFERENCES_NOTICES, name, default) for name, default in _PREFERENCES_NOTICE_DEFAULTS}
    notices["off"] = not preferences_enabled()
    return notices



def _read_preferences_file():
    """The preferences file's object exactly as written -- every key, valid
    or not -- or {} when there is no file, or None when there is one that
    cannot be read as an object (bad bytes, bad JSON, the wrong shape,
    JSON nested past the interpreter's depth, no permission, a folder in
    its place; SB-05, ruling 157: a pipe or a device in its place, or more
    than PREFERENCES_BYTE_LIMIT bytes)."""
    if not PREFERENCES_PATH.exists():
        return {}
    try:
        # utf-8-sig reads a leading byte-order mark (what Notepad writes) and
        # a file without one unchanged, as the saved charts' reader does
        # (L6-04).
        raw = json.loads(_read_regular_file(PREFERENCES_PATH, PREFERENCES_BYTE_LIMIT).decode("utf-8-sig"))
    except (ValueError, RecursionError, OSError):
        # Undecodable bytes and bad JSON are both ValueError. K-02 of the
        # re-pass's follow-ups: JSON nested past the interpreter's depth
        # (200,000 open brackets) raises RecursionError, which escaped this
        # reader and killed the launch with a raw traceback; it is no more a
        # preferences file than bad JSON is, so it is unreadable, copied
        # aside and named as any unreadable file is (the store's write
        # path reads it so already).
        return None
    return raw if isinstance(raw, dict) else None


def _keep_unreadable_preferences():
    """Copy an unreadable preferences file beside itself (once per content,
    by the saved charts' own copier, which names the copy after the file it
    is given) and note the copy, or that none could be made. True when the
    bytes are kept and the file may be written over."""
    global LAST_PREFERENCES_ERROR, LAST_PREFERENCES_UNREADABLE
    LAST_PREFERENCES_ERROR = _preserve_unreadable_store(PREFERENCES_PATH, limit=PREFERENCES_BYTE_LIMIT)
    LAST_PREFERENCES_UNREADABLE = True
    _PREFERENCES_NOTICES.copy, _PREFERENCES_NOTICES.unreadable = LAST_PREFERENCES_ERROR, True   # K-2
    return LAST_PREFERENCES_ERROR is not None


def load_preferences():
    """The stored preferences as a dict, keys limited to PREFERENCE_KEYS and
    'last_chart', values limited to what the widget behind each key can
    hold; an empty dict when there is no file, or it is unreadable, or the
    harness has switched preferences off.

    An entry whose value is the wrong type or not one of its options is
    dropped, so the reading falls to its default -- the app opens, and the
    file is left as it is until the next reading is set.

    A file that cannot be read at all is copied beside itself first, as the
    saved charts' loader does (L6R-N5 of the re-pass of 2026-10-04: a file
    beginning with a byte-order mark was read as empty, and the same launch
    wrote over it -- home place, last chart and readings gone, with no copy
    and no sentence). The copy's name, or that none could be made, is left
    in LAST_PREFERENCES_ERROR / LAST_PREFERENCES_UNREADABLE for the sidebar,
    and in this window's preferences_notices() (K-2)."""
    global LAST_PREFERENCES_ERROR, LAST_PREFERENCES_UNREADABLE
    LAST_PREFERENCES_ERROR = None
    LAST_PREFERENCES_UNREADABLE = False
    _reset_preferences_notices()
    if not preferences_enabled() or _not_this_accounts(PREFERENCES_PATH.parent):     # C-03
        return {}
    _tidy_stray_temp_files(PREFERENCES_PATH, preferences_lock, _reads_as_preferences)   # SC-03, ruling 91
    raw = _read_preferences_file()
    if raw is None:
        _keep_unreadable_preferences()
        return {}
    return _loadable_preferences(raw)

def _loadable_preferences(raw):
    """The entries of the file's object `raw` that a load keeps."""
    prefs = {k: v for k, v in raw.items() if k in PREFERENCE_KEYS or k == 'last_chart'}
    # Option values renamed by the citation convention of 2026-09-10 (a
    # locator names its volume, never the author alone); a file written
    # before it still loads.
    for key, old_value, new_value in PREFERENCE_RENAMES:
        if prefs.get(key) == old_value:
            prefs[key] = new_value
    # The renames run first: a value written under the old name is a valid
    # value once it has been brought forward.
    return {k: v for k, v in prefs.items() if preference_is_valid(k, v)}

def write_preferences(prefs):
    if not preferences_enabled() or _not_this_accounts(PREFERENCES_PATH.parent):     # C-03
        return False
    try:
        text = json.dumps(prefs, indent=2, sort_keys=True)
        if len(text.encode("utf-8")) > PREFERENCES_BYTE_LIMIT:
            return False                # SB-05: never written past what the reader reads back
        _write_text_atomically(PREFERENCES_PATH, text)
        return True
    except (OSError, ValueError):       # ValueError: json.dumps past the integer string limit (B-06)
        return False

# L6R-N6 of the re-pass of 2026-10-04: each session wrote its own copy of
# the whole preferences file, read once at its launch, so a window opened
# before another set a home place or saved a chart erased both from the
# file the moment any of its own readings moved. The two functions below
# read the file again at the write, as a load reads it, and change one key
# in that: every other key stands as whichever window wrote it left it. An
# entry no load would keep (an unknown key, a value no widget can hold) is
# dropped by the write, as the whole-file write always dropped it.
#
# A file that cannot be read is written over only once its bytes are kept
# beside it (L6R-N5); when no copy can be made it is left as it is and
# nothing is written. LAST_PREFERENCES_ERROR / LAST_PREFERENCES_UNREADABLE
# say which, as after a load.

def _preferences_as_they_stand(fallback=None):
    """The file's entries, as a load keeps them, to change one key in, and
    True; when the file is unreadable, a copy of `fallback` (the session's
    own preferences) once the file's bytes are kept beside it, and False;
    (None, False) when no copy of them could be made."""
    global LAST_PREFERENCES_ERROR, LAST_PREFERENCES_UNREADABLE
    LAST_PREFERENCES_ERROR = None
    LAST_PREFERENCES_UNREADABLE = False
    _PREFERENCES_NOTICES.copy, _PREFERENCES_NOTICES.unreadable = None, False      # K-2
    raw = _read_preferences_file()
    if raw is None:
        return (dict(fallback or {}) if _keep_unreadable_preferences() else None), False
    return _loadable_preferences(raw), True


def remember_preference(key, value, fallback=None):
    """Set `key` to `value` in the preferences file as it stands now, and
    change no other entry a load keeps. True when the file holds the change.
    `fallback` is what the file is rebuilt from if it has become unreadable
    since it was loaded.

    Whether the value is a change is judged here, against the file as it
    stands, and not against any window's copy of it (K-10 of the re-pass's
    follow-ups): window A opened X, window B then opened Y, and A opening X
    again wrote nothing, because A's own copy already said X, so the file
    kept B's earlier choice over A's later one. A file that already holds
    the value is not written at all.

    Ruling 77: False, with LAST_PREFERENCES_BUSY set and nothing written,
    when the lock is held elsewhere past LOCK_WAIT_SECONDS. Ruling 109:
    False, with preferences_notices()['blocked'] naming the folder and
    nothing written, when something stands under the lock's name. False,
    with neither set and nothing written, when the folder refuses the lock
    call itself (DataLockUnavailable): the page says the file was not
    written, as for any write it did not take."""
    global LAST_PREFERENCES_BUSY
    LAST_PREFERENCES_BUSY = False
    _reset_preferences_notices()
    if not preferences_enabled() or _not_this_accounts(PREFERENCES_PATH.parent):     # C-03
        return False
    # HP2-03: the read, the change and the write under the preferences'
    # lock, so that another window's key set in between is not lost.
    try:
        with preferences_lock():
            prefs, from_file = _preferences_as_they_stand(fallback)
            if prefs is None:
                return False
            if from_file and key in prefs and prefs[key] == value:
                return True
            prefs[key] = value
            return write_preferences(prefs)
    except DataLockBlocked as exc:
        _PREFERENCES_NOTICES.blocked = exc.folder       # ruling 109
        return False
    except DataLockUnavailable:
        return False                    # the folder refuses the lock call: refused as a write the file did not take
    except DataLockBusy:
        LAST_PREFERENCES_BUSY = True
        _PREFERENCES_NOTICES.busy = True                # K-2
        return False


_ANY_VALUE = object()

def forget_preference(key, only_if=_ANY_VALUE, fallback=None):
    """Remove `key` from the preferences file as it stands now, and change
    no other entry a load keeps; with `only_if`, only while the file holds that
    value under `key`, so that a value another window has written since is
    left. True when the file no longer holds what was to be forgotten.
    `fallback`, the bounded wait (ruling 77), the obstruction (ruling 109),
    a lock call refused, and the notices (K-2) as in remember_preference."""
    global LAST_PREFERENCES_BUSY
    LAST_PREFERENCES_BUSY = False
    _reset_preferences_notices()
    if not preferences_enabled() or _not_this_accounts(PREFERENCES_PATH.parent):     # C-03
        return False
    try:
        with preferences_lock():        # HP2-03, as in remember_preference
            prefs, _from_file = _preferences_as_they_stand(fallback)
            if prefs is None:
                return False
            if key not in prefs:
                return True                 # nothing to remove: the file is not touched
            if only_if is not _ANY_VALUE and prefs[key] != only_if:
                return True                 # another value now: not this one to forget
            del prefs[key]
            return write_preferences(prefs)
    except DataLockBlocked as exc:
        _PREFERENCES_NOTICES.blocked = exc.folder       # ruling 109
        return False
    except DataLockUnavailable:
        return False                    # the folder refuses the lock call: refused as a write the file did not take
    except DataLockBusy:
        LAST_PREFERENCES_BUSY = True
        _PREFERENCES_NOTICES.busy = True                # K-2
        return False

# --- The clock ----------------------------------------------------------
# The two readings of this computer's clock the "Here & Now" button makes,
# each one small function so that a test can monkeypatch it on this module
# and no test depends on the wall clock. The button's callback reads them
# through `engine.` at call time, so a patch on the module object holds
# whether the app took the names through its star import or not.

def now_utc():
    """This moment, aware, in UTC."""
    return datetime.now(timezone.utc)


def local_clock(instant):
    """`instant` as this computer's own clock shows it: the same moment
    in the zone the operating system is set to, offset and all."""
    return instant.astimezone()

# ==========================================
# 1. CORE CALCULATION ENGINE
# ==========================================

# The Sun's centre when his upper limb stands on the apparent horizon, as
# swe.rise_trans places it. Where the Sun neither rises nor sets within a
# day on either side (_sun_is_up is None) the sect fallback asks whether any of his disk
# is up by comparing the sine of his centre's geometric altitude with
# sun_up_sin_altitude(distance): the threshold is taken from the model
# rise_trans itself uses (swecl.c, rise_set_fast), not from a figure of our
# own, so that "any of the disk is up" means the same thing on a night with
# no setting as it does at a setting. A flat -50' (34' refraction, 16'
# semi-diameter) sat about 2.3' ABOVE that horizon, so a Sun whose disk
# never set -- his centre between the two -- read Nocturnal (F5 re-check,
# R1: 65.7N 25E 2000-06-21 22:22 UT). rise_trans's model, at its defaults:
#   - refraction at the apparent horizon from swe.refrac_extended at
#     1013.25 mbar (sea level) and 0 C -- the values it fills in for
#     atpress=0 and attemp=0 -- about 36.74';
#   - the disk's semi-diameter at the Sun's distance, asin(696000 km / d),
#     15.7' to 16.3' over the year (pla_diam[SE_SUN] / 2);
#   - the altitude it tests is TOPOCENTRIC, and _sin_altitude's is
#     geocentric, so the Sun's horizontal parallax, asin(6378.1366 km / d)
#     (about 0.15'), is given back.
# So the centre stands at parallax - semi-diameter - refraction: about
# -52.33' in June and -52.85' in December. tests/test_hostile_l1_2026_10_03.py
# asserts this against rise_trans's own events; the development oracle
# (tools/astro_oracle.py, sun_up_altitude) uses the same formula.
AU_KM = 149597870.7                 # Swiss Ephemeris AUNIT (DE431), in km
SUN_RADIUS_KM = 696000.0            # Swiss Ephemeris pla_diam[SE_SUN] / 2
EARTH_RADIUS_KM = 6378.1366         # Swiss Ephemeris EARTH_RADIUS

def _horizon_refraction():
    """Refraction at the apparent horizon under swe.rise_trans's default
    atmosphere (1013.25 mbar, 0 C, lapse rate 0.0065 K/m), the way
    rise_set_fast takes it: swe_refrac_extended at apparent altitude
    0.000001, APP_TO_TRUE, apparent minus true. About 36.74'."""
    _r, (true_alt, app_alt, _refr, _dip) = swe.refrac_extended(0.000001, 0.0, 1013.25, 0.0, 0.0065, swe.APP_TO_TRUE)
    return app_alt - true_alt

HORIZON_REFRACTION = _horizon_refraction()   # degrees

def sun_up_altitude(distance_au):
    """Geometric altitude (degrees, negative) of the Sun's centre when his
    upper limb stands on the apparent horizon under swe.rise_trans's model:
    parallax - semi-diameter - refraction at his distance in AU."""
    semi_diameter = math.degrees(math.asin(SUN_RADIUS_KM / (distance_au * AU_KM)))
    parallax = math.degrees(math.asin(EARTH_RADIUS_KM / (distance_au * AU_KM)))
    return parallax - semi_diameter - HORIZON_REFRACTION

def sun_up_sin_altitude(distance_au):
    """sin(sun_up_altitude(distance_au)), for comparison with _sin_altitude."""
    return math.sin(math.radians(sun_up_altitude(distance_au)))

@st.cache_data(max_entries=32, show_spinner=False)
def _sin_altitude(ecl_lon, ecl_lat, distance, obliquity, armc, geo_lat):
    """Sine of a body's geocentric altitude above the horizon of geo_lat:
    sin(alt) = sin(phi) sin(delta) + cos(phi) cos(delta) cos(H), with the
    hour angle H = ARMC - RA and RA/delta from the body's actual ecliptic
    longitude, latitude and distance (swe.cotrans). No refraction, no
    parallax. Positive is above the horizon. This, not the ecliptic proxy
    (lon - Ascendant) % 360 > 180, decides which body is above the earth
    (hayz, the luminary up at a syzygy, the Sect table's column), and --
    against sun_up_sin_altitude(distance), so that the visible disk and not
    the bare centre is asked, against the horizon swe.rise_trans places him
    on -- the sect where the Sun is circumpolar; the proxy
    inverts near the poles and on the horizon (fixed 2026-09-08). Sect
    itself turns on the Sun's visible rising and setting, with the
    planetary hours (_sun_is_up)."""
    ra, decl, _r = swe.cotrans((ecl_lon, ecl_lat, distance), -obliquity)
    p, d, h = map(math.radians, (geo_lat, decl, armc - ra))
    return math.sin(p) * math.sin(d) + math.cos(p) * math.cos(d) * math.cos(h)


def calculate_traditional_chart(dt_utc, lat, lon):
    """A chart from a UT moment given as anything with year, month, day,
    hour, minute and second (a datetime or a CivilMoment); the digits are
    read in the calendar the civil calendar's policy assigns them
    (ephemeris.py)."""
    jd = civil_to_jd(dt_utc.year, dt_utc.month, dt_utc.day,
                     dt_utc.hour + dt_utc.minute / 60.0 + dt_utc.second / 3600.0)
    return calculate_traditional_chart_jd(jd, lat, lon)

def calculate_traditional_chart_jd(jd, lat, lon):
    """The chart at a Julian Day (UT). The sidebar arrives here directly, so
    a Julian-only date and an offset across midnight need no datetime."""
    # The seven planets' ephemeris ids are PLANET_SWE_IDS, defined once with
    # the VII.6 material; the chart adds the TRUE Node (owner's decision of
    # 2026-09-07, matching the reference charts; the mean node sat 1-2 degrees
    # off them). The true node's speed is carried like a planet's, and it is
    # not always retrograde: it has short direct spells, which the wheel
    # reports as they are rather than assuming the mean node's constant
    # backward motion.
    targets = {**PLANET_SWE_IDS, 'North Node': swe.TRUE_NODE}
    
    planetary_data = {}
    for name, obj_id in targets.items():
        res, _ = swe.calc_ut(jd, obj_id, MOSHIER_FLAGS)
        planetary_data[name] = {
            'longitude': res[0],
            'latitude': res[1],
            'distance': res[2],
            'speed_in_lon': res[3],
            # Latitude and distance speeds are carried so that Abu Ma'shar's
            # conditions "in themselves" (Gr. Intr. VII.1) can be
            # told apart from their static counterparts: VII.6, 22 and 38
            # distinguish "rising up in the north" from "are northern", and
            # "going down in the south" from "is southern".
            'speed_in_lat': res[4],
            'speed_in_dist': res[5],
        }

    cusps, ascmc = swe.houses(jd, lat, lon, b'B')
    ascendant = ascmc[0]
    mc = ascmc[1]
    descendant = (ascendant + 180.0) % 360.0
    ic = (mc + 180.0) % 360.0
    
    # True obliquity of the ecliptic at the moment (Lesson 5 worksheet
    # line 15); computed here because sect needs it below.
    obliquity = swe.calc(jd + swe.deltat_ex(jd, -1), swe.ECL_NUT, swe.FLG_MOSEPH)[0][0]

    # Sect: is it day or night? ONE definition, shared with the planetary
    # hours (calculate_chronocrats) and stated once on the Chart page.
    # Gr. Intr. VI.33, 4: "the Sun is the planet by whose rising the day
    # comes to be, and by his setting the night comes to be"; VI.33, 17:
    # "the beginning of the hours of the day are from the inception of
    # the Sun's rising from the eastern horizon, while the beginning of
    # the hours of the night are from the disappearance of the Sun's body
    # from the horizon of the west" -- the Sun's visible disk, as Dykes's
    # fn 357 there glosses it: "so long as any part of the Sun's disk is
    # still above the horizon, it is still daytime". So the day runs from
    # the apparent rising of the upper limb to its apparent setting,
    # refraction included -- the same swe.rise_trans events the hours are
    # counted from (_sun_is_up), so sect and the hour count cannot answer
    # "is the Sun up" two ways (hostile pass 2026-10-03, L1-04): both read
    # one bracket of events found once for the moment (_sun_bracket), in
    # which the rising's own instant is day and the setting's night. Where
    # nothing lies within a day ahead, the bracket's events behind decide: a
    # rising behind with no setting since is day, a setting behind with no
    # rising since night (_sun_up_behind), so the instant of the last sunrise
    # before a polar day is day, as stated, and not night by an altitude
    # whose centre sits on the threshold (the third outside pass, A-02).
    # Only where the Sun is circumpolar (polar day or night: no rising or
    # setting within a day on either side) is the same question asked of
    # his altitude: is any of his
    # disk above the horizon, i.e. is his centre above the altitude at
    # which swe.rise_trans would report him rising or setting
    # (sun_up_sin_altitude: his semi-diameter plus rise_trans's own
    # horizon refraction, less his parallax -- about -52.3' in June,
    # -52.9' in December)? Asking the centre against 0 deg instead made
    # the midnight Sun at the edge of polar day -- the disk up all night,
    # its centre a little below the true horizon -- read Nocturnal (F5
    # check, finding 3); asking it against a flat -50' left a 2.3' band
    # in which rise_trans found no setting and the fallback still said
    # Nocturnal (F5 re-check, R1). Never the ecliptic proxy
    # (Sun - Ascendant) % 360 > 180, which inverts near the poles (fixed
    # 2026-09-08).
    sun = planetary_data['Sun']
    is_diurnal = _sun_is_up(jd, lat, lon)
    if is_diurnal is None:
        is_diurnal = (_sin_altitude(sun['longitude'], sun['latitude'], sun['distance'], obliquity, ascmc[2], lat)
                      > sun_up_sin_altitude(sun['distance']))
    sect = 'Diurnal' if is_diurnal else 'Nocturnal'

    # From its LOT_DEFINITIONS row, like every other Lot in the file.
    lot_of_fortune = lot_by_id('fortune', planetary_data, ascendant, cusps, sect)

    return {
        'julian_day': jd,
        'planetary_data': planetary_data,
        'houses': cusps,
        'ascendant': ascendant,
        'descendant': descendant,
        'mc': mc,
        'ic': ic,
        'sect': sect,
        'lot_of_fortune': lot_of_fortune,
        # Lesson 5 worksheet lines 14 and 15: the right ascension of the
        # meridian from the same houses call, and the true obliquity of the
        # ecliptic at the moment. Read by the Chart page's Calculation table.
        'armc': ascmc[2],
        'obliquity': obliquity,
        # The place, so that evaluators needing the horizon (hayz: above or
        # below the earth by ALTITUDE, Astra F04) can be handed it from the
        # chart alone.
        'geo_lat': lat,
        'geo_lon': lon,
    }

# ==========================================
# 2. HELPER FUNCTIONS & VARIATION-SELECTOR-FREE RENDERER
# ==========================================

SIGN_ORDER = ['Aries', 'Taurus', 'Gemini', 'Cancer', 'Leo', 'Virgo', 'Libra', 'Scorpio', 'Sagittarius', 'Capricorn', 'Aquarius', 'Pisces']

def get_zodiac_sign(longitude):
    # Longitudes are circular: exactly 360.0 is 0 Aries, not a thirteenth
    # sign. Every public geometry helper normalises at its own door.
    return SIGN_ORDER[int((longitude % 360.0) // 30) % 12]

def _on_circle(longitude):
    """A longitude in [0, 360). In floats -1e-16 % 360.0 is 360.0 (the sum
    rounds up), which get_zodiac_sign reads as 0 Aries; a helper that took
    its sign from there and its degree in the sign from the raw `lon % 30`
    (30.0 at -1e-16) read the seam as Aries' far edge, not its first
    degree. Every value already in [0, 360) comes back unchanged."""
    longitude = longitude % 360.0
    return 0.0 if longitude >= 360.0 else longitude

# --- Ordinal degrees: the one conversion the degree tables read through ---
# The texts number a sign's degrees as ordinals: the nth degree is the whole
# degree from (n - 1) deg 00' up to, not including, n deg 00'. Gr. Intr.
# V.5, fn 39 (Gr. Intr. p. 268) warns of the confusion between an ordinal
# degree and the cardinal degree of the same number, and Gr. Intr. Fig. 38
# prints each exaltation degree beside its span: the Sun's 19th degree of
# Aries is 18 deg 00' to 18 deg 59'. Read through ordinal_degree: the wells
# (Gr. Intr. V.21, Gr. Intr. Fig. 62), the two tables of Gr. Intr. V.22
# (Gr. Intr. Figs. 63-64), Sahl's degrees of nobility (On Nativities 1.38, 39-41,
# read as ordinals as Gr. Intr. Fig. 64 prints the same rule) and the last
# degree of a sign (Fifty Aphorisms #15, 31). Through in_ordinal_degrees:
# the bright and dark degrees (Gr. Intr. V.20, Gr. Intr. Fig. 61), printed as
# runs of whole degrees. Through ordinal_degree_range: the exaltation
# degrees (EXALTATION_DEGREES), whose one reader in the engine, the Lot of
# Exaltation, counts from the first point of the degree, and the harsher
# burned band (HARSH_BURNED_PATH, Gr. Intr. VII.6, 40), from the start of the
# Sun's fall in the 19th degree of Libra to the end of the Moon's in the 3rd
# of Scorpio. The bounds and the
# faces are runs of measured degrees, and the eyesight places carry their
# own spans; none of them comes through here.

def ordinal_degree(longitude):
    """The ordinal degree a longitude stands in within its sign, 1 to 30:
    0 deg 00' 00" of a sign is its 1st degree, 29 deg 59' 59" its 30th.
    Truncated, never rounded. The seam is Aries' 1st degree (_on_circle),
    and 360 is 0 Aries; the sign is get_zodiac_sign's."""
    return int(_on_circle(longitude) % 30.0) + 1

def ordinal_degree_range(first, last=None):
    """The span of a sign's ordinal degrees `first` to `last` (inclusive;
    `last` defaults to `first`), as degrees from the sign's beginning,
    start included and end excluded: the 19th degree runs from 18 deg 00'
    up to, not including, 19 deg 00', and comes back as 18.0 and 19.0."""
    last = first if last is None else last
    if not 1 <= first <= last <= 30:
        raise ValueError(f"ordinal degrees run 1 to 30 in a sign: {first}..{last}")
    return float(first - 1), float(last)

def in_ordinal_degrees(longitude, first, last=None):
    """True when the longitude stands in its sign's ordinal degrees `first`
    to `last` (ordinal_degree_range: the end excluded)."""
    start, end = ordinal_degree_range(first, last)
    return start <= _on_circle(longitude) % 30.0 < end

def degrees_text(value, places, circle=False, signed=False, zodiac=False):
    """An angle as the tables print it, to `places` decimals, rounded, with
    two exceptions so that no printed angle reads 360 or a signed zero
    (SL's check, finding 8: a Moon at 359.999987 printed Absolute
    360.0000° and her declination -0.00°): a value that rounds to zero
    prints without its sign, and on the circle (`circle`: a longitude or a
    right ascension, taken in [0, 360)) a value that would round up to 360
    prints the last value below it, as a longitude a hair under a sign's
    end prints 29° 59' of its own sign (_whole_minutes; the owner's ruling
    Q6 of 2026-10-05: the carry stops at the boundary). `signed` prints +
    before a value that is not negative (a meridian distance).

    `zodiac` (a longitude, on the circle) stops the carry at every sign's
    end, not at 360 alone: a longitude a hair under 30 Aries printed
    30.0000 beside its Position's 29° Ari 59', the first degree of the
    next sign (the outside inventory of 2026-10-06, N01: Q6's argument
    holds at each of the twelve boundaries). It prints the last value
    below the end, as the Position prints 29° 59'. A right ascension has
    no signs and is printed with `circle` alone."""
    circle = circle or zodiac
    v = _on_circle(value) if circle else float(value)
    text = f"{v:.{places}f}"
    if circle and float(text) >= 360.0:
        text = f"{360.0 - 10.0 ** -places:.{places}f}"
    if zodiac:
        end = (int(v // 30) % 12 + 1) * 30.0          # the end of get_zodiac_sign's sign
        if float(text) >= end:
            text = f"{end - 10.0 ** -places:.{places}f}"
    if float(text) == 0.0:
        text = f"{0.0:.{places}f}"
    if signed and not text.startswith('-'):
        text = '+' + text
    return text

def verdict_text(value, places, reads, circle=False):
    """A number printed beside a verdict read from it, so that the printed
    number, read back, gives the same verdict: reads(printed) ==
    reads(value). Rounding to `places` can carry a value across the bound
    its verdict was read against -- a direct western Venus 6.9999 degrees
    from the Sun is burned, and "7.0" is the first degree past burning --
    and then the number printed beside the verdict says the other one (the
    outside inventory of 2026-10-06, N05-N10, N13). Such a value prints one
    place more, and where that does not separate it either, the last value
    of that place on its own side: never the bound itself, as
    _rhetorius_loosener prints its gap (PW-12). `circle` prints through
    degrees_text on the circle, so no printed angle reads 360; a value that
    rounds to zero prints without its sign. The value itself is not moved:
    the verdict is read from it, and only the print follows."""
    verdict = reads(value)
    for p in (places, places + 1):
        text = degrees_text(value, p, circle=circle)
        if reads(float(text)) == verdict:
            return text
    step = 10.0 ** -(places + 1)
    near = float(degrees_text(value, places + 1, circle=circle))
    for candidate in ((near - step, near + step) if value < near else (near + step, near - step)):
        text = degrees_text(candidate, places + 1, circle=circle)
        if reads(float(text)) == verdict:
            return text
    return degrees_text(value, places + 1, circle=circle)

def bound_sides(bounds):
    """A verdict reader for a set of bounds: on which side of each, and
    whether on it. A number read back through it agrees with its value only
    when the rounding has carried it across none of them and onto none of
    them (verdict_text), whichever way each bound is read, inclusive or
    exclusive."""
    return lambda v: tuple((v < b, v <= b) for b in bounds)

def in_sign_text(degree, places=1):
    """A degree in a sign, [0, 30], to `places` decimals, rounded, that does
    not carry past its sign: a planet 29.999 degrees into Aries printed
    "30.0° Ari", and a counterpart degree a hair under its sign's far edge
    "30.0", as if it were the edge (N07). A value below 30 prints the last
    value below it; 30 itself (a counterpart at the sign's far edge, 57 and
    62) prints 30."""
    text = f"{float(degree):.{places}f}"
    if degree < 30.0 and float(text) >= 30.0:
        text = f"{30.0 - 10.0 ** -places:.{places}f}"
    return text

class CircleLongitude(float):
    """A longitude a table carries as the calculation's float, which the
    JSON keeps whole (it is a float) and the HTML and Markdown reports print
    as the page prints it, through degrees_text on the circle (_export_cell):
    a value a hair under 0 Aries prints 359.9999, never 360, and a signed
    zero prints 0 (SL's check, findings 4 and 8); a value a hair under any
    sign's end prints the last value below it, never the next sign's first
    (N01)."""
    __slots__ = ()

def _planets_on_circle(planetary_data):
    """planetary_data with every longitude in [0, 360), for a reader that
    takes signs or degrees in the sign from the raw value: the mapping
    itself when each already is (as every longitude the ephemeris returns
    is), else a copy whose stray entries carry _on_circle's longitude, so
    -1e-16 reads as 0 Aries and not as Pisces (K-16)."""
    def stray(entry):
        lon = entry.get('longitude') if isinstance(entry, dict) else None
        return isinstance(lon, (int, float)) and not 0.0 <= lon < 360.0
    if not any(stray(entry) for entry in planetary_data.values()):
        return planetary_data
    return {name: (dict(entry, longitude=_on_circle(entry['longitude'])) if stray(entry) else entry)
            for name, entry in planetary_data.items()}

def _lon_attr(longitude):
    """A longitude as a wheel's data-lon attribute: six places, in
    [0, 360). A value that rounds up to 360 at six places is 0 Aries."""
    text = f"{_on_circle(longitude):.6f}"
    return '0.000000' if text == '360.000000' else text

def _whole_minutes(longitude):
    """(whole degrees from 0 Aries, minute): the one rounding rule shared by
    get_degree_string and the wheel, so they cannot drift.

    The tolerance's carry stops at a sign boundary: a longitude within it
    below a sign's end prints 29° 59' of its own sign, never 00° 00' of the
    next, so the printed sign is always the sign get_zodiac_sign reads from
    the float (60 - 1e-10 prints 29° Tau 59', and the engine reads Taurus)."""
    on_circle = longitude % 360.0
    total = on_circle * 60.0
    nearest = round(total)
    if abs(total - nearest) < 1e-6:
        total = nearest
    total = int(total) % (360 * 60)
    sign = int(on_circle // 30) % 12                  # get_zodiac_sign's own index
    if total // 1800 != sign:                         # carried (or float-rounded) over the boundary
        total = sign * 1800 + 1799
    return divmod(total, 60)

def get_degree_string(longitude):
    """A longitude as DD° Sgn MM'. Display policy: whole arcminutes,
    TRUNCATED (12°27'40" prints 27'), with one tolerance -- a value within a
    millionth of a minute of a whole minute IS that minute. Binary floats
    put 30 + 1/60 a hair under 00° Tau 01' and int() printed 00' (Astra
    F13); an entered whole minute now survives display. The carry at 60'
    follows from working in total minutes; it stops at a sign boundary
    (owner's ruling, 2026-10-05): a value within the tolerance below a
    sign's end prints 29° 59' of its own sign, so the printed sign is the
    sign every table reads. Nothing here rounds the longitude itself; bound
    and degree tests read the float."""
    deg_total, minute = _whole_minutes(longitude)
    return f"{deg_total % 30:02d}° {SIGN_ORDER[deg_total // 30][:3]} {minute:02d}'"

# ---- The chart wheel ---------------------------------------------------
# Redesigned 2026-09-07 (brief: process/tae_docs/WHEEL_REDESIGN_2026-09-07.md, decisions
# D1-D10). generate_hybrid_svg() is a pure function -- no Streamlit calls --
# returning an SVG string that the Chart page shows through st.image(), which
# wraps it in Streamlit's own fullscreen control, the same expand arrows the
# tables carry. Inside an <img> the SVG has no page CSS, web fonts or scripts,
# so everything here is attributes and system fonts.
#
# Rings, outside in: a rim band with the WHOLE-SIGN place numbers; the sign
# band with the glyphs, shaded by triplicity, and a one-degree scale on its
# inner edge; the planet zone, where each point's label runs radially --
# glyph, degree, sign, minute, and a black retrograde mark -- as the owner's
# reference charts draw it; a narrow ring with the ALCHABITIUS house numbers;
# and the hub, which names the chart. The rising sign's boundary sits at
# 9 o'clock (D1: the app's own convention, kept), so whole-sign places fall on
# the twelve clock positions. Alchabitius cusps stay dashed (the app's
# convention) and now run from the quadrant ring to the degree scale.
WHEEL_LAYOUT_OPTIONS = ('Square', 'Wide')
WHEEL_SIZE = 1000                     # viewBox of the square wheel
WHEEL_WIDE_WIDTH = 1760               # the wide variant: wheel plus a positions panel
_R_RIM, _R_WS_IN, _R_SIGN_IN = 492, 462, 402
_R_GLYPH, _R_DEG, _R_SIGN, _R_MIN, _R_RX = 344, 306, 272, 242, 214
_R_Q_OUT, _R_Q_IN = 152, 122
_R_BOUNDS_BAND = 24                   # the Egyptian-bounds ring, inside the degree scale, when drawn
LABEL_MIN_SEP = 10.5                  # degrees between neighbouring label stacks
LABEL_STAGGER = 30                    # px inward for alternate members of a crowded run
# One tint per triplicity (D3): fire, earth, air, water; sign i uses i % 4.
TRIPLICITY_TINT = ('#f7f7f7', '#dedede', '#ededed', '#cdcdcd')
_WHEEL_FONT = "'TAE Symbols', 'Noto Sans Symbols', 'Segoe UI Symbol', 'DejaVu Sans', sans-serif"
_CUSP_COLOUR = '#a94442'
_AXIS_COLOUR = {0: '#0000cc', 6: '#0000cc', 9: '#1e7b1e', 3: '#1e7b1e'}   # horizon blue, meridian green (D4)
_VS = '︎'                        # text-presentation selector: never an emoji
SIGN_GLYPHS = ['♈', '♉', '♊', '♋', '♌', '♍',
               '♎', '♏', '♐', '♑', '♒', '♓']
POINT_GLYPHS = {'Sun': '☉', 'Moon': '☽', 'Mercury': '☿', 'Venus': '♀',
                'Mars': '♂', 'Jupiter': '♃', 'Saturn': '♄',
                'North Node': '☊', 'South Node': '☋', 'Lot of Fortune': '⊗'}

# A set of names is walked in an order that follows Python's string hashing,
# which is seeded afresh each time the app starts: the same chart could name
# a different planet first, or a different planet at all, after a restart.
# Anything that walks a set on its way to a page or the export walks it
# through this instead, in the order the tables list the planets -- the
# chart's own, Sun, Moon, Mercury, Venus, Mars, Jupiter, Saturn -- then the
# points, then anything else by name.
def in_planet_order(names):
    order = list(POINT_GLYPHS)
    return sorted(names, key=lambda name: (order.index(name) if name in order else len(order), str(name)))


def _spread_labels(bearings, min_sep=LABEL_MIN_SEP):
    """Push neighbouring bearings apart on the circle until every adjacent
    pair is at least min_sep degrees apart. bearings are in ascending order
    around the circle; that circular order is preserved and the result
    comes back in the same order. Input already separated is unchanged.

    The sequence is unwrapped to a monotone one first and the gaps kept
    SIGNED, so a pair pushed apart cannot leapfrog its neighbours (a
    modular gap would read the overshoot as a wide gap and leave the order
    scrambled). A negative gap is a violation like any other and is pushed
    open on the next sweep."""
    n = len(bearings)
    if n < 2:
        return [b % 360.0 for b in bearings]
    min_sep = min(min_sep, 0.9 * 360.0 / n)       # n labels must fit the circle
    pos = [bearings[0] % 360.0]
    for b in bearings[1:]:
        b = b % 360.0
        while b < pos[-1]:
            b += 360.0
        pos.append(b)
    for _ in range(1000):
        moved = False
        for k in range(n):
            j = (k + 1) % n
            gap = (pos[j] + (360.0 if j == 0 else 0.0)) - pos[k]
            if gap < min_sep - 1e-6:
                push = (min_sep - gap) / 2.0
                pos[k] -= push
                pos[j] += push
                moved = True
        if not moved:
            break
    return [p % 360.0 for p in pos]


def _stagger_offsets(true_bearings, shown_bearings, step=LABEL_STAGGER):
    """Within each run of consecutive displaced labels, every other one
    steps inward by `step` px, as Solar Fire does for stellia."""
    displaced = [abs(((s - t + 180.0) % 360.0) - 180.0) > 0.05 for s, t in zip(shown_bearings, true_bearings)]
    offsets = [0] * len(displaced)
    k = 0
    while k < len(displaced):
        if displaced[k]:
            end = k
            while end < len(displaced) and displaced[end]:
                end += 1
            for n, idx in enumerate(range(k, end)):
                offsets[idx] = step if n % 2 else 0
            k = end
        else:
            k += 1
    return offsets


def _wheel_dm(longitude):
    """Degree and minute within the sign, minutes truncated exactly as
    get_degree_string() truncates them (one shared helper), so the wheel and the tables agree."""
    deg_total, minute = _whole_minutes(longitude)
    return deg_total % 30, minute


def _wheel_sign(longitude):
    """The index (0-11) of the sign the wheel prints beside _wheel_dm's
    degree and minute: the sign of the same carried total, as
    get_degree_string prints it. The carry stops at a sign boundary, so
    60 - 1e-10 prints 29° Tau 59' in the table and on the wheel alike.
    Where the point is DRAWN stays the float."""
    return _whole_minutes(longitude)[0] // 30


def generate_hybrid_svg(chart_data, chart_name, location_query, lat, lon, dt_local, tz_name,
                        wide=False, chronocrats=None, bounds=False, theme=None):
    pal = _wheel_palette(theme)
    size = WHEEL_SIZE
    cx = cy = size / 2.0
    asc = chart_data['ascendant']
    mc = chart_data['mc']
    cusps = chart_data['houses']
    asc_sign = int((asc % 360.0) // 30)
    angles = (asc, mc, (asc + 180.0) % 360.0, (mc + 180.0) % 360.0)

    # D1: the rising sign's boundary at 9 o'clock, zodiac counter-clockwise.
    # The geometry and the two primitives are shared with the multi-ring
    # wheels of the Timing page (2026-09-10).
    ang, xy, sector, _arc = _wheel_geometry(asc_sign, cx, cy)
    line, text = _svg_line, _svg_text
    # An Egyptian-bounds ring inside the degree scale (2026-09-10): PN IV's
    # nativities carry one (Figures 1, 22 and 25), and the revolution of
    # Figure 26 does; Figure 51, the simplified I.6 wheel, does not. It sits in
    # the leader zone, so the planet stack is not moved.
    r_planet_edge = _R_SIGN_IN - _R_BOUNDS_BAND if bounds else _R_SIGN_IN

    def sign_glyph(longitude):
        return SIGN_GLYPHS[_wheel_sign(longitude)] + _VS

    width = WHEEL_WIDE_WIDTH if wide else size
    svg = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {size}" width="{width}" height="{size}" '
           f'style="font-family:{_WHEEL_FONT}">',
           f'<style>{font_face_css()}</style>',
           f'<rect width="{width}" height="{size}" fill="{pal["bg"]}"/>']

    # 1. Sign band shaded by triplicity, sign glyphs, whole-sign place
    #    numbers on the rim, boundary spokes through both bands.
    #
    #    Each sign's own elements stand in a <g class="sign" data-sign="0-11">
    #    and each point's in a <g class="pt" data-point data-lon>, the
    #    convention the revolution wheels have carried since 2026-09-10
    #    (_draw_ring_points). The groups add a handle and nothing else: strip
    #    the wrappers and the picture is the picture it always was, which is
    #    what tests/test_clickable_wheel_2026_09_15.py asserts against main.
    for i in range(12):
        a0, a1 = ang(i * 30), ang(i * 30 + 30)
        svg.append(f'<g class="sign" data-sign="{_esc_attr(i)}">')
        svg.append(f'<path d="{sector(_R_SIGN_IN, _R_WS_IN, a0, a1)}" fill="{pal["tints"][i % 4]}"/>')
        svg.append(f'<path d="{sector(_R_WS_IN, _R_RIM, a0, a1)}" fill="{pal["panel"]}"/>')
        # An angle box (step 4) sits wherever the Ascendant or MC falls in its
        # sign; a glyph within 7 degrees of one steps 8 degrees aside.
        glyph_lon = i * 30 + 15
        for angle_lon in angles:
            gap = ((angle_lon - glyph_lon + 180.0) % 360.0) - 180.0
            if abs(gap) < 7.0:
                glyph_lon = i * 30 + 15 - (8 if gap > 0 else -8)
        gx, gy = xy((_R_SIGN_IN + _R_WS_IN) / 2, ang(glyph_lon))
        svg.append(text(gx, gy, SIGN_GLYPHS[i] + _VS, 30, fill=pal['ink']))
        hx, hy = xy((_R_WS_IN + _R_RIM) / 2, ang(i * 30 + 15))
        svg.append(text(hx, hy, str((i - asc_sign) % 12 + 1), 17, 'bold', pal['ink']))
        x0, y0 = xy(_R_SIGN_IN, a0); x1, y1 = xy(_R_RIM, a0)
        svg.append(line(x0, y0, x1, y1, pal['rule'], 1.2))
        svg.append('</g>')

    # 2. Degree scale on the inner edge of the sign band: 1, 5 and 10 degrees.
    for d in range(360):
        ln = 14 if d % 10 == 0 else 10 if d % 5 == 0 else 5
        x0, y0 = xy(_R_SIGN_IN, ang(d)); x1, y1 = xy(_R_SIGN_IN + ln, ang(d))
        svg.append(line(x0, y0, x1, y1, pal['rule'], 0.9 if ln > 5 else 0.5))
    if bounds:
        svg.extend(_bounds_ring_svg(ang, xy, sector, r_planet_edge, _R_SIGN_IN, glyph_px=12, pal=pal))
    for r, w in ((_R_RIM, 2.5), (_R_WS_IN, 1.2), (_R_SIGN_IN, 1.6), (_R_Q_OUT, 1.2), (_R_Q_IN, 1.6)):
        svg.append(f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="{pal["rule"]}" stroke-width="{w}"/>')

    # 3. Alchabitius cusps, dashed as before but reaching the degree scale;
    #    the four stakes solid and coloured. House numbers at mid-house on
    #    the quadrant ring.
    for i, cusp_lon in enumerate(cusps):
        x0, y0 = xy(_R_Q_IN, ang(cusp_lon)); x1, y1 = xy(r_planet_edge, ang(cusp_lon))
        if i in pal['axis']:
            svg.append(line(x0, y0, x1, y1, pal['axis'][i], 2.6))
        else:
            svg.append(line(x0, y0, x1, y1, pal['cusp'], 1.4, '6 4'))
        mid = cusp_lon + ((cusps[(i + 1) % 12] - cusp_lon) % 360.0) / 2.0
        mx, my = xy((_R_Q_OUT + _R_Q_IN) / 2, ang(mid))
        svg.append(text(mx, my, str(i + 1), 14, 'bold', pal['cusp']))

    # 4. Angle boxes on the sign band: degree over minute, in the axis colour.
    #    The four angles carry data-point under the names the Calculated
    #    Points table prints, so a click on a box reaches the same panel a
    #    click on a planet does.
    for angle_lon, colour, angle_name in zip(angles, (pal['horizon'], pal['meridian'], pal['horizon'], pal['meridian']),
                                             ('Ascendant', 'Midheaven', 'Descendant', 'Imum Coeli')):
        d, m = _wheel_dm(angle_lon)
        svg.append(f'<g class="pt" data-point="{_esc_attr(angle_name)}" data-lon="{_lon_attr(angle_lon)}">')
        bx, by = xy((_R_SIGN_IN + _R_WS_IN) / 2, ang(angle_lon))
        svg.append(f'<rect x="{bx - 19:.1f}" y="{by - 17:.1f}" width="38" height="34" rx="3" '
                   f'fill="{pal["panel"]}" stroke="{colour}" stroke-width="1.2"/>')
        svg.append(text(bx, by - 8, f'{d:02d}°', 13, 'bold', colour))
        svg.append(text(bx, by + 8, f"{m:02d}'", 13, 'bold', colour))
        svg.append('</g>')

    # 5. Points. The seven planets and the north node from the ephemeris, the
    #    south node opposite it with the same motion (D2), the Lot of Fortune
    #    with no motion. A retrograde mark goes on any point whose longitude
    #    speed is negative, nodes included (D9): the true node has direct
    #    spells and is shown as it moves.
    p_data = chart_data['planetary_data']
    node = p_data['North Node']
    points = [(name, d['longitude'], d.get('speed_in_lon', 0.0)) for name, d in p_data.items()]
    points.append(('South Node', (node['longitude'] + 180.0) % 360.0, node.get('speed_in_lon', 0.0)))
    points.append(('Lot of Fortune', chart_data['lot_of_fortune'], None))
    points.sort(key=lambda p: ang(p[1]))
    true_bearings = [ang(p[1]) for p in points]
    shown = _spread_labels(true_bearings)
    offsets = _stagger_offsets(true_bearings, shown)
    for (name, lon_val, speed), a_true, a_shown, off in zip(points, true_bearings, shown, offsets):
        # A tick on the ring at the true degree, a hairline from it to the glyph.
        svg.append(f'<g class="pt" data-point="{_esc_attr(name)}" data-lon="{_lon_attr(lon_val)}">')
        x0, y0 = xy(r_planet_edge, a_true); x1, y1 = xy(r_planet_edge - 10, a_true)
        svg.append(line(x0, y0, x1, y1, pal['rule'], 1.6))
        x2, y2 = xy(_R_GLYPH - off + 22, a_shown)
        svg.append(line(x1, y1, x2, y2, pal['leader'], 0.8))
        d, m = _wheel_dm(lon_val)
        gx, gy = xy(_R_GLYPH - off, a_shown); svg.append(text(gx, gy, POINT_GLYPHS.get(name, name[:2]) + _VS, 34, fill=pal['ink']))
        dx_, dy_ = xy(_R_DEG - off, a_shown); svg.append(text(dx_, dy_, f'{d:02d}°', 18, 'bold', pal['ink']))
        sx, sy = xy(_R_SIGN - off, a_shown); svg.append(text(sx, sy, sign_glyph(lon_val), 19, fill=pal['ink']))
        mx, my = xy(_R_MIN - off, a_shown); svg.append(text(mx, my, f"{m:02d}'", 15, fill=pal['ink']))
        if speed is not None and motion_state(name, speed) == 'retrograde':
            rx, ry = xy(_R_RX - off, a_shown); svg.append(text(rx, ry, '℞' + _VS, 15, fill=pal['ink']))   # the ink, never red (D6)
        svg.append('</g>')

    # 6. Hub: the chart's name first (D5 supplies "Transits" when none was
    #    given), then when, where, and the systems in force. User strings
    #    are escaped: a name or place with & or < would otherwise break the
    #    whole wheel. The name and the place are isolated (_isolated), as the
    #    page sets them, so an override in either ends with it (SB-08).
    svg.append(f'<circle cx="{cx}" cy="{cy}" r="{_R_Q_IN - 1}" fill="{pal["panel"]}"/>')
    name = str(chart_name)
    if len(name) > 30:
        name = name[:29] + '…'
    name_px = 17 if len(name) <= 16 else 14 if len(name) <= 22 else 11
    lat_s = f"{int(abs(lat))}°{int((abs(lat) % 1) * 60):02d}′{'N' if lat >= 0 else 'S'}"
    lon_s = f"{int(abs(lon))}°{int((abs(lon) % 1) * 60):02d}′{'E' if lon >= 0 else 'W'}"
    hub_lines = [
        (_esc_text(_isolated(name)), name_px, 'bold'),
        (f'{dt_local.day} {dt_local:%b} {dt_local.year}  {dt_local:%H:%M}', 12, 'normal'),
        (_esc_text(tz_name), 11, 'normal'),
        (_esc_text(_isolated(str(location_query))), 12, 'normal'),
        (f'{lat_s}  {lon_s}', 11, 'normal'),
        (_esc_text(chart_data['sect']), 12, 'bold'),
        ('Whole sign · Alchabitius', 10, 'normal'),
        ('Tropical · True node', 10, 'normal'),
    ]
    y = cy - 7 * len(hub_lines)
    for s, px, w in hub_lines:
        svg.append(text(cx, y, s, px, w, pal['ink']))
        y += 14

    # 7. The wide variant: a positions panel beside the wheel, so a full-
    #    window view uses the window's width as well as its height (D10).
    if wide:
        x0 = size + 40
        svg.append(text(x0, 60, 'Positions', 22, 'bold', pal['ink'], anchor='start'))
        for dx, h in ((0, 'Point'), (150, 'Position'), (330, 'WS place'), (460, 'Quadrant'), (590, 'Motion')):
            svg.append(text(x0 + dx, 100, h, 15, 'bold', pal['label'], anchor='start'))
        svg.append(line(x0, 112, x0 + 680, 112, pal['rule'], 1))
        y = 140
        for name_, lon_val, speed in sorted(points, key=lambda p: list(POINT_GLYPHS).index(p[0]) if p[0] in POINT_GLYPHS else 99):
            d, m = _wheel_dm(lon_val)
            if speed is None:
                motion = '–'
            else:
                motion = motion_state(name_, speed)
                motion = '℞' + _VS + ' retrograde' if motion == 'retrograde' else motion
            svg.append(text(x0, y, POINT_GLYPHS.get(name_, '') + _VS, 22, fill=pal['ink'], anchor='start'))
            svg.append(text(x0 + 34, y, _esc_text(name_), 16, fill=pal['ink'], anchor='start'))
            svg.append(text(x0 + 150, y, f'{d:02d}° {sign_glyph(lon_val)} {m:02d}′', 16, fill=pal['ink'], anchor='start'))
            svg.append(text(x0 + 330, y, str(get_wsh_house(lon_val, asc)), 16, fill=pal['ink'], anchor='start'))
            svg.append(text(x0 + 460, y, str(get_effective_house(lon_val, cusps)), 16, fill=pal['ink'], anchor='start'))
            svg.append(text(x0 + 590, y, motion, 15, fill=pal['ink'], anchor='start'))
            y += 36
        y += 20
        svg.append(text(x0, y, 'Angles and cusps (Alchabitius)', 18, 'bold', pal['ink'], anchor='start'))
        y += 34
        for i, cusp_lon in enumerate(cusps):
            d, m = _wheel_dm(cusp_lon)
            label = {0: 'Asc', 3: 'IC', 6: 'Des', 9: 'MC'}.get(i, '')
            col = x0 + (0 if i < 6 else 340)
            yy = y + (i % 6) * 32
            svg.append(text(col, yy, f'{i + 1:2d}', 15, 'bold', pal['cusp'], anchor='start'))
            svg.append(text(col + 40, yy, f'{d:02d}° {sign_glyph(cusp_lon)} {m:02d}′', 15, fill=pal['ink'], anchor='start'))
            if label:
                svg.append(text(col + 190, yy, label, 15, 'bold', pal['axis'][i], anchor='start'))
        y += 6 * 32 + 20
        sect_line = f"Sect: {_esc_text(chart_data['sect'])}"
        if chronocrats:
            sect_line += (f" · Lord of the day: {_esc_text(day_lord_qualified(chronocrats))}"
                          f" · Lord of the hour: {_esc_text(hour_lord_qualified(chronocrats))}")
        svg.append(text(x0, y, sect_line, 15, fill=pal['ink'], anchor='start'))

    svg.append('</svg>')
    return ''.join(svg)


# ---- Multi-ring wheels and direction strips for the Timing page (2026-09-10) ----
# Built from the book's own figures (UI_CHART_INPUT_EVALUATION_2026-09-10.md
# §6). The revolution over the root is PN IV I.6 (Figure 51, fn 33); the
# month over the year and the root is IX.3, 4-6 (Figures 39 and 109, fn 58);
# the profection is Figures 3, 15 and 33. What Dykes' wheels carry, read
# from the images: the outer charts in whole signs, the sign of the year
# shaded, the profection as a dashed arc from the natal Ascendant, an
# Egyptian-bounds ring, and "only the seven traditional planets, the Nodes,
# Lot of Fortune, and axial degrees" (p. 12) unless more is asked for. On
# the order: "Abu Ma'shar seems to prefer that the SR be the inner wheel,
# but to me this seem unnatural and I only do it to illustrate his
# instructions in Ch. I.6" (p. 12) -- the caller chooses; the page offers
# both. Pure functions, no Streamlit, SVG strings out; every point carries
# data- attributes so a test can hold the picture to the inventory table.

_M_RIM, _M_SIGN_IN, _M_BOUNDS_IN, _M_HUB_RING, _M_HUB = 478, 430, 408, 150, 118
WHEEL_RING_COLOURS = ('#000000', '#1f3a93', '#8b1a1a')     # inner, middle, outer ring text
WHEEL_SHADE = '#e2e2e2'                                    # the sign of the year (fn 33)
WHEEL_BOUND_TINT = '#ffe08a'                               # the bound the distribution stands in
WHEEL_ORDER_OPTIONS = ("Nativity inside (Dykes)", "Revolution inside (Abu Ma'shar's order, PN IV I.6)")
WHEEL_VIEW_OPTIONS = ("Year", "Year over root", "Month over year and root", "Month", "Profection")
_ASPECT_GLYPH = {'body': '☌', 'sextile': '⚹', 'square': '□', 'trine': '△', 'opposition': '☍'}


def _wheel_geometry(asc_sign, cx=500.0, cy=500.0):
    """ang/xy/sector for a wheel whose rising SIGN's boundary sits at
    9 o'clock (D1), the zodiac running counter-clockwise."""
    def ang(longitude):
        return (longitude - asc_sign * 30 + 180.0) % 360.0

    def xy(r, a):
        t = math.radians(a)
        return cx + r * math.cos(t), cy - r * math.sin(t)

    def sector(r_in, r_out, a0, a1):
        x0o, y0o = xy(r_out, a0); x1o, y1o = xy(r_out, a1)
        x0i, y0i = xy(r_in, a0); x1i, y1i = xy(r_in, a1)
        large = 1 if (a1 - a0) % 360 > 180 else 0
        return (f'M{x0o:.1f},{y0o:.1f} A{r_out},{r_out} 0 {large} 0 {x1o:.1f},{y1o:.1f} '
                f'L{x1i:.1f},{y1i:.1f} A{r_in},{r_in} 0 {large} 1 {x0i:.1f},{y0i:.1f} Z')

    def arc(r, a0, a1):
        """An open arc from bearing a0 to a1 the zodiacal way round."""
        x0, y0 = xy(r, a0); x1, y1 = xy(r, a1)
        large = 1 if (a1 - a0) % 360 > 180 else 0
        return f'M{x0:.1f},{y0:.1f} A{r},{r} 0 {large} 0 {x1:.1f},{y1:.1f}'

    return ang, xy, sector, arc


def _svg_line(x0, y0, x1, y1, stroke, width, dash=None):
    d = f' stroke-dasharray="{dash}"' if dash else ''
    return f'<line x1="{x0:.1f}" y1="{y0:.1f}" x2="{x1:.1f}" y2="{y1:.1f}" stroke="{stroke}" stroke-width="{width}"{d}/>'


def _svg_text(x, y, s, px, weight='normal', fill='#000', anchor='middle', rotate=None, cls=None):
    rot = f' transform="rotate({rotate:.1f} {x:.1f} {y:.1f})"' if rotate is not None else ''
    c = f' class="{cls}"' if cls else ''
    return (f'<text{c} x="{x:.1f}" y="{y:.1f}" text-anchor="{anchor}" dominant-baseline="central" '
            f'font-size="{px}" font-weight="{weight}" fill="{fill}"{rot}>{s}</text>')


def _svg_arrowhead(xy, r, a, colour, size=9, forward=True):
    """A small filled triangle at bearing a on radius r, pointing the
    zodiacal way (forward) along the circle."""
    tip_a = a + (1.2 if forward else -1.2) * (size * 0.5) * 57.2958 / r
    tx, ty = xy(r, tip_a)
    bx1, by1 = xy(r + size * 0.6, a)
    bx2, by2 = xy(r - size * 0.6, a)
    return f'<polygon points="{tx:.1f},{ty:.1f} {bx1:.1f},{by1:.1f} {bx2:.1f},{by2:.1f}" fill="{colour}"/>'


def _bounds_ring_svg(ang, xy, sector, r_in, r_out, highlight=None, glyph_px=12, pal=None):
    """The Egyptian bounds as a ring, a cell per bound with its lord's
    glyph, as every PN IV wheel carries (Figures 1, 22, 25, 26, 109).
    `highlight` is a longitude whose bound is tinted -- the bound the
    distribution stands in. Every cell is class="bound"."""
    pal = pal or _PALETTE_LIGHT
    out = []
    if highlight is not None:
        highlight = _on_circle(highlight)                # -1e-16 tints Aries' first bound (K-16)
    for i, sign in enumerate(SIGN_ORDER):
        start = 0
        for limit, lord in EGYPTIAN_TERMS[sign]:
            a0, a1 = ang(i * 30 + start), ang(i * 30 + limit)
            tint = pal['panel']
            if highlight is not None and int(highlight // 30) == i and start <= (highlight % 30.0) < limit:
                tint = pal['bound_tint']
            out.append(f'<path class="bound" d="{sector(r_in, r_out, a0, a1)}" fill="{tint}" '
                       f'stroke="{pal["rule"]}" stroke-width="0.6"/>')
            mx, my = xy((r_in + r_out) / 2.0, ang(i * 30 + (start + limit) / 2.0))
            out.append(_svg_text(mx, my, POINT_GLYPHS[lord] + _VS, glyph_px, fill=pal['note'], cls='bound-lord'))
            start = limit
    return out


def _wheel_points(chart_data):
    """The points a wheel draws by default (p. 12): the seven planets, the
    nodes, the Lot of Fortune. (name, longitude, speed-or-None)."""
    p_data = chart_data['planetary_data']
    node = p_data['North Node']
    points = [(name, d['longitude'], d.get('speed_in_lon', 0.0)) for name, d in p_data.items()]
    points.append(('South Node', (node['longitude'] + 180.0) % 360.0, node.get('speed_in_lon', 0.0)))
    points.append(('Lot of Fortune', chart_data['lot_of_fortune'], None))
    return points


def _ring_layout(n, bounds):
    """(r_in, r_out) for n chart rings, inner to outer, between the hub
    ring and the bounds ring (or the degree scale)."""
    top = _M_BOUNDS_IN - 4 if bounds else _M_SIGN_IN - 4
    bottom = _M_HUB_RING
    if n == 1:
        return [(bottom, top)]
    if n == 2:
        split = bottom + (top - bottom) * 0.58
        return [(bottom, split), (split, top)]
    a = bottom + (top - bottom) * 0.40
    b = a + (top - bottom) * 0.30
    return [(bottom, a), (a, b), (b, top)]


def _draw_ring_points(svg, ang, xy, ring_idx, label, chart_data, r_in, r_out, colour, badges=None, pal=None):
    """One chart's default points in its annulus: a tick at the true
    degree on the ring's outer edge, a hairline to a radial stack (glyph,
    degree, sign, minute, retrograde mark, badge letters), spread apart
    as the natal wheel spreads them. Each point is a <g class="pt"> with
    data-ring/data-chart/data-point/data-lon."""
    # The stack -- glyph, degree, sign, minute, retrograde, badge -- fits the
    # annulus: sizes scale with its width (capped at the natal wheel's),
    # the lines are laid out between the ring's edges, and the stagger
    # for crowded runs is used only where the ring is wide enough for it.
    pal = pal or _PALETTE_LIGHT
    width = r_out - r_in
    scale = max(0.42, min(1.0, width / 150.0))
    px_glyph, px_deg, px_sign, px_min, px_rx = (round(34 * scale), round(18 * scale), round(19 * scale),
                                                 round(15 * scale), round(14 * scale))
    r_glyph = r_out - 12 - px_glyph * 0.55
    span = min(r_glyph - (r_in + 8), 118.0 * scale + 12.0)
    step = span / 4.6
    r_deg, r_sign, r_min, r_rx = r_glyph - step, r_glyph - 2.0 * step, r_glyph - 2.9 * step, r_glyph - 3.7 * step
    r_badge = r_glyph - 4.6 * step
    points = sorted(_wheel_points(chart_data), key=lambda p: ang(p[1]))
    true_b = [ang(p[1]) for p in points]
    min_sep = max(4.0, (px_glyph + 6) * 57.2958 / r_glyph)
    shown = _spread_labels(true_b, min_sep)
    stagger = round(min(30.0 * scale, max(0.0, width - span - 22.0)))
    offsets = _stagger_offsets(true_b, shown, step=stagger) if stagger >= 8 else [0] * len(points)
    for (name, lon_val, speed), a_true, a_shown, off in zip(points, true_b, shown, offsets):
        d, m = _wheel_dm(lon_val)
        svg.append(f'<g class="pt" data-ring="{ring_idx}" data-chart="{_esc_attr(label)}" data-point="{_esc_attr(name)}" '
                   f'data-lon="{_lon_attr(lon_val)}">')
        x0, y0 = xy(r_out, a_true); x1, y1 = xy(r_out - 8, a_true)
        svg.append(_svg_line(x0, y0, x1, y1, colour, 1.4))
        x2, y2 = xy(r_glyph - off + px_glyph * 0.6, a_shown)
        svg.append(_svg_line(x1, y1, x2, y2, pal['leader_ring'], 0.7))
        gx, gy = xy(r_glyph - off, a_shown); svg.append(_svg_text(gx, gy, POINT_GLYPHS.get(name, name[:2]) + _VS, px_glyph, fill=colour))
        dx_, dy_ = xy(r_deg - off, a_shown); svg.append(_svg_text(dx_, dy_, f'{d:02d}°', px_deg, 'bold', colour))
        sx, sy = xy(r_sign - off, a_shown); svg.append(_svg_text(sx, sy, SIGN_GLYPHS[_wheel_sign(lon_val)] + _VS, px_sign, fill=colour))
        mx, my = xy(r_min - off, a_shown); svg.append(_svg_text(mx, my, f"{m:02d}'", px_min, fill=colour))
        if speed is not None and motion_state(name, speed) == 'retrograde':
            rx, ry = xy(r_rx - off, a_shown); svg.append(_svg_text(rx, ry, '℞' + _VS, px_rx, fill=colour))
        if badges and badges.get(name):
            bx, by = xy(r_badge - off, a_shown)
            svg.append(_svg_text(bx, by, _esc_text(badges[name]), px_rx, 'bold', pal['badge'], cls='badge'))
        svg.append('</g>')


def _draw_ring_extras(svg, ang, xy, ring_idx, label, extras, r_out, colour, pal=None):
    """Optional points (Lots, rays, twelfth-parts): a short tick at the
    ring's outer edge and a tiny label, spread thinly. <g class="extra">."""
    pal = pal or _PALETTE_LIGHT
    if not extras:
        return
    items = sorted(extras, key=lambda e: ang(e[1]))
    true_b = [ang(e[1]) for e in items]
    shown = _spread_labels(true_b, 2.2)
    for item, a_true, a_shown in zip(items, true_b, shown):
        name, lon_val = item[0], item[1]
        short = item[2] if len(item) > 2 else (name if len(name) <= 6 else name[:6])
        svg.append(f'<g class="extra" data-ring="{ring_idx}" data-chart="{_esc_attr(label)}" '
                   f'data-point="{_esc_attr(name)}" data-lon="{_lon_attr(lon_val)}">')
        x0, y0 = xy(r_out, a_true); x1, y1 = xy(r_out - 5, a_true)
        svg.append(_svg_line(x0, y0, x1, y1, colour, 0.8))
        tx, ty = xy(r_out - 12, a_shown)
        svg.append(_svg_text(tx, ty, _esc_text(short) + _VS, 7, fill=colour, rotate=-(a_shown - 90.0) % 360.0 - 90.0))
        svg.append('</g>')


def generate_multiwheel_svg(rings, chart_name, wide=False, bounds=True, shade_sign=None, shade_label='Sign of year',
                            outline_sign=None, outline_label='Sign of month', profection_from=None,
                            distribution=None, marks=(), badges=None, extras=None, hub_lines=(), theme=None):
    """One to three charts on one zodiac. `rings` are dicts inner to outer:
    {'label', 'chart' (a chart_data), 'when' (a short line for the hub)}.
    shade_sign / outline_sign: sign indices 0-11 (the sign of the year,
    the sign of the month). profection_from: a longitude whose sign the
    dashed arc starts from, ending at shade_sign (Figures 3, 33).
    distribution: {'start': lon, 'end': lon} draws the directed
    Ascendant's arc and tints the bound of `end` (Figures 2, 65). marks:
    (label, lon, ring_idx) degrees ticked on a ring's outer edge. badges:
    {ring_idx: {planet: letters}}. extras: {ring_idx: [(name, lon)]}."""
    pal = _wheel_palette(theme)
    rings = list(rings)
    assert 1 <= len(rings) <= 3
    size = WHEEL_SIZE
    cx = cy = size / 2.0
    inner = rings[0]['chart']
    asc_sign = int((inner['ascendant'] % 360.0) // 30)
    ang, xy, sector, arc = _wheel_geometry(asc_sign, cx, cy)
    width = WHEEL_WIDE_WIDTH if wide else size
    svg = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {size}" width="{width}" height="{size}" '
           f'style="font-family:{_WHEEL_FONT}">',
           f'<style>{font_face_css()}</style>',
           f'<rect width="{width}" height="{size}" fill="{pal["bg"]}"/>']
    layout = _ring_layout(len(rings), bounds)
    r_top = layout[-1][1]

    # 0. The shaded sign of the year, under everything (fn 33).
    if shade_sign is not None:
        a0, a1 = ang(shade_sign * 30), ang(shade_sign * 30 + 30)
        svg.append(f'<path class="shade" data-sign="{shade_sign}" d="{sector(_M_HUB, _M_RIM, a0, a1)}" fill="{pal["shade"]}"/>')
    # 1. Sign band, degree scale, spokes through every ring (whole signs are
    #    every chart's houses here, as Dykes draws them).
    for i in range(12):
        a0, a1 = ang(i * 30), ang(i * 30 + 30)
        fill = pal['tints'][i % 4] if shade_sign != i else pal['shade']
        svg.append(f'<path d="{sector(_M_SIGN_IN, _M_RIM, a0, a1)}" fill="{fill}"/>')
        gx, gy = xy((_M_SIGN_IN + _M_RIM) / 2.0 + 6, ang(i * 30 + 15))
        svg.append(_svg_text(gx, gy, SIGN_GLYPHS[i] + _VS, 26, fill=pal['ink']))
        x0, y0 = xy(_M_HUB, a0); x1, y1 = xy(_M_RIM, a0)
        svg.append(_svg_line(x0, y0, x1, y1, pal['rule'], 1.0))
    for d in range(360):
        ln = 12 if d % 10 == 0 else 8 if d % 5 == 0 else 4
        x0, y0 = xy(_M_SIGN_IN, ang(d)); x1, y1 = xy(_M_SIGN_IN + ln, ang(d))
        svg.append(_svg_line(x0, y0, x1, y1, pal['rule'], 0.8 if ln > 4 else 0.45))
    if bounds:
        svg.extend(_bounds_ring_svg(ang, xy, sector, _M_BOUNDS_IN, _M_SIGN_IN,
                                    highlight=(distribution or {}).get('end'), pal=pal))
    for r, w in ((_M_RIM, 2.2), (_M_SIGN_IN, 1.4), (_M_HUB_RING, 1.0), (_M_HUB, 1.4)):
        svg.append(f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="{pal["rule"]}" stroke-width="{w}"/>')
    if outline_sign is not None:
        a0, a1 = ang(outline_sign * 30), ang(outline_sign * 30 + 30)
        svg.append(f'<path class="outline" data-sign="{outline_sign}" d="{sector(_M_HUB, _M_RIM, a0, a1)}" '
                   f'fill="none" stroke="{pal["rule"]}" stroke-width="2.2" stroke-dasharray="7 5"/>')

    # 2. The rings, inner to outer: separator, whole-sign numbers of that
    #    chart, its angles across its own annulus, its points.
    for idx, (ring, (r_in, r_out)) in enumerate(zip(rings, layout)):
        chart = ring['chart']
        colour = pal['rings'][idx if len(rings) > 1 else 0]
        if idx > 0:
            svg.append(f'<circle cx="{cx}" cy="{cy}" r="{r_in}" fill="none" stroke="{pal["rule"]}" stroke-width="1.0"/>')
        c_asc_sign = int((chart['ascendant'] % 360.0) // 30)
        num_r = (_M_HUB + _M_HUB_RING) / 2.0 if idx == 0 else r_out - 9
        for i in range(12):
            nx, ny = xy(num_r, ang(i * 30 + 15 if idx > 0 else i * 30 + 15))
            svg.append(_svg_text(nx, ny, str((i - c_asc_sign) % 12 + 1), 15 if idx == 0 else 10,
                                 'bold', colour, cls='house'))
        a_lo = _M_HUB if idx == 0 else r_in
        for lon_val, col, lab in ((chart['ascendant'], pal['horizon'], 'As'), (chart['mc'], pal['meridian'], 'Mc'),
                                  ((chart['ascendant'] + 180.0) % 360.0, pal['horizon'], 'Ds'),
                                  ((chart['mc'] + 180.0) % 360.0, pal['meridian'], 'Ic')):
            x0, y0 = xy(a_lo, ang(lon_val)); x1, y1 = xy(r_out, ang(lon_val))
            svg.append(_svg_line(x0, y0, x1, y1, col, 2.0 if idx == 0 else 1.5))
            lx, ly = xy(r_out - 9, ang(lon_val) + 2.5 * 57.2958 / r_out * 3)
            svg.append(_svg_text(lx, ly, lab, 9, 'bold', col, cls='angle'))
        _draw_ring_points(svg, ang, xy, idx, ring['label'], chart, r_in, r_out, colour,
                          badges=(badges or {}).get(idx), pal=pal)
        _draw_ring_extras(svg, ang, xy, idx, ring['label'], (extras or {}).get(idx), r_out, colour, pal=pal)

    # 3. Marks: named degrees on a ring's outer edge (the terminal point ...).
    for lab, lon_val, ring_idx in marks:
        r_in, r_out = layout[min(ring_idx, len(layout) - 1)]
        a = ang(lon_val)
        x0, y0 = xy(r_out, a); x1, y1 = xy(r_out - 14, a)
        svg.append(f'<g class="mark" data-point="{_esc_attr(lab)}" data-lon="{_lon_attr(lon_val)}">')
        svg.append(_svg_line(x0, y0, x1, y1, pal['badge'], 2.2))
        tx, ty = xy(r_out - 22, a)
        svg.append(_svg_text(tx, ty, _esc_text(lab), 9, 'bold', pal['badge']))
        svg.append('</g>')

    # 4. The profection: a dashed arc outside the rim from the natal
    #    Ascendant's sign to the sign of the year, arrowhead at the end.
    if profection_from is not None and shade_sign is not None:
        s0 = int(_on_circle(profection_from) // 30)
        if s0 != shade_sign:
            a0, a1 = ang(s0 * 30 + 15), ang(shade_sign * 30 + 15)
            svg.append(f'<path class="profection" d="{arc(_M_RIM + 11, a0, a1)}" fill="none" stroke="{pal["rule"]}" '
                       f'stroke-width="2.4" stroke-dasharray="9 6"/>')
            svg.append(_svg_arrowhead(xy, _M_RIM + 11, a1, pal['rule']))
    # Sign labels run along the arc in the sign band's inner margin,
    # upright on either half of the wheel, as Dykes letters "Sign of year".
    def _tangential(r, lon_val, s, cls):
        a = ang(lon_val)
        rot = (90.0 - a) % 360.0
        if 180.0 < a % 360.0 < 360.0:
            rot += 180.0
        x, y = xy(r, a)
        return _svg_text(x, y, _esc_text(s), 10, 'bold', pal['label'], rotate=rot, cls=cls)
    if shade_sign is not None:
        svg.append(_tangential(_M_SIGN_IN + 15, shade_sign * 30 + 15, shade_label, 'shade-label'))
    if outline_sign is not None:
        svg.append(_tangential(_M_SIGN_IN + 15 if outline_sign != shade_sign else _M_SIGN_IN + 26,
                               outline_sign * 30 + 15, outline_label, 'outline-label'))

    # 5. The distribution: the directed Ascendant from its degree to the
    #    degree the caller passes (the revolution's, on the Year over root
    #    view), solid, on the inner edge of the bounds ring.
    if distribution:
        r_arc = r_top + 1
        a0, a1 = ang(distribution['start']), ang(distribution['end'])
        svg.append(f'<path class="distribution" data-start="{distribution["start"] % 360.0:.6f}" '
                   f'data-end="{distribution["end"] % 360.0:.6f}" d="{arc(r_arc, a0, a1)}" fill="none" '
                   f'stroke="{pal["horizon"]}" stroke-width="2.6"/>')
        svg.append(_svg_arrowhead(xy, r_arc, a1, pal['horizon'], size=11))

    # 6. Hub: the name, then one line per ring, inner first.
    svg.append(f'<circle cx="{cx}" cy="{cy}" r="{_M_HUB - 1}" fill="{pal["panel"]}"/>')
    name = str(chart_name)
    if len(name) > 30:
        name = name[:29] + '…'
    lines = [(_esc_text(_isolated(name)), 15 if len(name) <= 18 else 12, 'bold', pal['rings'][0])]
    for idx, ring in enumerate(rings):
        colour = pal['rings'][idx if len(rings) > 1 else 0]
        place = ('Inner', 'Middle', 'Outer')[idx] if len(rings) == 3 else ('Inner', 'Outer')[idx] if len(rings) == 2 else ''
        head = f"{place}: {ring['label']}" if place else ring['label']
        lines.append((_esc_text(head), 11, 'bold', colour))
        if ring.get('when'):
            lines.append((_esc_text(ring['when']), 9, 'normal', colour))
    for s in hub_lines:
        lines.append((_esc_text(s), 9, 'normal', pal['note']))
    y = cy - 6.5 * (len(lines) - 1)
    for s, px, w, col in lines:
        svg.append(_svg_text(cx, y, s, px, w, col))
        y += 13

    # 7. Wide: a positions column per ring.
    if wide:
        col_w = (width - size - 60) / len(rings)
        for idx, ring in enumerate(rings):
            colour = pal['rings'][idx if len(rings) > 1 else 0]
            x0 = size + 40 + idx * col_w
            svg.append(_svg_text(x0, 60, _esc_text(ring['label']), 18, 'bold', colour, anchor='start'))
            if ring.get('when'):
                svg.append(_svg_text(x0, 84, _esc_text(ring['when']), 11, fill=colour, anchor='start'))
            svg.append(_svg_line(x0, 98, x0 + col_w - 30, 98, pal['rule'], 1))
            chart = ring['chart']
            y = 122
            pts = sorted(_wheel_points(chart), key=lambda p: list(POINT_GLYPHS).index(p[0]) if p[0] in POINT_GLYPHS else 99)
            for name_, lon_val, speed in pts:
                d, m = _wheel_dm(lon_val)
                motion = '℞' + _VS if speed is not None and motion_state(name_, speed) == 'retrograde' else ''
                svg.append(_svg_text(x0, y, POINT_GLYPHS.get(name_, '') + _VS, 18, fill=colour, anchor='start'))
                svg.append(_svg_text(x0 + 30, y, f'{d:02d}° {SIGN_GLYPHS[_wheel_sign(lon_val)]}{_VS} {m:02d}′ {motion}',
                                     14, fill=colour, anchor='start'))
                svg.append(_svg_text(x0 + col_w - 50, y, str(get_wsh_house(lon_val, chart['ascendant'])), 13, fill=colour))
                y += 28
            y += 10
            for lon_val, lab in ((chart['ascendant'], 'Asc'), (chart['mc'], 'MC')):
                d, m = _wheel_dm(lon_val)
                svg.append(_svg_text(x0, y, lab, 13, 'bold', colour, anchor='start'))
                svg.append(_svg_text(x0 + 30, y, f'{d:02d}° {SIGN_GLYPHS[_wheel_sign(lon_val)]}{_VS} {m:02d}′',
                                     14, fill=colour, anchor='start'))
                y += 26
            svg.append(_svg_text(x0, y, f"Sect: {_esc_text(chart['sect'])}", 12, fill=colour, anchor='start'))

    svg.append('</svg>')
    return ''.join(svg)


# ---- Direction strips --------------------------------------------------------
# The four distributions as timelines (evaluation B.4): one bar per bound
# tinted by its distributor, the distributor's glyph in it, a full-height
# line where the bound changes and a half tick where only the partner
# does, and the present as a red line. PN IV prints distributions as a
# table with dates (Figure 22) and as an arc on the wheel (Figures 2, 65);
# nothing in the book replaces a timeline, and a student needs one.
# 1200 x 240 (was 1600 x 170, 2026-09-22): the page shows a strip in a
# column about 550 px wide, so a 1600-wide canvas drew its glyphs at a
# third of their size; the narrower canvas with taller bars puts a
# distributor's glyph at about 12 px on screen instead of 7.
STRIP_WIDTH, STRIP_HEIGHT = 1200, 240
STRIP_TINT = {'Saturn': '#d9d9d9', 'Jupiter': '#cfe0f5', 'Mars': '#f5cdc7', 'Sun': '#fbe9a6',
              'Venus': '#d4efd0', 'Mercury': '#f8ddb8', 'Moon': '#e2d9f3'}


# ---- The two palettes ---------------------------------------------------
# Every picture used to be drawn on an opaque white rectangle with black
# ink, so a reader in the dark theme got a white square on a dark page.
# The renderers take theme=: None is the palette above, exactly as it has
# always been drawn, and 'dark' is the same picture on Streamlit's own
# dark ground. One dict per theme, read once at the top of a renderer; the
# geometry does not know which it is drawing in.
_PALETTE_LIGHT = {
    'bg': '#ffffff',            # the picture's ground
    'panel': '#ffffff',         # opaque fills over it: the rim band, the angle boxes, the hub, a bound's cell
    'ink': '#000',              # text, where _svg_text's own default was taken
    'rule': '#000000',          # circles, spokes, the degree scale, a strip's axis
    'leader': '#666666',        # the hairline from a point's tick to its glyph (the natal wheel)
    'leader_ring': '#777777',   # the same on a revolution ring
    'label': '#444444',         # the wide panel's column heads, the sign-of-year lettering
    'note': '#333333',          # a bound's lord, the hub's added lines, a strip's partner
    'axis_note': '#555555',     # the strip's axis caption
    'tints': TRIPLICITY_TINT,   # the sign band by triplicity
    'shade': WHEEL_SHADE,
    'bound_tint': WHEEL_BOUND_TINT,
    'axis': _AXIS_COLOUR,       # by cusp index
    'horizon': '#0000cc',       # Ascendant and Descendant, and the distribution's arc
    'meridian': '#1e7b1e',      # MC and IC
    'cusp': _CUSP_COLOUR,
    'badge': '#b8860b',
    'rings': WHEEL_RING_COLOURS,
    'now': '#c00000',
    'strip_tint': STRIP_TINT,
    'strip_other': '#eeeeee',
}
# The dark ground is Streamlit's own default (#0e1117): st.context.theme
# reports the theme's type and not its colours, so the value is taken from
# the framework's default rather than guessed. The semantic colours move
# only as far as a dark ground requires -- the horizon stays blue, the
# meridian green, the cusps red, the badge gold, the sign band still four
# steps apart, each at the distance from the ground its light counterpart
# keeps from white.
_PALETTE_DARK = {
    'bg': '#0e1117',
    'panel': '#0e1117',
    'ink': '#fafafa',
    'rule': '#d2d6de',
    'leader': '#8b919b',
    'leader_ring': '#9aa1ac',
    'label': '#b4b9c2',
    'note': '#c2c7d0',
    'axis_note': '#a8adb6',
    'tints': ('#161a22', '#2f3440', '#202530', '#40485a'),
    'shade': '#2b313d',
    'bound_tint': '#584717',
    'axis': {0: '#7aa7ff', 6: '#7aa7ff', 9: '#5fcf5f', 3: '#5fcf5f'},
    'horizon': '#7aa7ff',
    'meridian': '#5fcf5f',
    'cusp': '#e0736f',
    'badge': '#e3b341',
    'rings': ('#fafafa', '#8ab4ff', '#f08a80'),
    'now': '#ff5f56',
    'strip_tint': {'Saturn': '#3a3a3a', 'Jupiter': '#25384f', 'Mars': '#4d2e2a', 'Sun': '#4d431c',
                   'Venus': '#26402a', 'Mercury': '#4a3a23', 'Moon': '#37304a'},
    'strip_other': '#2a2a2a',
}


def _wheel_palette(theme=None):
    """The colours a picture is drawn in. None -- and anything the viewer's
    browser does not report as dark -- is the palette the app has always
    used."""
    return _PALETTE_DARK if str(theme).lower() == 'dark' else _PALETTE_LIGHT


# What XML 1.0 forbids anywhere in a document, escaped or not: the C0
# controls other than tab, line feed and carriage return, U+FFFE and U+FFFF,
# and a lone surrogate. A name or place label holding one made the wheel
# SVG, and so its download, not well-formed.
_XML_ILLEGAL = re.compile('[\x00-\x08\x0b\x0c\x0e-\x1f\ud800-\udfff\ufffe\uffff]')


def _xml_legal(s):
    return _XML_ILLEGAL.sub('', str(s))


def _esc_attr(s):
    """A value on its way into an SVG attribute. Double quotes included: a
    Lot name carrying one closed the attribute and broke a whole wheel. The
    characters XML 1.0 forbids are dropped first."""
    return html.escape(_xml_legal(s), quote=True)


def _esc_text(s):
    """A value on its way into SVG text content. The characters XML 1.0
    forbids are dropped first."""
    return html.escape(_xml_legal(s))


# R4 of the lane's re-check: the bidirectional classes that can move text
# outside a name -- right-to-left letters, Arabic digits and the explicit
# embeddings, overrides and isolates (U+202A-U+202E, U+2066-U+2069; the
# marks U+200F and U+061C are right-to-left letters to the algorithm).
# Here, not in app.py, since lane SEC5 of the security release: the HTML
# export's heading and Place cells and the wheel's name and place isolate a
# typed name as the page and the Markdown export do (SB-08).
_BIDI_MOVERS = frozenset(("R", "AL", "AN", "LRE", "RLE", "LRO", "RLO", "PDF", "LRI", "RLI", "FSI", "PDI"))
_ISOLATE_OPENERS = "⁦⁧⁨"
_ISOLATE_CLOSER = "⁩"


def _isolated(text):
    """A name the page prints, kept from turning the app's own text around it
    (R4: "abc", RIGHT-TO-LEFT OVERRIDE, "def" drew the strip's date,
    time and coordinates backwards, and the readings question read right to
    left). A name holding a right-to-left letter, an Arabic digit or a
    directional control is set between FIRST STRONG ISOLATE and POP
    DIRECTIONAL ISOLATE: whatever it does to its own letters ends at the
    isolate's end, and the text after it reads in its own direction. Isolated
    rather than stripped, so the name is printed as typed, and so a name
    written right to left -- a Hebrew or an Arabic one, which needs no control
    at all -- cannot pull the separators beside it into its own direction.
    Inside the name, an isolate it opens and never closes is closed before
    the outer one, and a closing isolate with none open (which would end the
    outer isolate early) is dropped: it draws nothing. Every other name is
    returned as it is."""
    if not any(unicodedata.bidirectional(ch) in _BIDI_MOVERS for ch in text):
        return text
    depth, kept = 0, []
    for ch in text:
        if ch in _ISOLATE_OPENERS:
            depth += 1
        elif ch == _ISOLATE_CLOSER:
            if not depth:
                continue
            depth -= 1
        kept.append(ch)
    return "⁨" + "".join(kept) + _ISOLATE_CLOSER * depth + "⁩"


def generate_distribution_strip_svg(segments, now, unit='years', span=None, title='', theme=None):
    """segments as _pn4_distribute returns them (from/to/distributor/partner/
    partner_aspect); `now` in the strip's unit (completed years, or the day
    of the year) or None; span the bar's full length (120 years, 365 days
    ...). Each bar is <rect class="seg"> with data-from/to/distributor/
    partner; the present is <line class="now">. The segment the present
    falls in is outlined in the present's colour; a bound change is a
    full-height rule, a partner change a tick at the top; a bar too
    narrow for its glyph is left to its tint alone (2026-09-22)."""
    pal = _wheel_palette(theme)
    if unit not in ('years', 'days'):
        raise ValueError(f"unit must be 'years' or 'days', not {unit!r}")
    segments = list(segments or [])
    if span is None:
        span = max((s['to'] for s in segments), default=1.0)
    span = float(span) or 1.0
    x_left, x_right = 40.0, STRIP_WIDTH - 40.0
    y_top, y_bot = 78.0, 172.0

    def x_of(v):
        return x_left + (x_right - x_left) * max(0.0, min(1.0, v / span))

    svg = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {STRIP_WIDTH} {STRIP_HEIGHT}" width="{STRIP_WIDTH}" '
           f'height="{STRIP_HEIGHT}" style="font-family:{_WHEEL_FONT}">',
           f'<style>{font_face_css()}</style>',
           f'<rect width="{STRIP_WIDTH}" height="{STRIP_HEIGHT}" fill="{pal["bg"]}"/>']
    if title:
        svg.append(_svg_text(x_left, 30, _esc_text(title), 22, 'bold', pal['ink'], anchor='start'))
    current = None
    if now is not None:
        current = next((seg for seg in segments if seg['from'] <= now < seg['to']), None)
    rules, prev = [], None
    for seg in segments:
        x0, x1 = x_of(seg['from']), x_of(seg['to'])
        w = max(0.0, x1 - x0)
        tint = pal['strip_tint'].get(seg['distributor'], pal['strip_other'])
        svg.append(f'<rect class="seg" x="{x0:.1f}" y="{y_top}" width="{w:.1f}" height="{y_bot - y_top}" fill="{tint}" '
                   f'data-from="{seg["from"]:.4f}" data-to="{seg["to"]:.4f}" '
                   f'data-distributor="{_esc_attr(seg["distributor"])}" data-partner="{_esc_attr(pn4_result_text(seg["partner"], "none"))}" '
                   f'data-aspect="{_esc_attr(pn4_result_text(seg["partner_aspect"], "none"))}"/>')
        bound_change = prev is None or prev['distributor'] != seg['distributor']
        # The rules go on after the bars so no bar's fill covers a neighbour's edge.
        rules.append(_svg_line(x0, y_top, x0, y_bot if bound_change else y_top + 18,
                               pal['rule'], 1.6 if bound_change else 1.0))
        if w >= 18:
            svg.append(_svg_text((x0 + x1) / 2.0, y_top + 32, POINT_GLYPHS.get(seg['distributor'], '') + _VS, 30,
                                 fill=pal['ink']))
        if w >= 26 and is_unresolved(seg['partner']):
            svg.append(_svg_text((x0 + x1) / 2.0, y_bot - 22, '?', 18, fill=pal['note']))
        elif w >= 26 and seg['partner']:
            # Two or more partners met together (PN IV III.1, 50) are each
            # drawn, aspect and planet, in their order.
            together = isinstance(seg['partner'], PN4Together)
            pairs = zip(seg['partner'], seg['partner_aspect']) if together else ((seg['partner'], seg['partner_aspect']),)
            svg.append(_svg_text((x0 + x1) / 2.0, y_bot - 22,
                                 ''.join(_ASPECT_GLYPH.get(a, '') + POINT_GLYPHS.get(p, '') + _VS for p, a in pairs),
                                 19, fill=pal['note']))
        prev = seg
    svg.extend(rules)
    if current is not None:
        x0, x1 = x_of(current['from']), x_of(current['to'])
        svg.append(f'<rect class="current" x="{x0:.1f}" y="{y_top - 1.5}" width="{max(0.0, x1 - x0):.1f}" '
                   f'height="{y_bot - y_top + 3}" fill="none" stroke="{pal["now"]}" stroke-width="3"/>')
    svg.append(_svg_line(x_left, y_bot, x_right, y_bot, pal['rule'], 1.4))
    tick = 10.0 if unit == 'years' else 30.0
    v = 0.0
    while v <= span + 1e-9:
        x = x_of(v)
        svg.append(_svg_line(x, y_bot, x, y_bot + 8, pal['rule'], 1.0))
        svg.append(_svg_text(x, y_bot + 24, f'{v:g}', 15, fill=pal['ink']))
        v += tick
    svg.append(_svg_text(x_right, y_bot + 50, 'age in completed years' if unit == 'years' else 'day of the year',
                         14, fill=pal['axis_note'], anchor='end'))
    if now is not None and 0.0 <= now <= span:
        x = x_of(now)
        svg.append(f'<line class="now" x1="{x:.1f}" y1="{y_top - 20}" x2="{x:.1f}" y2="{y_bot + 8}" stroke="{pal["now"]}" '
                   f'stroke-width="2.6" data-now="{now:.4f}"/>')
        # The label beside the line, not on it; on whichever side has room.
        # A day prints as the Days page's Now line and its tables print it.
        # Years as the table and the header print them, truncated
        # (pn4_elapsed_text): "now: age 10.0" stood in the segment that
        # ends at 10, 9.9999 years elapsed (N11).
        places = pn4_span_places(current, unit)
        label = (f'now: age {pn4_elapsed_text(now, places)}' if unit == 'years'
                 else f'now: day {pn4_day_text(now, places)}')
        at_right = x > (x_left + x_right) / 2.0
        svg.append(_svg_text(x - 8 if at_right else x + 8, y_top - 30, label, 15, 'bold', pal['now'],
                             anchor='end' if at_right else 'start'))
    svg.append('</svg>')
    return ''.join(svg)


def generate_hit_strip_svg(rows, now, span=None, title='', theme=None):
    """The house-master's direction (Sahl, On Nativities 1.23, 2) as a
    strip in the family of generate_distribution_strip_svg: the same
    0-to-span axis in completed years, one tick per target reached
    (<line class="hit"> with data-arc/data-target), labelled with the
    infortune's glyph and the aspect's, alternating above and below the
    axis so neighbours do not collide; the present as <line class="now">.
    `rows` are sahl_house_master_direction's rows (Target, Arc (years))."""
    pal = _wheel_palette(theme)
    rows = list(rows or [])
    if span is None:
        span = max((float(r['Arc (years)']) for r in rows), default=1.0)
    span = float(span) or 1.0
    x_left, x_right = 40.0, STRIP_WIDTH - 40.0
    y_axis = 128.0

    def x_of(v):
        return x_left + (x_right - x_left) * max(0.0, min(1.0, v / span))

    def label_of(target):
        m = re.match(r"(?:the )?(\w+)'s (body|opposition|square|degree)", target)
        if not m:
            return _esc_text(target)
        planet, what = m.group(1), m.group(2)
        glyph = POINT_GLYPHS.get(planet, planet)
        return (glyph + _VS) if what == 'degree' else (_ASPECT_GLYPH.get(what, '') + glyph + _VS)

    svg = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {STRIP_WIDTH} {STRIP_HEIGHT}" width="{STRIP_WIDTH}" '
           f'height="{STRIP_HEIGHT}" style="font-family:{_WHEEL_FONT}">',
           f'<style>{font_face_css()}</style>',
           f'<rect width="{STRIP_WIDTH}" height="{STRIP_HEIGHT}" fill="{pal["bg"]}"/>']
    if title:
        svg.append(_svg_text(x_left, 30, _esc_text(title), 22, 'bold', pal['ink'], anchor='start'))
    svg.append(_svg_line(x_left, y_axis, x_right, y_axis, pal['rule'], 1.4))
    v = 0.0
    while v <= span + 1e-9:
        x = x_of(v)
        svg.append(_svg_line(x, y_axis, x, y_axis + 8, pal['rule'], 1.0))
        svg.append(_svg_text(x, y_axis + 24, f'{v:g}', 15, fill=pal['ink']))
        v += 10.0
    svg.append(_svg_text(x_right, y_axis + 50, 'age in completed years', 14, fill=pal['axis_note'], anchor='end'))
    for i, r in enumerate(sorted(rows, key=lambda r: float(r['Arc (years)']))):
        arc = float(r['Arc (years)'])
        if arc > span:
            continue
        x = x_of(arc)
        above = i % 2 == 0
        y0, y1 = (y_axis - 34, y_axis) if above else (y_axis, y_axis + 34)
        svg.append(f'<line class="hit" x1="{x:.1f}" y1="{y0}" x2="{x:.1f}" y2="{y1}" stroke="{pal["rule"]}" '
                   f'stroke-width="2" data-arc="{arc:.4f}" data-target="{_esc_attr(r["Target"])}"/>')
        svg.append(f'<circle cx="{x:.1f}" cy="{y_axis}" r="4" fill="{pal["rule"]}"/>')
        svg.append(_svg_text(x, y_axis - 50 if above else y_axis + 54, label_of(str(r['Target'])), 26, fill=pal['ink']))
        # The arc as the direction table prints it, truncated: "10.0" stood
        # for the table's 9.99 (N11).
        arc_text = (r['Arc (years)'] if isinstance(r['Arc (years)'], str)
                    else f"{math.floor(arc * 100.0) / 100.0:.2f}")
        svg.append(_svg_text(x, y_axis - 74 if above else y_axis + 78, _esc_text(arc_text), 14, fill=pal['note']))
    if now is not None and 0.0 <= now <= span:
        x = x_of(now)
        svg.append(f'<line class="now" x1="{x:.1f}" y1="{y_axis - 86}" x2="{x:.1f}" y2="{y_axis + 8}" stroke="{pal["now"]}" '
                   f'stroke-width="2.6" data-now="{now:.4f}"/>')
        at_right = x > (x_left + x_right) / 2.0
        svg.append(_svg_text(x - 8 if at_right else x + 8, y_axis - 96, f'now: age {pn4_elapsed_text(now)}', 15, 'bold', pal['now'],
                             anchor='end' if at_right else 'start'))
    svg.append('</svg>')
    return ''.join(svg)


def _export_cell(value):
    """One cell's text, shared by every export format so a reader of the
    Markdown, the HTML and the JSON is reading the same words (the format
    applies its own escaping on top). A report for a reader, not a Python
    dump (the hostile pass of 2026-09-22, L2): nothing prints as None, a
    flag prints as a word, a bare number to four places -- the JSON keeps
    the full value."""
    # PN4Together: two or more partners met together (PN IV III.1, 50).
    if (isinstance(value, dict)
            and value.get('result_type') in {'UnresolvedResult', 'YearsOutcome', 'PN4Together'}):
        return str(value['display'])
    if isinstance(value, (list, tuple)):
        return "; ".join(_export_cell(v) for v in value)
    if isinstance(value, dict) and {'n', 'facts'} <= value.keys() and ('sentence' in value or 'label' in value):
        # A testimony as the engine records it: {'n', 'sentence', 'facts'}
        # (and 'result' where the sentence's answer is typed).
        # Facts left open by an undecided connection follow the settled ones.
        # The sentence prints through this printer too: one left open by an
        # undecided connection arrives as the JSON's typed result and prints
        # by its display, as the result beside it does, not as a dict (the
        # re-pass of 2026-10-04, N-06).
        parts = [_export_cell(value.get('sentence', value.get('label'))),
                 _export_cell(list(value['facts']) + list(value.get('Unresolved facts', ())))
                 if isinstance(value['facts'], (list, tuple)) else _export_cell(value['facts'])]
        if value.get('result') is not None:
            parts.append(_export_cell(value['result']))
        return ": ".join(part for part in parts if part)
    if isinstance(value, dict):
        return json.dumps(value, ensure_ascii=False, sort_keys=True)
    if value is None:
        return ""
    if isinstance(value, bool):
        return "yes" if value else "no"
    if isinstance(value, CircleLongitude) and value == value:
        return degrees_text(value, 4, zodiac=True).rstrip("0").rstrip(".")
    if isinstance(value, float):
        if value != value:
            return "nan"
        # A value that rounds to zero prints 0, not "-0" (N04): no
        # unrounded value stands beside a bare cell to give the sign a
        # meaning (ruling 9 keeps "-0.00" only where one does, in _fact).
        text = f"{value:.4f}"
        if float(text) == 0.0:
            text = "0"
        return text.rstrip("0").rstrip(".") if "." in text else text
    return str(value)


