def eyesight_place_in_span(row, longitude):
    """True when longitude stands in the row's sign and inside its span:
    half-open for ordinal degrees, closed for a measured span."""
    longitude = _on_circle(longitude)   # K-16: -1e-16 is 0 Aries, not degree 30
    if get_zodiac_sign(longitude) != row['sign']:
        return False
    d = longitude % 30.0
    if row['closed']:
        return row['lo'] - 1e-9 <= d <= row['hi'] + 1e-9
    return row['lo'] <= d < row['hi']

def evaluate_eyesight_places(planetary_data, ascendant_lon):
    """The Moon and the lord of the Ascendant (6.2, 48), the Sun (69), and
    the Ascendant degree itself (this app's addition) against
    EYESIGHT_PLACES: a row per point per span it stands in, each text's
    span under its own source. The lord of the Ascendant is the domicile
    lord of the rising sign. Display only; nothing scores it, and the
    rule's further conditions ride in the 'Text' column."""
    asc_sign = get_zodiac_sign(ascendant_lon)
    asc_lord = next(pl for pl, signs in DOMICILES.items() if asc_sign in signs)
    checks = [('Sun', planetary_data['Sun']['longitude']), ('Moon', planetary_data['Moon']['longitude']),
              ('Ascendant', ascendant_lon)]
    if asc_lord in ('Sun', 'Moon'):
        # one row, both roles named
        checks = [(f'{pt} (the lord of the Ascendant)' if pt == asc_lord else pt, lon) for pt, lon in checks]
    elif asc_lord in planetary_data:
        checks.append((f'Lord of the Ascendant ({asc_lord})', planetary_data[asc_lord]['longitude']))
    results = []
    for point, lon in checks:
        for row in EYESIGHT_PLACES:
            if eyesight_place_in_span(row, lon):
                results.append({'Point': point, 'Position': get_degree_string(lon),
                                'Place': f"{row['place']} -- {row['printed']} ({row['reading']})",
                                'Source': f"{row['source']}, {row['sentence']}",
                                'Text': f"{row['sentence']}: {row['quote']} Rule -- {row['rule']}"})
    return results

def evaluate_special_degrees(planetary_data):
    """Flags planets in Sahl's dark signs, in the two signs of his burned
    place (no degrees -- see DARK_SIGNS above), in a classical welled
    degree of their current sign, or in one of Sahl's two sign-boundary
    conditions.

    The boundary pair is the other half of the five-degree rule and its
    mirror at the far end of the sign:

    ENTERING -- "every planet which is at the beginning of a sign is weak
    until it is firmly established in it and comes to be 5 degrees within
    it" (Fifty Aphorisms #44, 87), repeated as "the planets do not become
    powerful in the sign [they are in] until they travel 5 degrees in it"
    (On Nativities Ch.1.22, 9).

    LEAVING -- "if a planet came to be in the LAST degree of the sign, then
    its strength has already gone away from that sign, and its strength is
    in the next sign ... like a man putting his foot on the threshold of
    [his] door. And if a planet was in the twenty-ninth degree, then indeed
    the strength of the planet IS in that sign" (Fifty Aphorisms #15, 31-33).
    So the 29th degree still counts, and only the 30th has left."""
    planetary_data = _planets_on_circle(planetary_data)   # the seam reads as 0 Aries (K-16)
    results = []
    for planet, data in planetary_data.items():
        if planet == 'North Node': continue
        lon = data['longitude']
        conditions = []

        sign = get_zodiac_sign(lon)
        if sign in DARK_SIGNS:
            conditions.append("Dark sign (Intro Ch. 1, 18; Nat. 1.38, 8)")
        if sign in BURNED_PLACE_SIGNS:
            conditions.append('In the burned place\'s signs -- "the end of Libra and the beginning of '
                              'Scorpio", no degrees given (Intro Ch. 1, 19; Nat. 1.38, 9)')
        if ordinal_degree(lon) in WELLED_DEGREES.get(sign, []):
            conditions.append("Welled Degree")

        # Entering is a measured distance, five degrees into the sign; leaving
        # is an ordinal, the sign's last degree, the 30th (the 29th still
        # counts).
        if lon % 30.0 < 5.0:
            conditions.append("Not yet established in the sign (Aph. #44, 87)")
        elif ordinal_degree(lon) == 30:
            conditions.append("On the threshold; strength already in the next sign (Aph. #15, 31)")

        if conditions:
            results.append({
                'Planet': planet,
                'Position': get_degree_string(lon),
                'Condition': ", ".join(conditions),
            })
    return results

