def _brightness_category(lon):
    """The category of the run of whole degrees the longitude stands in: a
    stored (start, end) is the ordinal degrees start + 1 to end + 1 (see
    BRIGHTNESS_DEGREES)."""
    lon = _on_circle(lon)
    sign = get_zodiac_sign(lon)
    for start, end, category in BRIGHTNESS_DEGREES[sign]:
        if in_ordinal_degrees(lon, start + 1, end + 1):
            return category
    return 'Bright'  # unreachable if the table is complete, kept as a safe default

# Gr. Intr. VII.6, 19-20: for the five non-luminaries, the domicile
