def _sahl_1_20_grade(q, share, east, west, retro, rays, fall, night):
    """1.20, 10-34 as a decision on the facts; q is the DIVISION (1-12).
    Returns (sentence key, grade) or (None, None) where no sentence reaches."""
    enhanced = share and east and not retro and not rays
    if q in (1, 4, 7, 10):
        if rays and retro:
            return 21, 'lesser'
        if q in (1, 10, 7) and enhanced:
            return 10, 'greater'
        if q == 4 and enhanced:                 # 11: "under the earth, eastern, in one of its shares, ENHANCED"
            return 11, 'greater'
        if rays:
            return 18, 'middle'
        if not retro:
            return 20, 'middle'
        return None, None
    if q == 11:
        if enhanced:
            return 10, 'greater'
        if retro:
            if rays and fall:
                return 24, 'days and hours'
            if rays:
                return '23b', 'months'
            return 23, 'lesser'
        if not share and not east:
            return 17, 'middle'
        return None, None
    if q in (2, 8):
        if retro and rays:
            return 25, 'months'
        return 16, 'middle'
    if q == 5:
        if night and enhanced:                  # 11's parenthesis carries 11's "enhanced"
            return 11, 'greater'
        if retro:
            if rays and fall:
                return 24, 'days and hours'
            if rays:
                return '23b', 'months'
            return 23, 'lesser'
        if not share and not east:
            return 17, 'middle'
        return None, None
    if q == 9:
        if rays and retro:
            return 29, 'months'
        if share and east:
            return 26, 'middle'
        if not share and not east:
            return 27, 'lesser'
        return None, None
    if q == 3:
        if retro and rays and fall:
            return 34, 'hours'
        if retro and rays:
            return 33, 'days'
        if retro:
            return 32, 'months'
        if share:
            return 30, 'middle'
        if not east:
            return 31, 'lesser'
        return None, None
    if q in (6, 12):
        return 28, 'lesser'
    return None, None


def _sahl_house_master_years_branch(planet, planetary_data, cusps, sect, essential, moon_eastern=None):
    """One Sahl 1.20 route with lunar orientality fixed when supplied."""
    row = planetary_data.get(planet)
    if not row:
        return None
    lon = row['longitude'] % 360.0
    q = get_effective_house(lon, cusps)
    ess = essential.get(planet, {})
    share = any(ess.get(k) for k in ('Domicile', 'Exalt', 'Triplicity', 'Term', 'Face'))
    fall, exile = bool(ess.get('Fall')), bool(ess.get('Detriment'))
    burned = False
    if planet == 'Sun':
        east = west = rays = False
    else:
        phase, side = solar_phase(planet, lon, planetary_data['Sun']['longitude'], row.get('speed_in_lon'), source='Sahl')[:2]
        if planet == 'Moon' and moon_eastern is not None:
            east, west = moon_eastern, not moon_eastern
        else:
            east, west = side == 'eastern', side == 'western'
        rays = phase in ('Burned', 'Under the rays')
        # 1.21, 13 says "burned", and 1.20 grants years to a house-master
        # "under the rays" (18, 21, 23b, 25, 33, 34): the two words are kept
        # apart, the refusal keyed on the inner band alone -- the app's
        # Burned phase, a declared operational interpretation of the word,
        # not a definition 1.21, 13 supplies.
        burned = phase == 'Burned'
    retro = motion_state(planet, row.get('speed_in_lon')) == 'retrograde'
    night = sect != 'Diurnal'
    key, grade = _sahl_1_20_grade(q, share, east, west, retro, rays, fall, night)
    if key is None and not share and west:
        key, grade = (22, 'lesser') if retro else (19, 'middle as months and days')
    years = None
    unit = None
    if grade in ('greater', 'middle', 'lesser'):
        years, unit = PLANETARY_YEARS[planet][grade], 'years'
    elif grade == 'middle as months and days':
        years, unit = PLANETARY_YEARS[planet]['middle'], 'months and days'
    n = str(key).rstrip('b') if key is not None else None
    if key is None:
        text = f"1.20 silent: no sentence of 10-34 reaches {planet} in division {q} with these facts"
    elif years is not None:
        text = (f"the {grade} years, {years:g} ({planet}) -- 1.20, {n}: \"{SAHL_1_20_SENTENCES[key][1]}\"")
    else:
        text = (f"{grade} -- 1.20, {n}: \"{SAHL_1_20_SENTENCES[key][1]}\" (the count is not restated by the "
                f"sentence; none is invented)")
    flags = []
    if planet in ('Saturn', 'Jupiter', 'Mars') and (exile or west or retro or rays):
        flags.append('1.20, 14-15, printed and not applied (fn 156: "to me the meaning is still unclear"): "Know that exile, '
                     'setting, retrogradation, and burning do not stick to the superior planets, but they do stick to the '
                     'inferior planets. And if a superior one was in the condition which sticks to it, it is corrupting, for it '
                     'indicates its lesser years as months or days." \'Umar al-Tabari reads the pair by degree (Book of '
                     'Nativities I.4.3): one such condition does not harm a superior planet as it does an inferior, and a '
                     'superior under a serious impediment gives its lesser years as months or days; what makes an impediment '
                     'serious no text states, so the reading is carried here and not applied.')
    if q == 5 and planet == 'Venus':
        flags.append('1.20, 13 (Venus in her own shares in the fifth, eastern, the governor) is illegible in part and not applied.')
    # 1.21, 13 is a positive refusal, not 1.20's silence. Apply in the
    # shared route so lunar alternatives and the JN fallback cannot bypass it;
    # keyed on the burned band only, and 1.20's own indication kept visible
    # beside the qualification (both witnesses stand; one qualifies the result).
    indicated_1_20 = text
    if burned:
        grade, years, unit = 'no indication', None, None
        text = ('1.21, 13: burned, no indication — "And if the house-master was burned, '
                'it will not indicate anything." The JN fallback is not consulted: Sahl is not silent. '
                f'1.20 would have indicated: {indicated_1_20}. Burned here is this app\'s inner band of the rays '
                '(the Burned phase of its Sahl reading), a declared operational interpretation of the word; a house-master '
                'under the rays but not burned keeps 1.20\'s grant.')
        outcome = YearsOutcome('1.21, 13', grade, years, unit, text)
    else:
        outcome = YearsOutcome(f"1.20, {n}" if n else None, grade, years, unit, text)
    return {'grade': grade, 'sentence': outcome.sentence, 'years': years, 'text': text, 'flags': flags,
            'division': q, 'facts': {'share': share, 'eastern': east, 'westernizing': west, 'retrograde': retro,
                                     'under the rays': rays, 'burned': burned, 'fall': fall}, 'readings': SAHL_1_20_READINGS,
            'result': outcome, 'indicated_1_20': indicated_1_20,
            'indication': 'void' if burned else 'available' if grade else 'silent'}


def _lunar_orientation_evidence(source):
    """Unknown lunar orientality represented as inverse Boolean predicates."""
    eastern = UnresolvedResult(
        reason="the supplied passages do not define the Moon's orientality",
        source=source,
        alternatives=(('if the Moon is eastern', True), ('if the Moon is not eastern', False)),
    )
    westernizing = UnresolvedResult(
        reason="the supplied passages do not define the Moon's orientality",
        source=source,
        alternatives=(('if the Moon is eastern', False), ('if the Moon is not eastern', True)),
    )
    return eastern, westernizing


def sahl_house_master_years(planet, planetary_data, cusps, sect, essential):
    """The years On Nativities 1.20, 7-34 grants a house-master (Nawbakht;
    the section 1.23, 68 -- Masha'allah -- sends the reader to: "according
    to what I explained to you in the section on the house-master"). The
    corpus's ONE natal grant: On Times 4, 7 is stated for a question chart
    ("in the hour of the question", 4, 2) and is no natal rival (FINAL-A1,
    owner 2026-09-11, decision sheet row 1). The placement is the DIVISION
    (the POWER unit of the owner's ruling). Returns a dict: 'grade', 'sentence',
    'years' (the count where the grade names one), 'text' (the grade with
    its sentence quoted), 'flags' (14-15 printed where it would apply; 13),
    'division', 'readings'; None if the planet is absent. Not the Sun's
    grant only in the sense that the Sun has no solar phase.

    An open house-master (sahl_releaser's UnresolvedResult, the election
    turning on the Moon's orientality) takes the grant under each arm, the
    Moon's orientality fixed to that arm's value, and returns the same
    unresolved shape the Moon's own grant takes."""
    if is_unresolved(planet):
        return _sahl_house_master_years_open(planet, planetary_data, cusps, sect, essential)
    if planet != 'Moon':
        return _sahl_house_master_years_branch(planet, planetary_data, cusps, sect, essential)
    eastern = _sahl_house_master_years_branch(planet, planetary_data, cusps, sect, essential, True)
    western = _sahl_house_master_years_branch(planet, planetary_data, cusps, sect, essential, False)
    if eastern is None:
        return None
    eastern_evidence, western_evidence = _lunar_orientation_evidence(
        "Sahl, On Nativities 1.20; Abu 'Ali, Judgments of Nativities Ch. 3")
    if _same_years_outcome(eastern['result'], western['result']):
        resolved = dict(eastern)
        resolved['facts'] = dict(eastern['facts'], eastern=eastern_evidence, westernizing=western_evidence)
        return resolved
    result = UnresolvedResult(
        reason="the supplied passages do not define the Moon's orientality",
        source='Sahl, On Nativities 1.20, 10-34',
        alternatives=(('if the Moon is eastern', eastern['result']),
                      ('if the Moon is not eastern', western['result'])),
    )
    return {'grade': result, 'sentence': result, 'years': result, 'text': result,
            'flags': list(dict.fromkeys(eastern['flags'] + western['flags'])),
            'division': eastern['division'],
            'facts': dict(eastern['facts'], eastern=eastern_evidence, westernizing=western_evidence),
            'readings': SAHL_1_20_READINGS, 'result': result,
            'orientation_alternatives': (('if the Moon is eastern', eastern),
                                         ('if the Moon is not eastern', western))}

def _sahl_house_master_years_open(house_master, planetary_data, cusps, sect, essential):
    """The years of an election sahl_releaser left open on the Moon's
    orientality: one grant per arm, each arm's house-master with the Moon's
    orientality fixed to that arm (so the Moon elected 'if eastern' is
    graded eastern), carried as UnresolvedResults like the Moon's own grant."""
    arms = []
    for (name, hm), east in zip(house_master.alternatives, (True, False)):
        grant = (_sahl_house_master_years_branch(hm, planetary_data, cusps, sect, essential, moon_eastern=east)
                 if hm else None)
        arms.append((name, hm, grant))
    if all(grant is None for _n, _hm, grant in arms):
        return None

    def fork(key, absent, collapse=False):
        values = [(name, grant[key] if grant else absent) for name, _hm, grant in arms]
        if collapse and all(value == values[0][1] for _name, value in values):
            return values[0][1]
        return UnresolvedResult(reason=SAHL_MOON_ORIENTALITY_REASON, source=SAHL_MOON_ORIENTALITY_SOURCE,
                                alternatives=tuple(values))
    result = fork('result', SAHL_NO_HOUSE_MASTER)
    return {'grade': result, 'sentence': result, 'years': result, 'text': fork('text', SAHL_NO_HOUSE_MASTER),
            'flags': list(dict.fromkeys(f for _n, _hm, grant in arms if grant for f in grant['flags'])),
            'division': fork('division', None, collapse=True),
            'facts': fork('facts', {}, collapse=True),
            'readings': SAHL_1_20_READINGS, 'result': result,
            'orientation_alternatives': tuple((name, grant) for name, _hm, grant in arms)}

# --- Sahl, On Nativities 1.29, 11-12 and 1.26, 7: the Moon on the third day; 1.8-1.9: the fetus's stay ---
