def pn4_turning_planet_topics(sect):
    """VI.2, 2, 6 and 8: what each planet is turned for. The parents'
    indicators are the sect planets, "whichever one of the two had the
    shift in the root" (fn 16, 19)."""
    diurnal = sect == 'Diurnal'
    topics = {
        'Sun': 'rank, works, and authority (PN IV VI.2, 2)' + ('; the fathers (PN IV VI.2, 6)' if diurnal else ''),
        'Moon': 'the accidents of the body (PN IV VI.2, 2-3)' + ('' if diurnal else '; the mother (PN IV VI.2, 8)'),
        'Jupiter': 'assets (PN IV VI.2, 2)',
        'Venus': 'women, amusement, delight, and fornication (PN IV VI.2, 2)' + ('; the mother (PN IV VI.2, 8)' if diurnal else ''),
        'Saturn': 'what it indicates (PN IV VI.2, 2)' + ('' if diurnal else '; the fathers (PN IV VI.2, 6)'),
        'Mars': 'what it indicates (PN IV VI.2, 2)',
        'Mercury': 'what it indicates (PN IV VI.2, 2)',
    }
    return topics

def _pn4_natal_planets_in_sign(planetary_data, sign):
    """VI.2, 1: the "planetary fortune or infortune" a turned point
    reaches. Every natal planet in the sign, tagged."""
    found = []
    for planet in PN4_SEVEN:
        row = planetary_data.get(planet)
        if row and get_zodiac_sign(row['longitude']) == sign:
            tag = 'fortune' if planet in FORTUNES else 'infortune' if planet in INFORTUNES else 'neither'
            found.append(f"{planet} ({tag})")
    return ', '.join(found) if found else 'none'

def pn4_turned_sign(natal_lon, completed_years):
    """VI.2, 1: "a year for every sign", from the point's own position."""
    return get_zodiac_sign(pn4_profect(natal_lon, int(completed_years)))

def _pn4_condition_string(data, planet, *, compare_sahl=False):
    """A planet's condition as the II.3 examination prints it: sign, motion,
    side of the Sun, solar phase. '-' when the planet is absent."""
    r = data.get(planet)
    if not r:
        return '-'
    motion = motion_state(planet, r.get('speed_in_lon'))
    phase, side, _el = solar_phase(planet, r['longitude'], data['Sun']['longitude'], r.get('speed_in_lon'),
                                   latitude=r.get('latitude'))
    condition = f"{get_zodiac_sign(r['longitude'])}, {motion}, {side or '-'}{', ' + phase.lower() if phase else ''}"
    if compare_sahl:
        sahl_phase = solar_phase(planet, r['longitude'], data['Sun']['longitude'],
                                 r.get('speed_in_lon'), source='Sahl')[0]
        sahl_text = 'in the heart' if sahl_phase == 'Cazimi' else (sahl_phase or 'outside the solar bands').lower()
        if planet == 'Sun':
            sahl_text = 'the Sun itself; no solar testimony'
        return f"Abu Ma'shar (heart through 16′): {condition}; Sahl (heart through 1°): {sahl_text}"
    return condition

def _triplicity_lords_in_sect_order(sign, sect, *, table):
    """Order the named table's two principal lords by natal sect, then partner."""
    trip = triplicity_rulers(sign, table=table)
    if sect == 'Diurnal':
        return [trip['Day'], trip['Night'], trip['Participating']]
    return [trip['Night'], trip['Day'], trip['Participating']]


